import numpy as np
import random
import copy
from datetime import datetime
from typing import List, Dict, Tuple, Optional

# Extended 8-color processing times (hours)
PROCESSING_TIMES_GEN = {
    'ecru': 4, 'pink': 5, 'light': 6, 'medium': 8,
    'pastel': 10, 'brown': 12, 'beige': 13, 'dark': 14
}
COLOR_ORDER_GEN = ['ecru', 'pink', 'light', 'medium', 'pastel', 'brown', 'beige', 'dark']
SETUP_TIMES_BY_COLOR_GEN = {color: round(PROCESSING_TIMES_GEN[color] / 10, 2) for color in COLOR_ORDER_GEN}

def generate_setup_matrix_gen(colors: List[str] = None) -> Dict[Tuple[str, str], float]:
    if colors is None:
        colors = COLOR_ORDER_GEN
    setup_matrix = {}
    for from_color in colors:
        for to_color in colors:
            if from_color == to_color:
                setup_matrix[(from_color, to_color)] = 0.0
            else:
                setup_matrix[(from_color, to_color)] = SETUP_TIMES_BY_COLOR_GEN.get(from_color, 0.8)
    return setup_matrix

DIFFICULTY_PRESETS = {
    "EASY": {"description": "Loose due dates", "tightness": 0.2, "range": 0.6, "size_cv": 0.3,
             "customer_balance": "balanced", "color_balance": "balanced"},
    "MEDIUM": {"description": "Moderate tightness", "tightness": 0.4, "range": 0.4, "size_cv": 0.4,
               "customer_balance": "balanced", "color_balance": "balanced"},
    "HARD": {"description": "Tight due dates", "tightness": 0.6, "range": 0.3, "size_cv": 0.5,
             "customer_balance": "slightly_unbalanced", "color_balance": "slightly_unbalanced"},
    "VERY_HARD": {"description": "Very tight due dates", "tightness": 0.8, "range": 0.2, "size_cv": 0.5,
                  "customer_balance": "unbalanced", "color_balance": "unbalanced"},
    "BENCHMARK": {"description": "Standard benchmark", "tightness": 0.4, "range": 0.6, "size_cv": 0.4,
                  "customer_balance": "balanced", "color_balance": "balanced"}
}

class InstanceConfig:
    def __init__(self, num_jobs=30, num_machines=4, num_customers=3, num_colors=4,
                 machine_capacity=500, tightness=0.4, range_factor=0.6,
                 min_size=50, max_size=300, size_cv=0.4,
                 customer_balance="balanced", color_balance="balanced",
                 seed=None, instance_name=None, instance_id=1):
        self.num_jobs = num_jobs
        self.num_machines = num_machines
        self.num_customers = num_customers
        self.num_colors = min(num_colors, len(COLOR_ORDER_GEN))
        self.machine_capacity = machine_capacity
        self.tightness = tightness
        self.range_factor = range_factor
        self.min_size = min_size
        self.max_size = max_size
        self.size_cv = size_cv
        self.customer_balance = customer_balance
        self.color_balance = color_balance
        self.seed = seed if seed is not None else random.randint(1, 999999)
        self.instance_id = instance_id
        self.instance_name = instance_name or f"random_{num_jobs}j_{num_machines}m_{num_customers}c_{num_colors}f"

    @classmethod
    def from_preset(cls, preset, **overrides):
        if preset not in DIFFICULTY_PRESETS:
            raise ValueError(f"Unknown preset: {preset}")
        p = DIFFICULTY_PRESETS[preset]
        return cls(tightness=p["tightness"], range_factor=p["range"], size_cv=p["size_cv"],
                   customer_balance=p["customer_balance"], color_balance=p["color_balance"], **overrides)

    @classmethod
    def from_literature_benchmark(cls, instance_num=1):
        benchmarks = {
            1: {"num_jobs": 30, "num_machines": 3, "num_colors": 3, "num_customers": 3},
            2: {"num_jobs": 40, "num_machines": 4, "num_colors": 3, "num_customers": 4},
            3: {"num_jobs": 60, "num_machines": 5, "num_colors": 6, "num_customers": 5},
            4: {"num_jobs": 70, "num_machines": 6, "num_colors": 5, "num_customers": 6},
            5: {"num_jobs": 80, "num_machines": 6, "num_colors": 5, "num_customers": 6},
            6: {"num_jobs": 80, "num_machines": 8, "num_colors": 6, "num_customers": 6},
        }
        if instance_num not in benchmarks:
            raise ValueError(f"Instance {instance_num} not defined. Available: 1-6")
        return cls.from_preset("BENCHMARK", instance_id=instance_num, **benchmarks[instance_num])

    def to_dict(self):
        return {"instance_name": self.instance_name, "instance_id": self.instance_id,
                "num_jobs": self.num_jobs, "num_machines": self.num_machines,
                "num_customers": self.num_customers, "num_colors": self.num_colors,
                "machine_capacity": self.machine_capacity, "tightness": self.tightness,
                "range_factor": self.range_factor, "seed": self.seed}

class RandomInstanceGenerator:
    def __init__(self, config: InstanceConfig):
        self.config = config
        self.rng = np.random.RandomState(config.seed)
        random.seed(config.seed)
        self.colors = COLOR_ORDER_GEN[:config.num_colors]
        self.setup_matrix = generate_setup_matrix_gen(self.colors)

    @classmethod
    def from_preset(cls, preset, **overrides):
        return cls(InstanceConfig.from_preset(preset, **overrides))

    @classmethod
    def from_benchmark(cls, instance_num):
        return cls(InstanceConfig.from_literature_benchmark(instance_num))

    def generate(self):
        jobs = self._generate_jobs()
        machines = [{"id": i+1, "capacity": self.config.machine_capacity} for i in range(self.config.num_machines)]
        metadata = self._calculate_metadata(jobs, machines)
        return jobs, machines, metadata, self.setup_matrix

    def _generate_jobs(self):
        customer_assignments = self._generate_assignments(self.config.num_customers, self.config.customer_balance)
        color_assignments = self._generate_color_assignments()
        sizes = self._generate_job_sizes()
        P = self._calculate_expected_processing_time(color_assignments, sizes)
        due_dates = self._generate_due_dates_fisher(P)
        jobs = []
        for i in range(self.config.num_jobs):
            color = color_assignments[i]
            jobs.append({"id": i+1, "customer": customer_assignments[i], "size": sizes[i],
                        "color": color, "proc_time": PROCESSING_TIMES_GEN[color], "due_date": due_dates[i]})
        return jobs

    def _generate_assignments(self, num_groups, balance):
        n = self.config.num_jobs
        if balance == "balanced":
            base = n // num_groups
            remainder = n % num_groups
            assignments = []
            for i in range(num_groups):
                assignments.extend([i+1] * (base + (1 if i < remainder else 0)))
            self.rng.shuffle(assignments)
        else:
            low, high = (0.8, 1.2) if balance == "slightly_unbalanced" else (0.5, 2.0)
            weights = self.rng.uniform(low, high, num_groups)
            weights = weights / weights.sum()
            counts = np.maximum((weights * n).astype(int), 1)
            while counts.sum() != n:
                if counts.sum() < n:
                    counts[self.rng.randint(num_groups)] += 1
                else:
                    idx = self.rng.choice(np.where(counts > 1)[0])
                    counts[idx] -= 1
            assignments = []
            for i, c in enumerate(counts):
                assignments.extend([i+1] * c)
            self.rng.shuffle(assignments)
        return assignments

    def _generate_color_assignments(self):
        n, f = self.config.num_jobs, self.config.num_colors
        balance = self.config.color_balance
        if balance == "balanced":
            base = n // f
            remainder = n % f
            assignments = []
            for i in range(f):
                assignments.extend([self.colors[i]] * (base + (1 if i < remainder else 0)))
            self.rng.shuffle(assignments)
        else:
            low, high = (0.8, 1.2) if balance == "slightly_unbalanced" else (0.5, 2.0)
            weights = self.rng.uniform(low, high, f)
            weights = weights / weights.sum()
            counts = np.maximum((weights * n).astype(int), 1)
            while counts.sum() != n:
                if counts.sum() < n:
                    counts[self.rng.randint(f)] += 1
                else:
                    idx = self.rng.choice(np.where(counts > 1)[0])
                    counts[idx] -= 1
            assignments = []
            for i, c in enumerate(counts):
                assignments.extend([self.colors[i]] * c)
            self.rng.shuffle(assignments)
        return assignments

    def _generate_job_sizes(self):
        mean_size = (self.config.min_size + self.config.max_size) / 2
        std_size = mean_size * self.config.size_cv
        sizes = []
        for _ in range(self.config.num_jobs):
            while True:
                size = int(round(self.rng.normal(mean_size, std_size) / 10) * 10)
                if self.config.min_size <= size <= self.config.max_size:
                    sizes.append(size)
                    break
        return sizes

    def _calculate_expected_processing_time(self, color_assignments, sizes):
        total_proc = sum(PROCESSING_TIMES_GEN[c] for c in color_assignments)
        total_size = sum(sizes)
        est_batches = max(self.config.num_jobs // 3, int(np.ceil(total_size / self.config.machine_capacity)))
        avg_setup = np.mean([SETUP_TIMES_BY_COLOR_GEN[c] for c in self.colors])
        return (total_proc + avg_setup * est_batches * 0.5) / self.config.num_machines

    def _generate_due_dates_fisher(self, P):
        tau, R = self.config.tightness, self.config.range_factor
        return [max(1, int(round(P * (1 - tau - R/2) + P * R * self.rng.uniform(0, 1))))
                for _ in range(self.config.num_jobs)]

    def _calculate_metadata(self, jobs, machines):
        sizes = [j["size"] for j in jobs]
        dues = [j["due_date"] for j in jobs]
        procs = [j["proc_time"] for j in jobs]
        color_counts = {}
        customer_counts = {}
        for j in jobs:
            color_counts[j["color"]] = color_counts.get(j["color"], 0) + 1
            customer_counts[j["customer"]] = customer_counts.get(j["customer"], 0) + 1

        return {
            "name": self.config.instance_name, "instance_id": self.config.instance_id,
            "num_jobs": len(jobs), "num_machines": len(machines),
            "machine_capacity": self.config.machine_capacity,
            "num_customers": self.config.num_customers, "num_colors": self.config.num_colors,
            "colors": self.colors, "customers": list(customer_counts.keys()),
            "total_size": sum(sizes), "min_size": min(sizes), "max_size": max(sizes),
            "avg_size": np.mean(sizes), "std_size": np.std(sizes),
            "min_due_date": min(dues), "max_due_date": max(dues),
            "avg_due_date": np.mean(dues), "std_due_date": np.std(dues),
            "total_processing": sum(procs), "avg_processing": np.mean(procs),
            "color_distribution": color_counts, "customer_distribution": customer_counts,
            "capacity_utilization": sum(sizes) / (len(machines) * self.config.machine_capacity),
            "complexity_score": self.config.num_jobs * self.config.num_customers * self.config.num_colors / 100,
            "tightness_factor": self.config.tightness, "range_factor": self.config.range_factor,
            "seed": self.config.seed, "generated_at": datetime.now().isoformat(),
            "config": self.config.to_dict()
        }

    def generate_batch(self, num_instances, base_seed=None):
        if base_seed is None:
            base_seed = self.config.seed
        instances = []
        for i in range(num_instances):
            new_config = copy.copy(self.config)
            new_config.seed = base_seed + i
            new_config.instance_id = i + 1
            new_config.instance_name = f"{self.config.instance_name}_{i+1}"
            instances.append(RandomInstanceGenerator(new_config).generate())
        return instances

