def plot_pareto_front_comparison(pareto_data, config_name, output_prefix="scalability"):
    """Plot Pareto fronts comparing multiple approaches."""
    ext = _get_extension()
    save_kwargs = _get_save_kwargs()

    approach_colors= {
        'FFD+SA-EDDTS': '#FFEAA7', 'ALNS': '#DDA0DD', 'NSGA-II': '#D35400', 'INTEGRATED': '#FF6B6B',
        'MILP1+MILP2': '#4ECDC4', 'FFD+SA-MILP2': '#45B7D1', 'MILP1+EDDTS': '#96CEB4', 'NSGA-II': '#D35400',
        'LPT+EDD': '#2C3E50',
    }
    approach_markers = {
        'FFD+SA-EDDTS': 'o', 'ALNS': 's', 'NSGA-II': 'h', 'LPT+EDD': 'X', 'INTEGRATED': '^',
        'MILP1+MILP2': 'D', 'FFD+SA-MILP2': 'v', 'MILP1+EDDTS': 'p', 'NSGA-II': 'D', 'LPT+EDD': 'X',
    }
    rep_linestyles = {1: '-', 2: '--', 3: ':', 4: '-.', 5: (0, (3, 1, 1, 1))}

    fig, ax = plt.subplots(figsize=(10, 7))

    for approach_name, rep_data in pareto_data.items():
        color = approach_colors.get(approach_name, '#999999')
        marker = approach_markers.get(approach_name, 'o')
        for rep_key, points in rep_data.items():
            if not points:
                continue
            points_sorted = sorted(points, key=lambda x: x[0])
            tardiness = [p[0] for p in points_sorted]
            setup = [p[1] for p in points_sorted]
            try:
                rep_idx = int(str(rep_key).split('_')[-1])
            except:
                rep_idx = 1
            linestyle = rep_linestyles.get(rep_idx, '-')
            label = f"{approach_name} (Rep {rep_idx})"
            ax.plot(tardiness, setup, marker=marker, color=color,
                   linestyle=linestyle, linewidth=2, markersize=8,
                   label=label, markeredgecolor='white', markeredgewidth=1)

    ax.set_xlabel('Total Tardiness', fontsize=12, fontweight='bold')
    ax.set_ylabel('Total Setup Time', fontsize=12, fontweight='bold')
    ax.set_title(f'Pareto Front Comparison\n{config_name}', fontsize=14, fontweight='bold')
    ax.grid(True, alpha=0.3)
    ax.legend(loc='upper right', fontsize=9)
    ax.annotate('Ideal\n(0,0)', xy=(0, 0), xytext=(0.05, 0.05),
               textcoords='axes fraction', fontsize=9, color='gray',
               arrowprops=dict(arrowstyle='->', color='gray', alpha=0.5))

    plt.tight_layout()

    timestamp = time.strftime("%Y%m%d-%H%M%S")
    safe_name = config_name.replace(' ', '_').replace(',', '').replace('/', '-')
    filename = f"{output_prefix}_pareto_{safe_name}_{timestamp}.{ext}"
    plt.savefig(filename, **save_kwargs)
    plt.show()
    print(f"✓ Pareto front figure saved to '{filename}'")
    return filename


