# GANTT CHART VISUALIZATION - FIXED VERSION
# ============================================================================

def plot_schedule_gantt(schedule, jobs=None, title="Production Schedule - Gantt Chart",
                        show_due_dates=True, show_job_ids=True, save_path=None,
                        due_date_display='compact'):
    """
    Create a comprehensive Gantt chart for textile batch scheduling.

    Parameters:
    -----------
    schedule : list
        Schedule data structure from optimization algorithms
    jobs : list, optional
        Original job list for due date information
    title : str
        Chart title
    show_due_dates : bool
        Whether to show due date markers
    show_job_ids : bool
        Whether to show job IDs within batches
    save_path : str, optional
        Path to save the figure
    due_date_display : str
        'compact' - Show due dates in a compact legend (default, recommended)
        'lines' - Show due date lines on chart (can stretch if dues >> makespan)
        'none' - Don't show due dates

    Returns:
    --------
    matplotlib.figure.Figure
    """
    import matplotlib.pyplot as plt
    import matplotlib.patches as mpatches
    from matplotlib.patches import Rectangle, FancyBboxPatch
    import numpy as np

    ext = _get_extension()
    save_kwargs = _get_save_kwargs()

    if not schedule:
        print("⚠ Warning: Empty schedule provided")
        return None

    COLOR_PALETTE = {
        'ecru': '#F5F5DC', 'pink': '#FFB6C1', 'light': '#90EE90',
        'medium': '#87CEEB', 'pastel': '#DDA0DD', 'brown': '#D2691E',
        'beige': '#F5DEB3', 'dark': '#696969', 'unknown': '#C0C0C0'
    }
    SETUP_COLOR = '#FF6B6B'

    sorted_schedule = sorted(schedule, key=lambda m: m.get("machine_id", 0))
    num_machines = len(sorted_schedule)

    # Calculate statistics
    makespan = 0
    total_tardiness = 0
    total_setup = 0
    total_batches = 0
    late_batches = 0
    all_due_dates = set()

    for machine in sorted_schedule:
        for batch in machine.get("batches", []):
            completion = batch.get("completion_time", 0)
            makespan = max(makespan, completion)
            total_tardiness += batch.get("tardiness", 0)
            total_setup += batch.get("setup_time", 0)
            total_batches += 1
            if batch.get("tardiness", 0) > 0:
                late_batches += 1
            # Collect due dates
            due_date = batch.get("due_date", None)
            if due_date is not None and due_date < float('inf'):
                all_due_dates.add(due_date)

    # Determine x-axis limit based on display mode
    if due_date_display == 'lines' and all_due_dates:
        max_due = max(all_due_dates)
        # Only extend if due dates are reasonably close to makespan
        if max_due <= makespan * 2.5:
            x_max = max(makespan, max_due) * 1.1
        else:
            # Due dates are too far, switch to compact mode
            x_max = makespan * 1.15
            due_date_display = 'compact'  # Override to compact
            print(f"  Note: Due dates far from makespan, using compact display")
    else:
        x_max = makespan * 1.15

    fig_height = max(8, num_machines * 2 + 3)
    fig, ax = plt.subplots(figsize=(18, fig_height))

    y_spacing = 2.5
    bar_height = 1.8

    job_due_dates = {}
    if jobs:
        for job in jobs:
            job_id = job.get('id', job.get('job_id'))
            job_due_dates[job_id] = job.get('due_date', float('inf'))

    due_date_lines = set()

    # Plot each machine
    for m_idx, machine in enumerate(sorted_schedule):
        y_pos = m_idx * y_spacing
        machine_id = machine.get("machine_id", m_idx + 1)
        batches = machine.get("batches", [])

        for batch in batches:
            batch_id = batch.get("batch_id", batch.get("id", "?"))
            family = batch.get("family", batch.get("color", "unknown"))
            start_time = batch.get("start_time", 0)
            setup_time = batch.get("setup_time", 0)
            proc_time = batch.get("proc_time", 0)
            completion_time = batch.get("completion_time", start_time + setup_time + proc_time)
            tardiness = batch.get("tardiness", 0)
            due_date = batch.get("due_date", float('inf'))
            batch_jobs = batch.get("jobs", [])
            batch_size = batch.get("size", 0)

            bar_color = COLOR_PALETTE.get(family.lower() if isinstance(family, str) else 'unknown',
                                          COLOR_PALETTE['unknown'])

            # Draw setup time bar (if any)
            if setup_time > 0:
                setup_start = start_time - setup_time
                setup_rect = FancyBboxPatch(
                    (setup_start, y_pos - bar_height/2),
                    setup_time, bar_height,
                    boxstyle="round,pad=0.02,rounding_size=0.1",
                    facecolor=SETUP_COLOR,
                    edgecolor='darkred',
                    linewidth=1.5,
                    alpha=0.9,
                    zorder=2
                )
                ax.add_patch(setup_rect)
                if setup_time >= 0.4:
                    ax.text(setup_start + setup_time/2, y_pos,
                           f"S:{setup_time:.1f}",
                           ha='center', va='center',
                           fontsize=7, fontweight='bold', color='white',
                           zorder=3)

            # Draw processing time bar
            proc_start = start_time
            if tardiness > 0:
                edge_color = 'red'
                edge_width = 3
            else:
                edge_color = 'black'
                edge_width = 1.5

            proc_rect = FancyBboxPatch(
                (proc_start, y_pos - bar_height/2),
                proc_time, bar_height,
                boxstyle="round,pad=0.02,rounding_size=0.15",
                facecolor=bar_color,
                edgecolor=edge_color,
                linewidth=edge_width,
                alpha=0.85,
                zorder=2
            )
            ax.add_patch(proc_rect)

            # Labels
            label_text = f"B{batch_id}"
            family_short = family[:3].upper() if isinstance(family, str) else "?"
            text_x = proc_start + proc_time/2

            ax.text(text_x, y_pos + 0.35, label_text,
                   ha='center', va='center',
                   fontsize=10, fontweight='bold', color='black',
                   zorder=3)

            ax.text(text_x, y_pos - 0.1, family_short,
                   ha='center', va='center',
                   fontsize=8, style='italic', color='darkblue',
                   zorder=3)

            if batch_size > 0:
                size_text = f"{batch_size}kg"
                ax.text(text_x, y_pos - 0.55, size_text,
                       ha='center', va='center',
                       fontsize=7, color='gray',
                       zorder=3)

            # Job IDs
            if show_job_ids and batch_jobs and proc_time >= 2:
                job_ids = []
                for job in batch_jobs:
                    if isinstance(job, dict):
                        job_id = job.get('id') or job.get('job_id') or job.get('ID') or '?'
                        job_ids.append(str(job_id))
                    else:
                        job_ids.append(str(job))
                job_ids = [jid for jid in job_ids if jid != '?']

                if job_ids:
                    if len(job_ids) <= 4:
                        jobs_text = "J:" + ",".join(job_ids)
                    else:
                        jobs_text = f"J:{job_ids[0]}..{job_ids[-1]} ({len(job_ids)})"
                    ax.text(text_x, y_pos + 0.75, jobs_text,
                           ha='center', va='center',
                           fontsize=6, color='darkgreen',
                           zorder=3)

            # Tardiness indicator
            if tardiness > 0:
                ax.text(completion_time + 0.3, y_pos, f"⚠+{tardiness:.1f}h",
                       ha='left', va='center',
                       fontsize=8, fontweight='bold', color='red',
                       zorder=3)

            # Track due date for this batch
            if show_due_dates and due_date < float('inf'):
                due_date_lines.add(due_date)

    # Draw due date lines (only if using 'lines' mode and within range)
    if due_date_display == 'lines' and due_date_lines:
        for dd in sorted(due_date_lines):
            if dd <= x_max:  # Only draw if within visible range
                ax.axvline(x=dd, color='purple', linestyle='--',
                          linewidth=1.5, alpha=0.6, zorder=1)
                ax.text(dd, num_machines * y_spacing + 0.3, f"D={dd:.0f}",
                       ha='center', va='bottom',
                       fontsize=8, color='purple', rotation=45)

    # Draw makespan line
    ax.axvline(x=makespan, color='green', linestyle='-',
              linewidth=2, alpha=0.8, zorder=1)
    ax.text(makespan + 0.5, num_machines * y_spacing / 2,
           f"Makespan\n{makespan:.1f}h",
           ha='left', va='center',
           fontsize=9, fontweight='bold', color='green',
           bbox=dict(boxstyle='round', facecolor='lightgreen', alpha=0.7))

    # Y-axis labels
    y_ticks = [m_idx * y_spacing for m_idx in range(num_machines)]
    y_labels = [f"Machine {m.get('machine_id', i+1)}\n({m.get('capacity', 'N/A')} kg)"
                for i, m in enumerate(sorted_schedule)]
    ax.set_yticks(y_ticks)
    ax.set_yticklabels(y_labels, fontsize=11, fontweight='bold')

    # Axis limits
    ax.set_xlim(-1, x_max)
    ax.set_ylim(-1.5, num_machines * y_spacing + 1)
    ax.set_xlabel('Time (hours)', fontsize=13, fontweight='bold')
    ax.set_title(title, fontsize=15, fontweight='bold', pad=15)

    # Grid
    ax.grid(True, axis='x', linestyle='--', alpha=0.4, zorder=0)
    ax.set_axisbelow(True)

    # Create legend
    legend_elements = [
        mpatches.Patch(facecolor=SETUP_COLOR, edgecolor='darkred',
                      label='Setup Time', alpha=0.9),
        mpatches.Patch(facecolor='white', edgecolor='red', linewidth=2,
                      label='Late Batch (Tardiness > 0)'),
        plt.Line2D([0], [0], color='green', linestyle='-', linewidth=2,
                  label='Makespan'),
    ]

    # Add due date to legend if using lines mode
    if due_date_display == 'lines':
        legend_elements.append(
            plt.Line2D([0], [0], color='purple', linestyle='--', linewidth=1.5,
                      label='Due Date')
        )

    # Add color legend for fabric types
    used_colors = set()
    for machine in sorted_schedule:
        for batch in machine.get("batches", []):
            family = batch.get("family", batch.get("color", ""))
            if family:
                used_colors.add(family.lower() if isinstance(family, str) else family)

    for color_name in sorted(used_colors):
        if color_name in COLOR_PALETTE:
            legend_elements.append(
                mpatches.Patch(facecolor=COLOR_PALETTE[color_name],
                              edgecolor='black', linewidth=1,
                              label=f'{color_name.capitalize()}')
            )

    ax.legend(handles=legend_elements, loc='upper right',
             fontsize=9, framealpha=0.95, ncol=2)

    # Statistics box - UPDATED to include due date info
    if due_date_lines:
        min_due = min(due_date_lines)
        max_due = max(due_date_lines)
        due_info = f"Due Dates: {min_due:.0f}h - {max_due:.0f}h\n"
    else:
        due_info = ""

    stats_text = (
        f"Summary Statistics\n"
        f"─────────────────\n"
        f"Total Batches: {total_batches}\n"
        f"Late Batches: {late_batches} ({100*late_batches/max(1,total_batches):.0f}%)\n"
        f"Total Tardiness: {total_tardiness:.1f}h\n"
        f"Total Setup Time: {total_setup:.1f}h\n"
        f"Makespan: {makespan:.1f}h\n"
        f"{due_info}"
    )

    props = dict(boxstyle='round,pad=0.5', facecolor='lightyellow',
                edgecolor='orange', alpha=0.9)
    ax.text(0.02, 0.98, stats_text, transform=ax.transAxes,
           fontsize=9, verticalalignment='top',
           fontfamily='monospace', bbox=props)

    plt.tight_layout()

    if save_path:
        if '.' in save_path:
            actual_path = save_path
        else:
            actual_path = f"{save_path}.{ext}"
        plt.savefig(actual_path, **save_kwargs)
        print(f"✓ Gantt chart saved to '{actual_path}'")

    return fig


def plot_best_schedule_from_pareto(pareto_solutions, jobs=None,
                                    criterion='tardiness',
                                    title_prefix="Best Schedule",
                                    due_date_display='compact'):
    """Plot the Gantt chart for the best solution from Pareto front."""
    if not pareto_solutions:
        print("⚠ No Pareto solutions available")
        return None

    if criterion == 'tardiness':
        best_sol = min(pareto_solutions, key=lambda s: s.get('tardiness', float('inf')))
        title = f"{title_prefix} (Min Tardiness = {best_sol['tardiness']:.1f}h)"
    else:
        best_sol = min(pareto_solutions, key=lambda s: s.get('setup_time', float('inf')))
        title = f"{title_prefix} (Min Setup = {best_sol['setup_time']:.1f}h)"

    schedule = best_sol.get('schedule')
    if not schedule:
        print("⚠ No schedule data in solution")
        return None

    return plot_schedule_gantt(schedule, jobs=jobs, title=title,
                               due_date_display=due_date_display)


def visualize_pareto_schedules(pareto_solutions, jobs=None, max_schedules=3,
                               due_date_display='compact'):
    """Visualize multiple schedules from Pareto front."""
    if not pareto_solutions:
        print("⚠ No Pareto solutions available")
        return []

    figures = []
    n_solutions = len(pareto_solutions)

    if n_solutions <= max_schedules:
        selected_indices = list(range(n_solutions))
    else:
        sorted_by_tard = sorted(range(n_solutions),
                                key=lambda i: pareto_solutions[i].get('tardiness', float('inf')))
        sorted_by_setup = sorted(range(n_solutions),
                                 key=lambda i: pareto_solutions[i].get('setup_time', float('inf')))
        selected_indices = [sorted_by_tard[0], sorted_by_setup[0]]
        if max_schedules > 2 and n_solutions > 2:
            middle_idx = n_solutions // 2
            if middle_idx not in selected_indices:
                selected_indices.append(middle_idx)
        selected_indices = list(set(selected_indices))[:max_schedules]

    for i, idx in enumerate(selected_indices):
        sol = pareto_solutions[idx]
        schedule = sol.get('schedule')
        if not schedule:
            continue
        tard = sol.get('tardiness', 0)
        setup = sol.get('setup_time', 0)
        point_id = sol.get('point_id', idx + 1)
        title = f"Pareto Point {point_id}: Tardiness={tard:.1f}h, Setup={setup:.1f}h"
        fig = plot_schedule_gantt(schedule, jobs=jobs, title=title,
                                  due_date_display=due_date_display)
        if fig:
            figures.append(fig)
            plt.show()

    return figures


