def visualize_mode4_results_with_gantt(all_results, comparison_df, dataset_name,
                                        jobs=None, save_prefix="mode4",
                                        show_gantt=True, gantt_criterion='tardiness',
                                        due_date_display='compact'):
    """Generate comprehensive visualizations for MODE 4 results INCLUDING Gantt chart."""
    timestamp = time.strftime("%Y%m%d-%H%M%S")
    ext = _get_extension()
    save_kwargs = _get_save_kwargs()
    saved_files = []

    valid_results = {k: v for k, v in all_results.items() if v is not None}

    if not valid_results:
        print("No valid results to visualize")
        return saved_files

    print(f"\n{'='*60}")
    print(f"GENERATING MODE 4 VISUALIZATIONS FOR: {dataset_name}")
    print(f"Output format: {OUTPUT_FORMAT.upper()}")
    print(f"{'='*60}")

    # 1. Main comparison
    fig1 = plot_mode4_main_comparison(valid_results, comparison_df, dataset_name)
    filename1 = f"{save_prefix}_{dataset_name}_comparison_{timestamp}.{ext}"
    fig1.savefig(filename1, **save_kwargs)
    plt.show()
    plt.close(fig1)
    saved_files.append(filename1)
    print(f"✓ Main comparison saved to '{filename1}'")

    # 2. Detailed Pareto front
    fig2 = plot_mode4_pareto_detailed(valid_results, dataset_name)
    filename2 = f"{save_prefix}_{dataset_name}_pareto_{timestamp}.{ext}"
    fig2.savefig(filename2, **save_kwargs)
    plt.show()
    plt.close(fig2)
    saved_files.append(filename2)
    print(f"✓ Detailed Pareto front saved to '{filename2}'")

    # 3. Performance heatmap
    if len(valid_results) >= 2:
        fig3 = plot_mode4_performance_heatmap(comparison_df, dataset_name)
        filename3 = f"{save_prefix}_{dataset_name}_heatmap_{timestamp}.{ext}"
        fig3.savefig(filename3, **save_kwargs)
        plt.show()
        plt.close(fig3)
        saved_files.append(filename3)
        print(f"✓ Performance heatmap saved to '{filename3}'")

    # 4. Gantt Chart
    if show_gantt:
        print(f"\n--- Generating Gantt Chart (Best {gantt_criterion.capitalize()}) ---")

        best_solution = None
        best_approach = None
        best_value = float('inf')

        for approach_name, results in valid_results.items():
            if results is None or 'pareto_solutions' not in results:
                continue
            for sol in results['pareto_solutions']:
                if gantt_criterion == 'tardiness':
                    val = sol.get('tardiness', float('inf'))
                else:
                    val = sol.get('setup_time', float('inf'))
                if val < best_value:
                    best_value = val
                    best_solution = sol
                    best_approach = approach_name

        if best_solution and best_solution.get('schedule'):
            tard = best_solution.get('tardiness', 0)
            setup = best_solution.get('setup_time', 0)
            title = (f"Best Schedule: {dataset_name}\n"
                    f"Approach: {best_approach} | "
                    f"Tardiness: {tard:.1f}h | Setup: {setup:.1f}h")

            fig4 = plot_schedule_gantt(
                best_solution['schedule'],
                jobs=jobs,
                title=title,
                due_date_display=due_date_display
            )

            if fig4:
                filename4 = f"{save_prefix}_{dataset_name}_gantt_{timestamp}.{ext}"
                fig4.savefig(filename4, **save_kwargs)
                plt.show()
                plt.close(fig4)
                saved_files.append(filename4)
                print(f"✓ Gantt chart saved to '{filename4}'")
        else:
            print("⚠ No schedule data available for Gantt chart")

    print(f"{'='*60}\n")
    return saved_files


