def print_job_batch_assignment(schedule, title="JOB-BATCH ASSIGNMENT TABLE"):
    """Print a detailed table showing which jobs are assigned to which batches."""
    print(f"\n{'='*80}")
    print(f"{title}")
    print(f"{'='*80}")

    if not schedule:
        print("  No schedule data available")
        return

    all_batches = []
    for machine in schedule:
        machine_id = machine.get("machine_id", "?")
        for batch in machine.get("batches", []):
            batch_id = batch.get("batch_id", batch.get("id", "?"))
            family = batch.get("family", batch.get("color", "?"))
            customer = batch.get("customer", "?")
            size = batch.get("size", 0)
            proc_time = batch.get("proc_time", 0)
            start_time = batch.get("start_time", 0)
            completion_time = batch.get("completion_time", 0)
            setup_time = batch.get("setup_time", 0)
            due_date = batch.get("due_date", "?")
            tardiness = batch.get("tardiness", 0)

            batch_jobs = batch.get("jobs", [])
            job_ids = []
            for job in batch_jobs:
                if isinstance(job, dict):
                    job_id = job.get('id') or job.get('job_id') or job.get('ID')
                    if job_id:
                        job_ids.append(str(job_id))
                else:
                    job_ids.append(str(job))

            all_batches.append({
                'machine': machine_id,
                'batch': batch_id,
                'color': family,
                'customer': customer,
                'jobs': job_ids,
                'num_jobs': len(job_ids),
                'size': size,
                'proc_time': proc_time,
                'start': start_time,
                'end': completion_time,
                'setup': setup_time,
                'due_date': due_date,
                'tardiness': tardiness
            })

    all_batches.sort(key=lambda x: (x['machine'], x['start']))

    print(f"\n{'Machine':<10} {'Batch':<7} {'Color':<8} {'Cust':<6} {'Jobs':<20} {'Size':<8} {'Start':<8} {'End':<8} {'Setup':<7} {'Due':<7} {'Tard':<6}")
    print("-" * 105)

    current_machine = None
    for b in all_batches:
        if current_machine is not None and b['machine'] != current_machine:
            print("-" * 105)
        current_machine = b['machine']

        if len(b['jobs']) <= 4:
            jobs_str = ",".join(b['jobs']) if b['jobs'] else "-"
        else:
            jobs_str = f"{b['jobs'][0]}..{b['jobs'][-1]} ({b['num_jobs']})"

        tard_str = f"{b['tardiness']:.1f}" if b['tardiness'] > 0 else "0"
        if b['tardiness'] > 0:
            tard_str += " ⚠"

        print(f"M{b['machine']:<9} B{b['batch']:<6} {str(b['color'])[:7]:<8} {b['customer']:<6} {jobs_str:<20} {b['size']:<8.0f} {b['start']:<8.1f} {b['end']:<8.1f} {b['setup']:<7.1f} {str(b['due_date']):<7} {tard_str:<6}")

    print("-" * 105)

    total_batches = len(all_batches)
    total_jobs = sum(b['num_jobs'] for b in all_batches)
    total_tardiness = sum(b['tardiness'] for b in all_batches)
    total_setup = sum(b['setup'] for b in all_batches)
    late_batches = sum(1 for b in all_batches if b['tardiness'] > 0)
    makespan = max(b['end'] for b in all_batches) if all_batches else 0

    print(f"\nSUMMARY:")
    print(f"  Total Batches: {total_batches}")
    print(f"  Total Jobs: {total_jobs}")
    print(f"  Late Batches: {late_batches} ({100*late_batches/max(1,total_batches):.1f}%)")
    print(f"  Total Tardiness: {total_tardiness:.2f}h")
    print(f"  Total Setup Time: {total_setup:.2f}h")
    print(f"  Makespan: {makespan:.2f}h")
    print(f"{'='*80}\n")

    return all_batches


def print_job_details(schedule, jobs=None, title="DETAILED JOB SCHEDULE"):
    """Print detailed information for each job."""
    print(f"\n{'='*80}")
    print(f"{title}")
    print(f"{'='*80}")

    if not schedule:
        print("  No schedule data available")
        return

    job_lookup = {}
    if jobs:
        for job in jobs:
            job_id = job.get('id', job.get('job_id'))
            job_lookup[str(job_id)] = job

    all_jobs = []
    for machine in schedule:
        machine_id = machine.get("machine_id", "?")
        for batch in machine.get("batches", []):
            batch_id = batch.get("batch_id", batch.get("id", "?"))
            family = batch.get("family", batch.get("color", "?"))
            completion_time = batch.get("completion_time", 0)

            batch_jobs = batch.get("jobs", [])
            for job in batch_jobs:
                if isinstance(job, dict):
                    job_id = str(job.get('id') or job.get('job_id') or '?')
                    job_due = job.get('due_date', '?')
                    job_tard = job.get('tardiness', 0)
                else:
                    job_id = str(job)
                    job_due = '?'
                    job_tard = 0

                original = job_lookup.get(job_id, {})
                size = original.get('size', '?')
                customer = original.get('customer', batch.get('customer', '?'))

                all_jobs.append({
                    'job_id': job_id,
                    'batch_id': batch_id,
                    'machine_id': machine_id,
                    'color': family,
                    'customer': customer,
                    'size': size,
                    'due_date': job_due,
                    'completion': completion_time,
                    'tardiness': job_tard
                })

    all_jobs.sort(key=lambda x: int(x['job_id']) if x['job_id'].isdigit() else 0)

    print(f"\n{'Job':<6} {'Batch':<7} {'Machine':<9} {'Color':<8} {'Cust':<6} {'Size':<8} {'Due':<8} {'Complete':<10} {'Tardiness':<10}")
    print("-" * 85)

    for j in all_jobs:
        tard_str = f"{j['tardiness']:.1f}" if j['tardiness'] > 0 else "0"
        if j['tardiness'] > 0:
            tard_str += " ⚠"
        size_str = f"{j['size']}" if j['size'] != '?' else "?"
        print(f"J{j['job_id']:<5} B{j['batch_id']:<6} M{j['machine_id']:<8} {str(j['color'])[:7]:<8} {j['customer']:<6} {size_str:<8} {j['due_date']:<8} {j['completion']:<10.1f} {tard_str:<10}")

    print("-" * 85)
    print(f"{'='*80}\n")


