def get_solver(solver_name='highs', time_limit=1200):
    """Create solver instance with appropriate options"""
    if not PYOMO_AVAILABLE:
        raise RuntimeError("Pyomo is not available. Cannot create solver.")

    try:
        solver = pyo.SolverFactory(solver_name)

        if not solver.available():
            print(f"WARNING: {solver_name} not available, trying alternatives...")
            if solver_name == 'highs':
                solver = pyo.SolverFactory('appsi_highs')
                if solver.available():
                    solver_name = 'appsi_highs'
                else:
                    solver = pyo.SolverFactory('glpk')
                    solver_name = 'glpk'
            else:
                solver = pyo.SolverFactory('glpk')
                solver_name = 'glpk'

    except Exception as e:
        print(f"Error creating solver: {e}")
        solver = pyo.SolverFactory('glpk')
        solver_name = 'glpk'

    # Set solver options
    if solver_name == 'highs':
        solver.options['time_limit'] = time_limit
        solver.options['mip_rel_gap'] = 0.06
        solver.options['threads'] = 8
        solver.options['log_to_console'] = True
        print(f"✓ Using HiGHS solver with {time_limit}s time limit")

    elif solver_name == 'appsi_highs':
        solver.config.time_limit = time_limit
        solver.config.mipgap = 0.06
        solver.config.threads = 8
        print(f"✓ Using HiGHS (APPSI) solver with {time_limit}s time limit")

    elif solver_name == 'gurobi':
        solver.options['TimeLimit'] = time_limit
        solver.options['MIPGap'] = 0.06
        solver.options['Threads'] = 8
        print(f"✓ Using Gurobi solver with {time_limit}s time limit")

    else:  # glpk
        solver.options['tmlim'] = time_limit
        solver.options['mipgap'] = 0.06
        print(f"✓ Using GLPK solver with {time_limit}s time limit")

    return solver


# ============================================================================
# OBJECTIVE CALCULATION UTILITIES
# ============================================================================

def calculate_objectives(schedule, job_results):
    """Calculate both objectives from a solution"""
    total_tardiness = sum(j.get('tardiness', 0) for j in job_results)
    total_setup = sum(
        sum(batch.get('setup_time', 0) for batch in machine.get('batches', []))
        for machine in schedule
    )
    return total_tardiness, total_setup


def filter_dominated_solutions(solutions):
    """Remove dominated solutions and duplicates to get Pareto front"""
    pareto_front = []
    seen_points = set()

    for sol_a in solutions:
        dominated = False
        for sol_b in solutions:
            if sol_a == sol_b:
                continue

            if (sol_b['tardiness'] <= sol_a['tardiness'] and
                sol_b['setup_time'] <= sol_a['setup_time']):
                if (sol_b['tardiness'] < sol_a['tardiness'] or
                    sol_b['setup_time'] < sol_a['setup_time']):
                    dominated = True
                    break

        if not dominated:
            point_key = (round(sol_a['tardiness'], 2), round(sol_a['setup_time'], 2))
            if point_key not in seen_points:
                seen_points.add(point_key)
                pareto_front.append(sol_a)

    pareto_front.sort(key=lambda x: x['tardiness'])
    return pareto_front


