# ROBUST CUSTOM DATASET LOADER
# ============================================================================

class CustomDatasetLoader:
    """
    Robust loader for custom Excel/CSV datasets
    Handles both single-sheet and multi-sheet Excel layouts
    """

    def __init__(self, processing_times=None):
        self.processing_times = processing_times or PROCESSING_TIMES
        self._xlsx_cache = None
        self._filepath_cache = None

    def _load_excel(self, filepath):
        """Load and cache Excel file"""
        if filepath != self._filepath_cache:
            self._xlsx_cache = pd.ExcelFile(filepath)
            self._filepath_cache = filepath
        return self._xlsx_cache

    def find_all_datasets(self, filepath):
        """Find all dataset sheets/locations in Excel file"""
        xlsx = self._load_excel(filepath)

        # Check for sheets named 'datasetX'
        datasets = {}
        for sheet in xlsx.sheet_names:
            sheet_lower = sheet.lower().strip()
            if sheet_lower.startswith('dataset') and sheet_lower != 'dataset conf.':
                datasets[sheet_lower] = {'sheet': sheet}

        return datasets

    def load_dataset(self, filepath, dataset_name, num_machines=4, machine_capacity=500):
        """
        Load a specific dataset from Excel file (supports multi-sheet format)

        Parameters:
        -----------
        filepath : str - Path to Excel file
        dataset_name : str - Name of dataset (e.g., 'dataset1')
        num_machines : int - Number of machines
        machine_capacity : int - Machine capacity

        Returns:
        --------
        jobs : list - Job data
        machines : list - Machine data
        metadata : dict - Dataset metadata
        setup_matrix : dict - Setup times for colors in dataset
        """
        xlsx = self._load_excel(filepath)

        # Find the sheet for this dataset
        target_sheet = None
        for sheet in xlsx.sheet_names:
            if sheet.lower().strip() == dataset_name.lower():
                target_sheet = sheet
                break

        if target_sheet is None:
            raise ValueError(f"Dataset '{dataset_name}' not found. Available sheets: {xlsx.sheet_names}")

        # Read the sheet
        df = pd.read_excel(xlsx, sheet_name=target_sheet, header=None)

        # Find the 'id' column header to locate data
        id_row = None
        id_col = None

        for i, row in df.iterrows():
            for j, cell in enumerate(row):
                if str(cell).lower().strip() == 'id':
                    id_row = i
                    id_col = j
                    break
            if id_row is not None:
                break

        if id_row is None:
            raise ValueError(f"Could not find 'id' column header in {dataset_name}")

        # Extract jobs starting from the row after header
        jobs = []
        row_idx = id_row + 1

        while row_idx < len(df):
            # Read 5 columns: id, customer, size, color, due_date
            row_data = df.iloc[row_idx, id_col:id_col+5].tolist()

            # Stop if we hit empty data
            if pd.isna(row_data[0]):
                break

            try:
                job_id = row_data[0]
                # Handle both int and float IDs
                if isinstance(job_id, float):
                    job_id = int(job_id)

                color = str(row_data[3]).lower().strip()

                job = {
                    'id': int(job_id),
                    'customer': int(row_data[1]),
                    'size': int(row_data[2]),
                    'color': color,
                    'due_date': int(row_data[4]),
                    'proc_time': self.processing_times.get(color, 8)
                }
                jobs.append(job)
            except (ValueError, TypeError) as e:
                # Stop on conversion error (likely end of data)
                break

            row_idx += 1

        if not jobs:
            raise ValueError(f"No valid jobs found in {dataset_name}")

        # Create machines
        machines = [{'id': i+1, 'capacity': machine_capacity} for i in range(num_machines)]

        # Calculate metadata
        colors_used = list(set(job['color'] for job in jobs))
        customers_used = list(set(job['customer'] for job in jobs))

        metadata = {
            'name': dataset_name,
            'num_jobs': len(jobs),
            'num_machines': num_machines,
            'machine_capacity': machine_capacity,
            'num_customers': len(customers_used),
            'num_colors': len(colors_used),
            'colors': colors_used,
            'customers': customers_used,
            'total_size': sum(job['size'] for job in jobs),
            'total_processing': sum(job['proc_time'] for job in jobs),
            'avg_size': np.mean([job['size'] for job in jobs]),
            'avg_due_date': np.mean([job['due_date'] for job in jobs])
        }

        # Generate setup matrix for colors in this dataset
        setup_matrix = generate_setup_matrix(colors_used)

        return jobs, machines, metadata, setup_matrix


def load_dataset(filepath, dataset_name, num_machines=4, machine_capacity=500):
    """Convenience function to load a dataset"""
    loader = CustomDatasetLoader()
    return loader.load_dataset(filepath, dataset_name, num_machines, machine_capacity)


