# ============================================================================
# STAGE 1: BATCH FORMATION - FFD HEURISTIC
# ============================================================================

def simplified_ffd(jobs, machines, setup_matrix=None):
    """
    First Fit Decreasing heuristic for batch formation

    Groups jobs by (color, customer) and packs into batches using FFD
    """
    capacity = machines[0]['capacity'] if machines else UNIFORM_CAPACITY

    # Group jobs by color and customer
    job_groups = {}
    for job in jobs:
        key = (job["color"], job["customer"])
        if key not in job_groups:
            job_groups[key] = []
        job_groups[key].append(job)

    batches = []
    batch_id = 1

    for (color, customer), group in job_groups.items():
        # Sort by size descending (FFD)
        sorted_jobs = sorted(group, key=lambda j: j["size"], reverse=True)
        remaining_jobs = sorted_jobs.copy()

        while remaining_jobs:
            current_batch = []
            current_size = 0

            # Best fit decreasing
            while remaining_jobs:
                best_idx = -1
                best_fit = 0
                for j in range(len(remaining_jobs)):
                    job_size = remaining_jobs[j]["size"]
                    if job_size <= (capacity - current_size) and job_size > best_fit:
                        best_idx = j
                        best_fit = job_size

                if best_idx >= 0:
                    job = remaining_jobs.pop(best_idx)
                    current_batch.append(job)
                    current_size += job["size"]
                else:
                    break

            if current_batch:
                batches.append({
                    "id": batch_id,
                    "family": color,
                    "customer": customer,
                    "jobs": current_batch,
                    "size": current_size,
                    "proc_time": current_batch[0]["proc_time"],
                    "due_date": min(j["due_date"] for j in current_batch),
                    "target_capacity": capacity
                })
                batch_id += 1

    return batches


# ============================================================================
# STAGE 1: BATCH FORMATION - SIMULATED ANNEALING IMPROVEMENT
# ============================================================================

def improved_simulated_annealing(initial_batches, jobs, machines, max_iterations=1000):
    """Simulated Annealing for batch optimization"""

    def evaluate_batching(batches):
        if not batches:
            return float('inf')
        num_batches = len(batches)
        fill_rates = [b["size"] / b["target_capacity"] for b in batches]
        avg_fill_rate = np.mean(fill_rates)
        size_variation = np.std([b["size"] for b in batches]) / 100
        score = (0.5 * num_batches - 0.4 * avg_fill_rate + 0.1 * size_variation)
        return score

    def generate_neighbor(batches):
        neighbor = copy.deepcopy(batches)
        op = random.choice(["move_job", "swap_jobs"])

        if op == "move_job" and len(neighbor) >= 2:
            multi_job_batches = [i for i, b in enumerate(neighbor) if len(b["jobs"]) > 1]
            if not multi_job_batches:
                return neighbor
            source_idx = random.choice(multi_job_batches)
            source_batch = neighbor[source_idx]
            compatible_batches = [
                i for i, b in enumerate(neighbor)
                if (b["family"] == source_batch["family"] and
                    b["customer"] == source_batch["customer"] and
                    i != source_idx)
            ]
            if compatible_batches:
                target_idx = random.choice(compatible_batches)
                target_batch = neighbor[target_idx]
                valid_jobs = [
                    i for i, job in enumerate(source_batch["jobs"])
                    if (target_batch["size"] + job["size"] <= target_batch["target_capacity"])
                ]
                if valid_jobs:
                    job_idx = random.choice(valid_jobs)
                    job = source_batch["jobs"].pop(job_idx)
                    source_batch["size"] -= job["size"]
                    target_batch["jobs"].append(job)
                    target_batch["size"] += job["size"]
                    if source_batch["jobs"]:
                        source_batch["due_date"] = min(j["due_date"] for j in source_batch["jobs"])
                    target_batch["due_date"] = min(j["due_date"] for j in target_batch["jobs"])

        elif op == "swap_jobs" and len(neighbor) >= 2:
            compatible_pairs = []
            for i in range(len(neighbor)):
                for j in range(i+1, len(neighbor)):
                    if (neighbor[i]["family"] == neighbor[j]["family"] and
                        neighbor[i]["customer"] == neighbor[j]["customer"] and
                        neighbor[i]["jobs"] and neighbor[j]["jobs"]):
                        compatible_pairs.append((i, j))
            if compatible_pairs:
                source_idx, target_idx = random.choice(compatible_pairs)
                source_batch = neighbor[source_idx]
                target_batch = neighbor[target_idx]
                valid_swaps = []
                for i, job1 in enumerate(source_batch["jobs"]):
                    for j, job2 in enumerate(target_batch["jobs"]):
                        new_source_size = source_batch["size"] - job1["size"] + job2["size"]
                        new_target_size = target_batch["size"] - job2["size"] + job1["size"]
                        if (new_source_size <= source_batch["target_capacity"] and
                            new_target_size <= target_batch["target_capacity"]):
                            valid_swaps.append((i, j))
                if valid_swaps:
                    job1_idx, job2_idx = random.choice(valid_swaps)
                    job1 = source_batch["jobs"][job1_idx]
                    job2 = target_batch["jobs"][job2_idx]
                    source_batch["jobs"][job1_idx] = job2
                    target_batch["jobs"][job2_idx] = job1
                    source_batch["size"] = source_batch["size"] - job1["size"] + job2["size"]
                    target_batch["size"] = target_batch["size"] - job2["size"] + job1["size"]
                    source_batch["due_date"] = min(j["due_date"] for j in source_batch["jobs"])
                    target_batch["due_date"] = min(j["due_date"] for j in target_batch["jobs"])

        return neighbor

    current = copy.deepcopy(initial_batches)
    best = copy.deepcopy(current)
    current_score = evaluate_batching(current)
    best_score = current_score
    temp = 100.0
    cooling_rate = globals().get('SA_COOLING_RATE', 0.95)

    for i in range(max_iterations):
        neighbor = generate_neighbor(current)
        neighbor_score = evaluate_batching(neighbor)
        delta = neighbor_score - current_score
        acceptance_prob = math.exp(-delta / temp) if delta > 0 else 1.0

        if random.random() < acceptance_prob:
            current = neighbor
            current_score = neighbor_score
            if current_score < best_score:
                best = copy.deepcopy(current)
                best_score = current_score

        temp *= cooling_rate

    return best, []


# ============================================================================
# STAGE 1: BATCH FORMATION - MILP
# ============================================================================

def solve_stage1_milp_simple(initial_batches, jobs, machines, setup_matrix=None):
    """Simplified MILP1 - minimize number of batches (NO OBJECTIVES)"""

    if not PYOMO_AVAILABLE:
        print("WARNING: Pyomo not available. Using FFD instead.")
        return initial_batches, 0

    print("Solving Stage 1 MILP (batch formation only)...")

    # Get unique colors and customers from jobs
    colors_in_jobs = list(set(j['color'] for j in jobs))
    customers_in_jobs = list(set(j['customer'] for j in jobs))

    color_to_idx = {c: i for i, c in enumerate(colors_in_jobs)}
    customer_to_idx = {c: i for i, c in enumerate(customers_in_jobs)}
    idx_to_color = {v: k for k, v in color_to_idx.items()}
    idx_to_customer = {v: k for k, v in customer_to_idx.items()}

    max_capacity = machines[0]['capacity'] if machines else UNIFORM_CAPACITY
    max_batches = len(initial_batches) + 2

    model = pyo.ConcreteModel()
    model.J = pyo.Set(initialize=range(len(jobs)))
    model.F = pyo.Set(initialize=list(color_to_idx.values()))
    model.C = pyo.Set(initialize=list(customer_to_idx.values()))
    model.B = pyo.Set(initialize=range(max_batches))

    model.s = pyo.Param(model.J, initialize={j: jobs[j]["size"] for j in model.J})
    model.f = pyo.Param(model.J, initialize={j: color_to_idx[jobs[j]["color"]] for j in model.J})
    model.c = pyo.Param(model.J, initialize={j: customer_to_idx[jobs[j]["customer"]] for j in model.J})
    model.cap = pyo.Param(initialize=max_capacity)

    model.x = pyo.Var(model.J, model.B, domain=pyo.Binary)
    model.y = pyo.Var(model.B, domain=pyo.Binary)
    model.z = pyo.Var(model.B, model.F, domain=pyo.Binary)
    model.w = pyo.Var(model.B, model.C, domain=pyo.Binary)
    model.S = pyo.Var(model.B, domain=pyo.NonNegativeReals)

    # Objective: Minimize number of batches
    model.objective = pyo.Objective(expr=sum(model.y[b] for b in model.B), sense=pyo.minimize)

    # Constraints
    def job_assignment_rule(model, j):
        return sum(model.x[j, b] for b in model.B) == 1
    model.job_assignment = pyo.Constraint(model.J, rule=job_assignment_rule)

    def batch_usage_rule(model, j, b):
        return model.x[j, b] <= model.y[b]
    model.batch_usage = pyo.Constraint(model.J, model.B, rule=batch_usage_rule)

    def batch_size_rule(model, b):
        return model.S[b] == sum(model.s[j] * model.x[j, b] for j in model.J)
    model.batch_size = pyo.Constraint(model.B, rule=batch_size_rule)

    def capacity_rule(model, b):
        return model.S[b] <= model.cap
    model.capacity = pyo.Constraint(model.B, rule=capacity_rule)

    def family_assignment_rule(model, j, b):
        return model.x[j, b] <= model.z[b, model.f[j]]
    model.family_assignment = pyo.Constraint(model.J, model.B, rule=family_assignment_rule)

    def single_family_rule(model, b):
        return sum(model.z[b, f] for f in model.F) <= 1
    model.single_family = pyo.Constraint(model.B, rule=single_family_rule)

    def customer_assignment_rule(model, j, b):
        return model.x[j, b] <= model.w[b, model.c[j]]
    model.customer_assignment = pyo.Constraint(model.J, model.B, rule=customer_assignment_rule)

    def single_customer_rule(model, b):
        return sum(model.w[b, c] for c in model.C) <= 1
    model.single_customer = pyo.Constraint(model.B, rule=single_customer_rule)

    def symmetry_breaking_rule(model, b):
        if b < max_batches - 1:
            return model.y[b] >= model.y[b + 1]
        return pyo.Constraint.Skip
    model.symmetry_breaking = pyo.Constraint(model.B, rule=symmetry_breaking_rule)

    solver = get_solver('highs', time_limit=1500)
    start_time = time.time()

    try:
        result = solver.solve(model, tee=True)
        solve_time = time.time() - start_time

        if result.solver.status != pyo.SolverStatus.ok:
            print("WARNING: Solver did not find optimal solution")
            return initial_batches, solve_time

    except Exception as e:
        print(f"Solver error: {e}")
        solve_time = time.time() - start_time
        return initial_batches, solve_time

    # Extract batches
    print("\n" + "="*80)
    print("STAGE 1 DETAILED RESULTS")
    print("="*80)

    batches = []
    batch_id = 1

    for b in model.B:
        if pyo.value(model.y[b]) > 0.5:
            batch_jobs = []
            batch_family = None
            for f in model.F:
                if pyo.value(model.z[b, f]) > 0.5:
                    batch_family = idx_to_color[f]
                    break
            batch_customer = None
            for c in model.C:
                if pyo.value(model.w[b, c]) > 0.5:
                    batch_customer = idx_to_customer[c]
                    break

            for j in model.J:
                if pyo.value(model.x[j, b]) > 0.5:
                    batch_jobs.append(jobs[j])

            if batch_jobs:
                batch_size = sum(job["size"] for job in batch_jobs)
                batch_proc_time = batch_jobs[0]["proc_time"]
                batch_due = min(job["due_date"] for job in batch_jobs)

                print(f"\nBatch {batch_id}:")
                print(f"  Color Family: {batch_family}")
                print(f"  Customer: {batch_customer}")
                print(f"  Total Size: {batch_size} kg")
                print(f"  Processing Time: {batch_proc_time} hours")
                print(f"  Setup Time (if transition): {SETUP_TIMES_BY_COLOR.get(batch_family, 0)} hours")
                print(f"  Earliest Due Date: {batch_due}")
                print(f"  Jobs in batch:")
                for job in batch_jobs:
                    print(f"    - Job {job['id']}: Size={job['size']}kg, Due={job['due_date']}, Color={job['color']}, Customer={job['customer']}")

                batches.append({
                    "id": batch_id,
                    "family": batch_family,
                    "customer": batch_customer,
                    "jobs": batch_jobs,
                    "size": batch_size,
                    "proc_time": batch_proc_time,
                    "due_date": batch_due,
                    "target_capacity": max_capacity
                })
                batch_id += 1

    print(f"\n" + "="*80)
    print(f"STAGE 1 SUMMARY")
    print(f"="*80)
    print(f"Total Batches Created: {len(batches)}")
    print(f"Objective Value: {pyo.value(model.objective)}")
    print(f"Solve Time: {solve_time:.2f} seconds")

    print(f"\nBatch Capacity Utilization:")
    for batch in batches:
        utilization = (batch["size"] / max_capacity) * 100
        print(f"  Batch {batch['id']}: {batch['size']}/{max_capacity} kg ({utilization:.1f}%)")

    print("="*80)

    return batches, solve_time


"""
FIXED INTEGRATED MILP WITH AUGMENTED EPSILON-CONSTRAINT

Key Fixes:
1. More robust max_batches calculation with larger buffers
2. Optional warm start (can be disabled for debugging)
3. Better diagnostic output to identify feasibility issues
4. Safety mode that uses a very large max_batches when needed
"""

import pyomo.environ as pyo
import math
import time
import copy
from collections import defaultdict


def solve_integrated_milp_epsilon(
    jobs, machines, epsilon_setup,
    primary_objective="tardiness",
    augmentation_coefficient=1e-6,
    setup_matrix=None,
    range_secondary=None,          # PHASE 1.2b: payoff-table range of the
                                   # secondary objective. AUGMECON2 divides
                                   # the surplus by it. None disables the
                                   # augmentation, which is what the
                                   # lexicographic range-finding phase needs.
    use_warm_start=True,           # NEW: Option to disable warm start
    max_batches_override=None,      # NEW: Manual override for max_batches
    safety_buffer_factor=2.0,       # NEW: Multiplier for safety buffer
    verbose=True                    # NEW: Detailed diagnostic output
):
    """
    INTEGRATED SINGLE-STAGE MILP WITH AUGMENTED EPSILON-CONSTRAINT

    FIXES APPLIED:
    1. More robust max_batches calculation
    2. Optional warm start (set use_warm_start=False if experiencing infeasibility)
    3. Manual override for max_batches if needed
    4. Better diagnostic output

    Parameters:
    -----------
    jobs : list - Job information
    machines : list - Machine information
    epsilon_setup : float - Upper bound on setup time (or tardiness)
    primary_objective : str - "tardiness" or "setup_time"
    augmentation_coefficient : float - Small coefficient for slack (default 1e-6)
    setup_matrix : dict - Setup time matrix (uses global if None)
    use_warm_start : bool - Whether to use FFD+SA warm start (default True)
    max_batches_override : int - If set, use this value for max_batches instead of calculating
    safety_buffer_factor : float - Multiplier for safety buffer in max_batches calc (default 2.0)
    verbose : bool - Print detailed diagnostic information

    Returns:
    --------
    schedule, job_results, solve_time
    """

    print("\n" + "="*80)
    print("INTEGRATED MILP WITH AUGMENTED EPSILON-CONSTRAINT (FIXED VERSION)")
    print("="*80)
    print(f"Primary objective: Minimize {primary_objective}")
    if primary_objective == "tardiness":
        print(f"Epsilon constraint: Setup time ≤ {epsilon_setup}")
    else:
        print(f"Epsilon constraint: Tardiness ≤ {epsilon_setup}")
    print(f"Augmentation coefficient: {augmentation_coefficient}")
    print(f"Use warm start: {use_warm_start}")
    print(f"Safety buffer factor: {safety_buffer_factor}")
    print("="*80)

    # Get unique colors and customers
    colors_in_jobs = list(set(j['color'] for j in jobs))
    customers_in_jobs = list(set(j['customer'] for j in jobs))

    color_to_idx = {c: i for i, c in enumerate(colors_in_jobs)}
    customer_to_idx = {c: i for i, c in enumerate(customers_in_jobs)}
    idx_to_color = {v: k for k, v in color_to_idx.items()}
    idx_to_customer = {v: k for k, v in customer_to_idx.items()}

    # Use provided setup_matrix or generate from global
    if setup_matrix is None:
        # Assuming generate_setup_matrix is available in the same scope
        setup_matrix = generate_setup_matrix(colors_in_jobs)



        #NEW:
    capacity = machines[0]['capacity'] if machines else 500

    # ================================================================
    # PRE-COMPUTE FFD+SA FOR BATCH COUNT AND WARM START
    # ================================================================
    warm_batches = None
    if use_warm_start:
        try:
            initial_batches = simplified_ffd(jobs, machines, setup_matrix)
            warm_batches, _ = improved_simulated_annealing(
                initial_batches, jobs, machines, max_iterations=200
            )
            print(f"\n  FFD+SA pre-solve: {len(warm_batches)} batches")
        except Exception as e:
            print(f"  ⚠ FFD+SA pre-solve failed: {e}")
            warm_batches = None

    # ================================================================
    # IMPROVED MAX_BATCHES CALCULATION
    # ================================================================

    if max_batches_override is not None:
        max_batches = max_batches_override
        print(f"\n⚙ Using manual max_batches override: {max_batches}")
    else:
#END_NEW
        # Group jobs by (color, customer)
        color_customer_groups = defaultdict(list)
        for j in jobs:
            key = (j['color'], j['customer'])
            color_customer_groups[key].append(j['size'])

        # Calculate minimum batches needed per group (exact calculation)
        min_batches_constrained = 0
        group_batch_counts = {}

        for (color, customer), sizes in color_customer_groups.items():
            group_total = sum(sizes)
            # Use FFD approximation for this group
            group_batches = 0
            remaining_capacity = 0
            for size in sorted(sizes, reverse=True):
                if size > remaining_capacity:
                    group_batches += 1
                    remaining_capacity = capacity - size
                else:
                    remaining_capacity -= size

            group_batch_counts[(color, customer)] = group_batches
            min_batches_constrained += group_batches

        # Other bounds
        color_customer_pairs = len(color_customer_groups)
        total_size = sum(j['size'] for j in jobs)
        min_batches_by_size = math.ceil(total_size / capacity)

        # Worst case: each job could need its own batch
        worst_case = len(jobs)

        # ================================================================
        # KEY FIX: Use larger buffers and safety multiplier
        # ================================================================



        #NEW:
        # Calculate with improved buffers
        candidate_values = [
            min_batches_constrained + 2,                      # Constrained + small buffer
            min_batches_by_size + 2,                          # Size-based + small buffer
            color_customer_pairs + 1,                         # Groups + 1
        ]

        # If we have a warm start, use its batch count as the anchor
        if warm_batches is not None:
            # Warm start gives us a known feasible batch count
            # Add a small buffer for the solver to explore alternatives
            max_batches = len(warm_batches) + 2
            print(f"\n  max_batches from warm start: {len(warm_batches)} + 2 = {max_batches}")
        else:
            max_batches = int(max(candidate_values))
            max_batches = max(max_batches, 6)  # Reasonable minimum floor
#END_NEW

        if verbose:
            print(f"\n{'='*60}")
            print("MAX_BATCHES CALCULATION DETAILS")
            print(f"{'='*60}")
            print(f"  Number of jobs: {len(jobs)}")
            print(f"  Machine capacity: {capacity}")
            print(f"  Total job size: {total_size}")
            print(f"  Color-customer groups: {color_customer_pairs}")
            print(f"\n  Group breakdown:")
            for (color, customer), count in sorted(group_batch_counts.items()):
                group_sizes = color_customer_groups[(color, customer)]
                print(f"    ({color}, C{customer}): {len(group_sizes)} jobs, "
                      f"total size {sum(group_sizes)}, min batches: {count}")
            print(f"\n  Candidate values:")
            print(f"    min_batches_constrained * {safety_buffer_factor}: {min_batches_constrained * safety_buffer_factor:.1f}")
            print(f"    min_batches_by_size + 5: {min_batches_by_size + 5}")
            print(f"    color_customer_pairs * 2: {color_customer_pairs * 2}")
            print(f"    len(jobs) * 0.75: {len(jobs) * 0.75:.1f}")
            print(f"    minimum floor: 15")
            print(f"\n  ➜ SELECTED max_batches: {max_batches}")
            print(f"{'='*60}")

    # Pre-compute setup times matrix with indices
    setup_times_matrix = {}
    for f1 in color_to_idx.values():
        for f2 in color_to_idx.values():
            if f1 == f2:
                setup_times_matrix[(f1, f2)] = 0
            else:
                color1 = idx_to_color.get(f1)
                color2 = idx_to_color.get(f2)
                if color1 and color2:
                    setup_times_matrix[(f1, f2)] = setup_matrix.get((color1, color2), 0)
                else:
                    setup_times_matrix[(f1, f2)] = 0

    # Create model
    model = pyo.ConcreteModel()

    # Sets
    model.J = pyo.Set(initialize=range(len(jobs)))
    model.B = pyo.Set(initialize=range(max_batches))
    model.M = pyo.Set(initialize=range(len(machines)))
    model.F = pyo.Set(initialize=list(color_to_idx.values()))
    model.C = pyo.Set(initialize=list(customer_to_idx.values()))

    # Parameters
    model.s = pyo.Param(model.J, initialize={j: jobs[j]["size"] for j in model.J})
    model.p = pyo.Param(model.J, initialize={j: jobs[j]["proc_time"] for j in model.J})
    model.d = pyo.Param(model.J, initialize={j: jobs[j]["due_date"] for j in model.J})
    model.f = pyo.Param(model.J, initialize={j: color_to_idx[jobs[j]["color"]] for j in model.J})
    model.c = pyo.Param(model.J, initialize={j: customer_to_idx[jobs[j]["customer"]] for j in model.J})
    model.Q = pyo.Param(initialize=capacity)
    model.setup_param = pyo.Param(model.F, model.F,
                                   initialize=lambda model, f1, f2: setup_times_matrix.get((f1, f2), 0))

    # PHASE 1.3: a transition-scale big-M.  Using the horizon-scale M_big in
    # the setup constraints destroys the LP relaxation (the bound stayed at 0
    # for the whole search in the run of 2026-09-01).
    M_SIGMA = max(setup_times_matrix.values()) if setup_times_matrix else 1.0

    # Big-M calculation
    total_processing = sum(jobs[j]["proc_time"] for j in model.J)
    max_setup = max(setup_times_matrix.values()) if setup_times_matrix else 0
    max_makespan = total_processing + max_setup * len(jobs)
    model.M_big = pyo.Param(initialize=max_makespan * 1.2)

    # ==================== DECISION VARIABLES ====================

    # Batch formation variables
    model.x = pyo.Var(model.J, model.B, domain=pyo.Binary)  # job j in batch b
    model.y = pyo.Var(model.B, domain=pyo.Binary)  # batch b used
    model.z = pyo.Var(model.B, model.F, domain=pyo.Binary)  # batch b has color f
    model.w = pyo.Var(model.B, model.C, domain=pyo.Binary)  # batch b has customer c
    model.S_batch = pyo.Var(model.B, domain=pyo.NonNegativeReals)  # batch size
    model.P_batch = pyo.Var(model.B, domain=pyo.NonNegativeReals)  # batch processing time

    # Machine assignment and sequencing variables
    model.a = pyo.Var(model.B, model.M, domain=pyo.Binary)  # batch b on machine m
    model.seq = pyo.Var(model.B, model.B, model.M, domain=pyo.Binary)  # i precedes j on m
    model.first = pyo.Var(model.B, model.M, domain=pyo.Binary)  # b is first on m
    model.last = pyo.Var(model.B, model.M, domain=pyo.Binary)  # b is last on m

    # Timing variables
    model.start = pyo.Var(model.B, domain=pyo.NonNegativeReals)  # start time of batch
    model.C_batch = pyo.Var(model.B, domain=pyo.NonNegativeReals)  # completion time of batch
    model.T_job = pyo.Var(model.J, domain=pyo.NonNegativeReals)  # tardiness of job

    # Linearization variables
    # PHASE 1.3: u[i,j,f1,f2] removed.  It carried |B|^2|F|^2 binaries (9,216
    # of the 10,032 in the 24-job run) purely to linearize z[i,f1]*z[j,f2].
    # Given z[i,f1]=1 the setup expression is already linear in z[j,.], so one
    # big-M constraint per (i,j,f1) replaces it: 0 new binaries.
    model.C_job = pyo.Var(model.J, model.B, domain=pyo.NonNegativeReals)
    model.setup_ij = pyo.Var(model.B, model.B, domain=pyo.NonNegativeReals)
    model.active_setup = pyo.Var(model.B, model.B, model.M, domain=pyo.NonNegativeReals)
    model.TS = pyo.Var(domain=pyo.NonNegativeReals)

    # Slack variable for augmented epsilon-constraint
    if augmentation_coefficient > 0:
        model.slack = pyo.Var(domain=pyo.NonNegativeReals)

    # ==================== OBJECTIVE FUNCTION ====================

    # PHASE 1.2b: AUGMECON2 is  min f1 - delta * (s / r2), where r2 is the
    # payoff-table range of the secondary objective. Without that division the
    # surplus sits on the raw epsilon scale: in the range-finding phase
    # epsilon = 1e6, so the term reaches -1 and pins the lower bound there.
    # Observed before this fix: BestBound = -1, gap 101% after 580 s.
    _r2 = float(range_secondary) if range_secondary else 1.0
    if augmentation_coefficient > 0 and not range_secondary:
        augmentation_coefficient = 0.0    # no meaningful scale yet

    if primary_objective == "tardiness":
        if augmentation_coefficient > 0:
            model.objective = pyo.Objective(
                expr=sum(model.T_job[j] for j in model.J)
                     - augmentation_coefficient * (model.slack / _r2),
                sense=pyo.minimize
            )
        else:
            model.objective = pyo.Objective(
                expr=sum(model.T_job[j] for j in model.J),
                sense=pyo.minimize
            )
    else:  # setup_time
        if augmentation_coefficient > 0:
            model.objective = pyo.Objective(
                expr=model.TS - augmentation_coefficient * (model.slack / _r2),
                sense=pyo.minimize
            )
        else:
            model.objective = pyo.Objective(
                expr=model.TS,
                sense=pyo.minimize
            )

    # ==================== EPSILON CONSTRAINT ====================


    #NEW:
    # ==================== EPSILON CONSTRAINT (AUGMECON2) ====================

    if primary_objective == "tardiness":
        if augmentation_coefficient > 0:
            model.epsilon_constraint = pyo.Constraint(
                expr=model.TS + model.slack == epsilon_setup
            )
        else:
            model.epsilon_constraint = pyo.Constraint(
                expr=model.TS <= epsilon_setup
            )
    else:
        if augmentation_coefficient > 0:
            model.epsilon_constraint = pyo.Constraint(
                expr=sum(model.T_job[j] for j in model.J) + model.slack == epsilon_setup
            )
        else:
            model.epsilon_constraint = pyo.Constraint(
                expr=sum(model.T_job[j] for j in model.J) <= epsilon_setup
            )
#END_NEW

    # ==================== BATCH FORMATION CONSTRAINTS ====================

    def job_assignment_rule(model, j):
        return sum(model.x[j, b] for b in model.B) == 1
    model.job_assignment = pyo.Constraint(model.J, rule=job_assignment_rule)

    def batch_usage_rule(model, j, b):
        return model.x[j, b] <= model.y[b]
    model.batch_usage = pyo.Constraint(model.J, model.B, rule=batch_usage_rule)

    def batch_size_rule(model, b):
        return model.S_batch[b] == sum(model.s[j] * model.x[j, b] for j in model.J)
    model.batch_size = pyo.Constraint(model.B, rule=batch_size_rule)

    def batch_proc_time_rule(model, b, j):
        return model.P_batch[b] >= model.p[j] * model.x[j, b]
    model.batch_proc_time = pyo.Constraint(model.B, model.J, rule=batch_proc_time_rule)

    def capacity_rule(model, b):
        return model.S_batch[b] <= model.Q
    model.capacity = pyo.Constraint(model.B, rule=capacity_rule)

    def family_assignment_rule(model, j, b):
        return model.x[j, b] <= model.z[b, model.f[j]]
    model.family_assignment = pyo.Constraint(model.J, model.B, rule=family_assignment_rule)

    def single_family_rule(model, b):
        return sum(model.z[b, f] for f in model.F) <= 1
    model.single_family = pyo.Constraint(model.B, rule=single_family_rule)

    def customer_assignment_rule(model, j, b):
        return model.x[j, b] <= model.w[b, model.c[j]]
    model.customer_assignment = pyo.Constraint(model.J, model.B, rule=customer_assignment_rule)

    def single_customer_rule(model, b):
        return sum(model.w[b, c] for c in model.C) <= 1
    model.single_customer = pyo.Constraint(model.B, rule=single_customer_rule)


    #NEW:
    # Symmetry breaking (full — pack active batches toward lower indices)
    def symmetry_breaking_rule(model, b):
        if b < max_batches - 1:
            return model.y[b] >= model.y[b + 1]
        return pyo.Constraint.Skip
    model.symmetry_breaking = pyo.Constraint(model.B, rule=symmetry_breaking_rule)
#END_NEW


    # ==================== LINEARIZATION CONSTRAINTS ====================

    # PHASE 1.3: colour-conditional big-M in place of the u-product block.
    # If batch i carries family f1 the constraint is active and forces
    # setup_ij[i,j] up to the correct value; otherwise it is relaxed.  Both
    # the objective and the epsilon bound push setup_ij down, so >= is tight
    # at optimality and equality is unnecessary.
    def setup_link_rule(model, i, j, f1):
        if i == j:
            return pyo.Constraint.Skip
        return (model.setup_ij[i, j]
                >= sum(model.setup_param[f1, f2] * model.z[j, f2] for f2 in model.F)
                - M_SIGMA * (1 - model.z[i, f1]))
    model.setup_link = pyo.Constraint(model.B, model.B, model.F, rule=setup_link_rule)

    def linearize_C_job1_rule(model, j, b):
        return model.C_job[j, b] <= model.C_batch[b]
    model.linearize_C_job1 = pyo.Constraint(model.J, model.B, rule=linearize_C_job1_rule)

    def linearize_C_job2_rule(model, j, b):
        return model.C_job[j, b] <= model.M_big * model.x[j, b]
    model.linearize_C_job2 = pyo.Constraint(model.J, model.B, rule=linearize_C_job2_rule)

    def linearize_C_job3_rule(model, j, b):
        return model.C_job[j, b] >= model.C_batch[b] - model.M_big * (1 - model.x[j, b])
    model.linearize_C_job3 = pyo.Constraint(model.J, model.B, rule=linearize_C_job3_rule)

    def linearize_active_setup1_rule(model, i, j, m):
        if i != j:
            return model.active_setup[i, j, m] <= model.setup_ij[i, j]
        return pyo.Constraint.Skip
    model.linearize_active_setup1 = pyo.Constraint(model.B, model.B, model.M, rule=linearize_active_setup1_rule)

    # PHASE 1.3: M_SIGMA (largest transition) instead of the horizon-scale
    # M_big.  A horizon-scale coefficient here makes the relaxation vacuous.
    def linearize_active_setup2_rule(model, i, j, m):
        if i != j:
            return model.active_setup[i, j, m] <= M_SIGMA * model.seq[i, j, m]
        return pyo.Constraint.Skip
    model.linearize_active_setup2 = pyo.Constraint(model.B, model.B, model.M, rule=linearize_active_setup2_rule)

    def linearize_active_setup3_rule(model, i, j, m):
        if i != j:
            return model.active_setup[i, j, m] >= model.setup_ij[i, j] - M_SIGMA * (1 - model.seq[i, j, m])
        return pyo.Constraint.Skip
    model.linearize_active_setup3 = pyo.Constraint(model.B, model.B, model.M, rule=linearize_active_setup3_rule)

    # ==================== MACHINE ASSIGNMENT CONSTRAINTS ====================

    def batch_to_machine_rule(model, b):
        return sum(model.a[b, m] for m in model.M) == model.y[b]
    model.batch_to_machine = pyo.Constraint(model.B, rule=batch_to_machine_rule)

    # ==================== SEQUENCING CONSTRAINTS ====================

    # PHASE 1.2: exact degree equalities.  Flow conservation only balanced
    # in- and out-degree, which left room for the tournament constraint below
    # to force an arc on every same-machine pair.  A path has no arc between
    # non-adjacent batches, so the two families contradicted each other and
    # the model was INFEASIBLE whenever a machine received 3 or more batches
    # (verified with HiGHS: k=2 optimal, k=3..6 infeasible).
    def in_degree_rule(model, b, m):
        return (sum(model.seq[i, b, m] for i in model.B if i != b)
                + model.first[b, m] == model.a[b, m])
    model.in_degree = pyo.Constraint(model.B, model.M, rule=in_degree_rule)

    def out_degree_rule(model, b, m):
        return (sum(model.seq[b, k, m] for k in model.B if k != b)
                + model.last[b, m] == model.a[b, m])
    model.out_degree = pyo.Constraint(model.B, model.M, rule=out_degree_rule)

    def seq_implies_assignment1(model, i, j, m):
        if i != j:
            return model.seq[i, j, m] <= model.a[i, m]
        return pyo.Constraint.Skip
    model.seq_assignment1 = pyo.Constraint(model.B, model.B, model.M, rule=seq_implies_assignment1)

    def seq_implies_assignment2(model, i, j, m):
        if i != j:
            return model.seq[i, j, m] <= model.a[j, m]
        return pyo.Constraint.Skip
    model.seq_assignment2 = pyo.Constraint(model.B, model.B, model.M, rule=seq_implies_assignment2)

    def first_implies_assignment(model, b, m):
        return model.first[b, m] <= model.a[b, m]
    model.first_assignment = pyo.Constraint(model.B, model.M, rule=first_implies_assignment)

    def last_implies_assignment(model, b, m):
        return model.last[b, m] <= model.a[b, m]
    model.last_assignment = pyo.Constraint(model.B, model.M, rule=last_implies_assignment)

    def one_first_rule(model, m):
        return sum(model.first[b, m] for b in model.B) <= 1
    model.one_first = pyo.Constraint(model.M, rule=one_first_rule)

    def one_last_rule(model, m):
        return sum(model.last[b, m] for b in model.B) <= 1
    model.one_last = pyo.Constraint(model.M, rule=one_last_rule)

    # PHASE 1.2: must_have_incoming_or_first / must_have_outgoing_or_last are
    # implied by the degree equalities above and have been removed.
    # exactly_one_ordering (the tournament constraint) was the actual defect
    # and is removed outright.
    #
    # MTZ ranks: the timing constraints already forbid cycles in any integer
    # solution, but they do so through a horizon-scale big-M, so the LP
    # relaxation learns nothing from them.  MTZ eliminates subtours
    # combinatorially and tightens the root bound.
    model.rank = pyo.Var(model.B, domain=pyo.NonNegativeReals,
                         bounds=(0, max_batches - 1))

    def mtz_rule(model, i, j, m):
        if i == j:
            return pyo.Constraint.Skip
        return model.rank[j] >= model.rank[i] + 1 - max_batches * (1 - model.seq[i, j, m])
    model.mtz = pyo.Constraint(model.B, model.B, model.M, rule=mtz_rule)

    # ==================== TIMING CONSTRAINTS ====================

    def start_first_rule(model, b, m):
        return model.start[b] <= model.M_big * (1 - model.first[b, m])
    model.start_first = pyo.Constraint(model.B, model.M, rule=start_first_rule)

    def precedence_rule(model, i, j, m):
        if i != j:
            return model.start[j] >= model.C_batch[i] + model.setup_ij[i, j] - \
                   model.M_big * (1 - model.seq[i, j, m])
        return pyo.Constraint.Skip
    model.precedence = pyo.Constraint(model.B, model.B, model.M, rule=precedence_rule)

    def completion_rule(model, b):
        return model.C_batch[b] == model.start[b] + model.P_batch[b]
    model.completion = pyo.Constraint(model.B, rule=completion_rule)

    # ==================== TARDINESS CONSTRAINTS ====================

    def job_tardiness_rule(model, j):
        return model.T_job[j] >= sum(model.C_job[j, b] for b in model.B) - model.d[j]
    model.job_tardiness = pyo.Constraint(model.J, rule=job_tardiness_rule)

    def job_tardiness_nonneg_rule(model, j):
        return model.T_job[j] >= 0
    model.job_tardiness_nonneg = pyo.Constraint(model.J, rule=job_tardiness_nonneg_rule)

    # VALID INEQUALITY (optional, controlled by the global USE_VALID_INEQ).
    # Job j sits in some batch whose processing time is p_{f_j}, and no batch
    # can start before time zero, so C_j >= p_{f_j} regardless of every other
    # decision. The resulting bound on T_j is a constant, so it holds in the
    # linear relaxation too and lifts the dual bound off zero.
    if globals().get('USE_VALID_INEQ', True):
        def tardiness_floor_rule(model, j):
            job = jobs[j]          # model.J is indexed 0..n-1 over the list
            floor = max(0.0, job['proc_time'] - job['due_date'])
            if floor <= 0:
                return pyo.Constraint.Skip
            return model.T_job[j] >= floor
        model.tardiness_floor = pyo.Constraint(model.J, rule=tardiness_floor_rule)


    # ==================== TOTAL SETUP CONSTRAINT ====================

    def total_setup_rule(model):
        return model.TS == sum(
            model.active_setup[i, j, m]
            for i in model.B for j in model.B for m in model.M if i != j
        )
    model.total_setup_constraint = pyo.Constraint(rule=total_setup_rule)

    # ==================== WARM START (OPTIONAL) ====================

# ==================== WARM START (COMPLETE) ====================


#NEW:
    if use_warm_start and warm_batches is not None:
        print("\nApplying COMPLETE warm start from pre-computed FFD+SA...")
        try:
#END_NEW

   # if use_warm_start:
    #    print("\nGenerating COMPLETE warm start from FFD+SA...")
    #    try:
            # Step 1: Get batches from FFD+SA
            initial_batches = simplified_ffd(jobs, machines, setup_matrix)
            warm_batches, _ = improved_simulated_annealing(
                initial_batches, jobs, machines, max_iterations=200
            )

            if len(warm_batches) > max_batches:
                print(f"  ⚠ Warning: FFD+SA produced {len(warm_batches)} batches "
                      f"but max_batches={max_batches}")
                print(f"     Increasing max_batches would be needed. Skipping warm start.")
                raise ValueError("Too many batches for warm start")

            # ----------------------------------------------------------
            # Step 2: Initialize ALL variables to zero/default
            # ----------------------------------------------------------
            for b in model.B:
                model.y[b].set_value(0)
                model.S_batch[b].set_value(0)
                model.P_batch[b].set_value(0)
                model.start[b].set_value(0)
                model.C_batch[b].set_value(0)
                for f in model.F:
                    model.z[b, f].set_value(0)
                for c_idx in model.C:
                    model.w[b, c_idx].set_value(0)
                for j in model.J:
                    model.x[j, b].set_value(0)
                    model.C_job[j, b].set_value(0)
                for m in model.M:
                    model.a[b, m].set_value(0)
                    model.first[b, m].set_value(0)
                    model.last[b, m].set_value(0)

            for i in model.B:
                for j_b in model.B:
                    if i != j_b:
                        model.setup_ij[i, j_b].set_value(0)
                        for m in model.M:
                            model.seq[i, j_b, m].set_value(0)
                            model.active_setup[i, j_b, m].set_value(0)

            for j in model.J:
                model.T_job[j].set_value(0)

            model.TS.set_value(0)
            if augmentation_coefficient > 0:
                model.slack.set_value(0)

            # ----------------------------------------------------------
            # Step 3: Set batch formation variables (x, y, z, w, S, P)
            # ----------------------------------------------------------
            # Build a lookup: job_id -> index in jobs list
            job_id_to_idx = {jobs[i]["id"]: i for i in range(len(jobs))}

            # Store batch family index for later use
            batch_family_idx = {}  # batch_index -> color family index

            for b_idx, batch in enumerate(warm_batches):
                model.y[b_idx].set_value(1)

                f_idx = color_to_idx.get(batch["family"])
                c_idx = customer_to_idx.get(batch["customer"])
                batch_family_idx[b_idx] = f_idx

                if f_idx is not None:
                    model.z[b_idx, f_idx].set_value(1)
                if c_idx is not None:
                    model.w[b_idx, c_idx].set_value(1)

                for job in batch["jobs"]:
                    j_idx = job_id_to_idx.get(job["id"])
                    if j_idx is not None:
                        model.x[j_idx, b_idx].set_value(1)

                model.S_batch[b_idx].set_value(batch["size"])
                model.P_batch[b_idx].set_value(batch["proc_time"])

            # ----------------------------------------------------------
            # Step 4: Assign batches to machines using LPT (Longest
            #         Processing Time first to the least-loaded machine)
            # ----------------------------------------------------------
            num_machines = len(machines)
            machine_load = [0.0] * num_machines
            machine_sequences = [[] for _ in range(num_machines)]  # list of batch indices

            # Sort batches by due date (EDD) for initial assignment
            sorted_batch_indices = sorted(
                range(len(warm_batches)),
                key=lambda i: warm_batches[i].get("due_date", float('inf'))
            )

            # Group by color family, then assign color groups to minimize setup
            from collections import defaultdict as _defaultdict
            color_batch_groups = _defaultdict(list)
            for b_idx in sorted_batch_indices:
                family = warm_batches[b_idx]["family"]
                color_batch_groups[family].append(b_idx)

            # Assign color groups round-robin to machines (keeps same-color
            # batches together on the same machine to reduce setup)
            all_batch_indices_ordered = []
            for family in sorted(color_batch_groups.keys()):
                all_batch_indices_ordered.extend(color_batch_groups[family])

            for b_idx in all_batch_indices_ordered:
                # Assign to least-loaded machine
                best_m = min(range(num_machines), key=lambda i: machine_load[i])
                machine_sequences[best_m].append(b_idx)
                model.a[b_idx, best_m].set_value(1)
                # Estimate load including potential setup
                machine_load[best_m] += warm_batches[b_idx]["proc_time"]

            # ----------------------------------------------------------
            # Step 5: Order batches on each machine by EDD within
            #         color groups (minimizes setup + respects due dates)
            # ----------------------------------------------------------
            for m_idx in range(num_machines):
                seq = machine_sequences[m_idx]
                if not seq:
                    continue

                # Sort: group by color first, then EDD within each group
                seq.sort(key=lambda i: (
                    warm_batches[i]["family"],
                    warm_batches[i].get("due_date", float('inf'))
                ))
                machine_sequences[m_idx] = seq

            # ----------------------------------------------------------
            # Step 6: Set sequencing variables (seq, first, last)
            # ----------------------------------------------------------
            for m_idx in range(num_machines):
                seq = machine_sequences[m_idx]
                if not seq:
                    continue

                # First batch on this machine
                model.first[seq[0], m_idx].set_value(1)
                # Last batch on this machine
                model.last[seq[-1], m_idx].set_value(1)

                # Precedence chain: seq[k] -> seq[k+1]
                for k in range(len(seq) - 1):
                    i_b = seq[k]
                    j_b = seq[k + 1]
                    model.seq[i_b, j_b, m_idx].set_value(1)

            # ----------------------------------------------------------
            # Step 7: rank variables for the MTZ constraints
            # ----------------------------------------------------------
            # PHASE 1.3: u no longer exists.  What the warm start must now
            # supply instead is a consistent MTZ rank, otherwise the starting
            # point violates the new constraints and the solver discards it
            # (which is what happened in the 2026-09-01 run: BestSol stayed
            # at inf for 522 s despite a warm start being reported).
            for m_idx in range(num_machines):
                for pos, i_b in enumerate(machine_sequences[m_idx]):
                    model.rank[i_b].set_value(pos)

            # Unused batch slots still need a rank inside their bounds.
            for b_idx in model.B:
                if model.rank[b_idx].value is None:
                    model.rank[b_idx].set_value(0)

            # num_warm used to be defined inside the deleted u-block; Step 8
            # still needs it.
            num_warm = len(warm_batches)

            # ----------------------------------------------------------
            # Step 8: Set setup_ij[i,j] for all batch pairs
            # ----------------------------------------------------------
            # setup_ij[i,j] = sum over f1,f2 of setup_param[f1,f2] * u[i,j,f1,f2]
            # Since u[i,j,f1,f2]=1 only for the actual families:
            for i_b in range(num_warm):
                f1 = batch_family_idx.get(i_b)
                if f1 is None:
                    continue
                for j_b in range(num_warm):
                    if i_b == j_b:
                        continue
                    f2 = batch_family_idx.get(j_b)
                    if f2 is None:
                        continue
                    setup_val = setup_times_matrix.get((f1, f2), 0)
                    model.setup_ij[i_b, j_b].set_value(setup_val)

            # ----------------------------------------------------------
            # Step 9: Compute timing (start, C_batch) by forward pass
            #         and set active_setup[i,j,m]
            # ----------------------------------------------------------
            total_setup_warm = 0.0

            for m_idx in range(num_machines):
                seq = machine_sequences[m_idx]
                if not seq:
                    continue

                current_time = 0.0  # machines start clean at time 0

                for k, b_idx in enumerate(seq):
                    # Setup time from predecessor
                    setup_time_val = 0.0
                    if k > 0:
                        prev_b = seq[k - 1]
                        f_prev = batch_family_idx.get(prev_b)
                        f_curr = batch_family_idx.get(b_idx)
                        if f_prev is not None and f_curr is not None:
                            setup_time_val = setup_times_matrix.get(
                                (f_prev, f_curr), 0
                            )
                        # Set active_setup for this actual transition
                        model.active_setup[prev_b, b_idx, m_idx].set_value(
                            setup_time_val
                        )
                        total_setup_warm += setup_time_val

                    start_time_val = current_time + setup_time_val if k > 0 else 0.0
                    proc_time_val = warm_batches[b_idx]["proc_time"]
                    completion_time_val = start_time_val + proc_time_val

                    model.start[b_idx].set_value(start_time_val)
                    model.C_batch[b_idx].set_value(completion_time_val)

                    current_time = completion_time_val

            # ----------------------------------------------------------
            # Step 10: Set job-level variables (C_job, T_job)
            # ----------------------------------------------------------
            # C_job[j,b] = C_batch[b] if x[j,b]=1, else 0
            total_tardiness_warm = 0.0

            for b_idx, batch in enumerate(warm_batches):
                completion_b = pyo.value(model.C_batch[b_idx])
                for job in batch["jobs"]:
                    j_idx = job_id_to_idx.get(job["id"])
                    if j_idx is None:
                        continue

                    # C_job linearization: C_job[j,b] = C_batch[b] when x[j,b]=1
                    model.C_job[j_idx, b_idx].set_value(completion_b)

                    # Tardiness
                    due_date = jobs[j_idx]["due_date"]
                    tardiness = max(0, completion_b - due_date)
                    model.T_job[j_idx].set_value(tardiness)
                    total_tardiness_warm += tardiness

            # ----------------------------------------------------------
            # Step 11: Set aggregate variables (TS, slack)
            # ----------------------------------------------------------
            model.TS.set_value(total_setup_warm)

            if augmentation_coefficient > 0:
                if primary_objective == "tardiness":
                    # Epsilon constraint: TS - slack <= epsilon_setup
                    slack_val = max(0, epsilon_setup - total_setup_warm)
                    model.slack.set_value(slack_val)
                else:
                    slack_val = max(0, epsilon_setup - total_tardiness_warm)
                    model.slack.set_value(slack_val)

            # ----------------------------------------------------------
            # Summary
            # ----------------------------------------------------------
            batches_per_machine = [len(machine_sequences[m]) for m in range(num_machines)]
            print(f"  ✓ COMPLETE warm start initialized:")
            print(f"    Batches: {len(warm_batches)} (max_batches={max_batches})")
            print(f"    Machine distribution: {batches_per_machine}")
            print(f"    Total tardiness: {total_tardiness_warm:.2f}")
            print(f"    Total setup time: {total_setup_warm:.2f}")
            print(f"    Variables set: x, y, z, w, S_batch, P_batch, a, "
                  f"seq, first, last,")
            print(f"                   u, setup_ij, active_setup, "
                  f"start, C_batch, C_job, T_job, TS, slack")

        except Exception as e:
            print(f"  ⚠ Warning: Could not generate warm start: {e}")
            import traceback
            traceback.print_exc()
            print(f"  Proceeding without warm start...")
    else:
            print("\n⚠ Warm start DISABLED - solving from scratch")

    # ==================== SOLVE ====================
    print(f"\nSolving integrated MILP...")
    print(f"  Model size: {len(jobs)} jobs × {max_batches} batches × {len(machines)} machines")

    # get_solver should be available in the same scope
    solver = get_solver('highs', time_limit=1200)
    start_time_solve = time.time()

    try:
        result = solver.solve(model, tee=True)
        solve_time = time.time() - start_time_solve

        print(f"\nSolver status: {result.solver.status}")
        print(f"Termination: {result.solver.termination_condition}")
        print(f"Time: {solve_time:.2f}s")

        if result.solver.status != pyo.SolverStatus.ok:
            print("WARNING: Solver did not complete successfully")
            if result.solver.termination_condition == pyo.TerminationCondition.infeasible:
                print("\n" + "!"*80)
                print("INFEASIBLE: No solution satisfies the constraints")
                print("!"*80)
                print("\nPossible causes:")
                print("  1. max_batches is too small")
                print("  2. Epsilon constraint is too tight")
                print("  3. Problem structure is inherently infeasible")
                print("\nSuggested fixes:")
                print("  1. Increase max_batches_override (try 2x current value)")
                print("  2. Increase epsilon_setup value")
                print("  3. Set use_warm_start=False and try again")
                print(f"\nCurrent settings: max_batches={max_batches}, epsilon={epsilon_setup}")
                print("!"*80)
                return None, None, solve_time

    except Exception as e:
        print(f"Solver error: {e}")
        solve_time = time.time() - start_time_solve
        return None, None, solve_time

    # ==================== EXTRACT SOLUTION ====================
    batches_formed = []
    batch_id = 1

    for b in model.B:
        if pyo.value(model.y[b]) > 0.5:
            batch_jobs = []
            batch_family = None
            batch_customer = None

            for f in model.F:
                if pyo.value(model.z[b, f]) > 0.5:
                    batch_family = idx_to_color[f]
                    break

            for c_idx in model.C:
                if pyo.value(model.w[b, c_idx]) > 0.5:
                    batch_customer = idx_to_customer[c_idx]
                    break

            for j in model.J:
                if pyo.value(model.x[j, b]) > 0.5:
                    batch_jobs.append(jobs[j])

            if batch_jobs:
                batches_formed.append({
                    "id": batch_id,
                    "internal_id": b,
                    "family": batch_family,
                    "customer": batch_customer,
                    "jobs": batch_jobs,
                    "size": pyo.value(model.S_batch[b]),
                    "proc_time": pyo.value(model.P_batch[b]),
                    "due_date": min(job["due_date"] for job in batch_jobs)
                })
                batch_id += 1

    # Build schedule
    schedule = []
    job_results = []

    for m in model.M:
        machine_batches = []
        assigned_batches = []

        for b in model.B:
            if pyo.value(model.a[b, m]) > 0.5:
                batch_info = next((bat for bat in batches_formed if bat["internal_id"] == b), None)
                if batch_info:
                    assigned_batches.append((b, batch_info))

        assigned_batches.sort(key=lambda x: pyo.value(model.start[x[0]]))

        for b, batch_info in assigned_batches:
            start_time_val = pyo.value(model.start[b])
            completion_time = pyo.value(model.C_batch[b])

            setup_time_val = 0
            if machine_batches:
                prev_batch_internal_id = next(
                    (bat["internal_id"] for bat in batches_formed if bat["id"] == machine_batches[-1]["batch_id"]),
                    None
                )
                if prev_batch_internal_id is not None:
                    setup_time_val = pyo.value(model.active_setup[prev_batch_internal_id, b, m])

            batch_jobs = []
            for job in batch_info["jobs"]:
                job_id = job["id"]
                job_idx = next(i for i, j in enumerate(jobs) if j["id"] == job_id)
                tardiness = pyo.value(model.T_job[job_idx])

                batch_jobs.append({
                    "job_id": job_id,
                    "due_date": job["due_date"],
                    "tardiness": tardiness
                })

                job_results.append({
                    "job_id": job_id,
                    "batch_id": batch_info["id"],
                    "machine_id": machines[m]["id"],
                    "due_date": job["due_date"],
                    "completion_time": completion_time,
                    "tardiness": tardiness
                })

            machine_batches.append({
                "batch_id": batch_info["id"],
                "family": batch_info["family"],
                "customer": batch_info["customer"],
                "size": batch_info["size"],
                "proc_time": batch_info["proc_time"],
                "start_time": start_time_val,
                "completion_time": completion_time,
                "due_date": batch_info["due_date"],
                "setup_time": setup_time_val,
                "jobs": batch_jobs
            })

        schedule.append({
            "machine_id": machines[m]["id"],
            "capacity": machines[m]["capacity"],
            "batches": machine_batches
        })

    total_tardiness = sum(pyo.value(model.T_job[j]) for j in model.J)
    total_setup = pyo.value(model.TS)

    print(f"\n{'='*80}")
    print(f"INTEGRATED MILP SOLUTION")
    print(f"{'='*80}")
    print(f"Batches: {len(batches_formed)}")
    print(f"Total Tardiness: {total_tardiness:.2f}")
    print(f"Total Setup Time: {total_setup:.2f}")
    print(f"Solve Time: {solve_time:.2f}s")
    print(f"{'='*80}\n")

    return schedule, job_results, solve_time


# ============================================================================
# WRAPPER FUNCTION FOR EASY REPLACEMENT
# ============================================================================

def solve_integrated_milp_epsilon_safe(jobs, machines, epsilon_setup, **kwargs):
    """
    Safe wrapper that automatically retries with larger max_batches if infeasible.

    This is a drop-in replacement for solve_integrated_milp_epsilon.
    """

    # First try with default settings
    schedule, job_results, solve_time = solve_integrated_milp_epsilon(
        jobs, machines, epsilon_setup, **kwargs
    )

    if schedule is not None:
        return schedule, job_results, solve_time

    # If infeasible, retry with larger max_batches and no warm start
    print("\n" + "="*80)
    print("RETRY: Trying with larger max_batches and no warm start")
    print("="*80)

    # Calculate a much larger max_batches
    large_max_batches = max(len(jobs), 30)  # At least as many as jobs

    schedule, job_results, solve_time = solve_integrated_milp_epsilon(
        jobs, machines, epsilon_setup,
        use_warm_start=False,
        max_batches_override=large_max_batches,
        safety_buffer_factor=3.0,
        **{k: v for k, v in kwargs.items()
           if k not in ['use_warm_start', 'max_batches_override', 'safety_buffer_factor']}
    )

    return schedule, job_results, solve_time


