# ============================================================================
# PHASE 1.11 (H3): equal wall-clock budget for every heuristic
# ============================================================================
# The budget must be a floor as well as a ceiling.  Capping the proposed
# method while letting a benchmark stop early at its iteration limit produces
# exactly the asymmetry observed on 2026-09-04: FFD+SA-EDDTS 14.47 s per
# point against ALNS 1.24 s.  This wrapper restarts a stochastic solver from
# a fresh random state until the budget is spent and keeps the best result,
# so all methods are given the same effort and each uses it as it can.
# ============================================================================

def run_within_budget(solver_fn, budget_seconds, objective_key,
                      seed_base=0, max_restarts=50, verbose=False):
    # Repeatedly call solver_fn(remaining_seconds) until the budget is spent.
    # solver_fn must return a tuple whose first elements are
    #   (schedule, job_results, solve_time, primary_value, secondary_value)
    # objective_key selects which of the two is being minimised.
    import random as _random
    t0 = time.time()
    best = None
    best_val = float('inf')
    restarts = 0

    while restarts < max_restarts:
        elapsed = time.time() - t0
        remaining = budget_seconds - elapsed
        if restarts > 0 and remaining <= 0.5:
            break

        _random.seed(seed_base + restarts)
        try:
            result = solver_fn(max(remaining, 0.5))
        except Exception as exc:
            if verbose:
                print(f"  [budget] restart {restarts} failed: {exc}")
            break

        if result is None or result[0] is None:
            restarts += 1
            continue

        val = result[3] if objective_key == "primary" else result[4]
        if val is not None and val < best_val:
            best_val = val
            best = result
        restarts += 1

        if time.time() - t0 >= budget_seconds:
            break

    if verbose and best is not None:
        print(f"  [budget] {restarts} restart(s) in "
              f"{time.time() - t0:.1f}s, best = {best_val:.3f}")
    return best, restarts


# ============================================================================
# STAGE 2: SCHEDULING - EDDTS (EDD + Tabu Search)
# ============================================================================

def eddts_scheduling_epsilon(batches, machines, setup_times,
                              primary_objective="tardiness",
                              epsilon_value=1000,
                              max_iterations=100,
                              tabu_size=None,
                              range_primary=None,
                              range_secondary=None,
                              time_limit=None):
    """
    EDD + Tabu Search scheduling with epsilon-constraint support
    """
    start_time = time.time()

    # PHASE 1.10 (H1): scale-normalised penalty.
    # The old constant  PENALTY = 10000  was applied to a raw violation while
    # tardiness ran in the hundreds and setup in single digits, so a 0.1
    # violation outweighed the whole primary objective and the search became
    # single-objective.  Dividing both terms by their payoff-table ranges
    # makes M dimensionless and lets epsilon act as a slider again.
    # Ranges default to 1.0, which reproduces the previous behaviour if the
    # caller does not supply them.
    PENALTY = globals().get('EDDTS_PENALTY', 5.0)  # dimensionless
    _R1 = float(range_primary) if range_primary else 1.0
    _R2 = float(range_secondary) if range_secondary else 1.0
    if _R1 <= 0:
        _R1 = 1.0
    if _R2 <= 0:
        _R2 = 1.0

    def calculate_setup_time_between(prev_batch, curr_batch):
        """Calculate setup time between two batches"""
        if prev_batch is None:
            return 0
        prev_family = prev_batch.get("family", prev_batch.get("color", ""))
        curr_family = curr_batch.get("family", curr_batch.get("color", ""))
        return setup_times.get((prev_family, curr_family), 0)

    def evaluate_schedule_epsilon(schedule):
        """Evaluate schedule with epsilon-constraint penalty"""
        total_tardiness = 0
        total_setup = 0

        for machine in schedule:
            for batch in machine["batches"]:
                total_tardiness += batch.get("tardiness", 0)
                total_setup += batch.get("setup_time", 0)

        if primary_objective == "tardiness":
            violation = max(0.0, total_setup - epsilon_value)
            cost = total_tardiness / _R1 + PENALTY * violation / _R2
        else:
            violation = max(0.0, total_tardiness - epsilon_value)
            cost = total_setup / _R1 + PENALTY * violation / _R2

        return cost, total_tardiness, total_setup

    def build_initial_schedule(batches, machines, family_order=None):
        """Build initial schedule using EDD within color groups"""
        color_groups = {}
        for batch in batches:
            family = batch.get("family", batch.get("color", "unknown"))
            if family not in color_groups:
                color_groups[family] = []
            color_groups[family].append(batch)

        for color in color_groups:
            color_groups[color] = sorted(color_groups[color],
                                         key=lambda b: b.get("due_date", float('inf')))

        schedule = []
        for m in machines:
            schedule.append({
                "machine_id": m["id"],
                "capacity": m["capacity"],
                "batches": []
            })

        machine_completion = [0] * len(machines)

        for color in ([c for c in family_order if c in color_groups] if family_order
                      else sorted(color_groups.keys())):
            for batch in color_groups[color]:
                best_m = min(range(len(machines)), key=lambda i: machine_completion[i])

                prev_batch = schedule[best_m]["batches"][-1] if schedule[best_m]["batches"] else None
                setup = calculate_setup_time_between(prev_batch, batch)
                start = machine_completion[best_m]
                completion = start + setup + batch["proc_time"]

                batch_entry = {
                    "batch_id": batch.get("id", batch.get("batch_id")),
                    "family": batch.get("family", batch.get("color")),
                    "customer": batch.get("customer", ""),
                    "size": batch.get("size", 0),
                    "proc_time": batch["proc_time"],
                    "due_date": batch.get("due_date", float('inf')),
                    "start_time": start,
                    "setup_time": setup,
                    "completion_time": completion,
                    # PHASE 1.16: job-level tardiness, consistent with
                    # recalculate_times() and evaluate_machine_seq().  The
                    # previous expression charged the batch once against its
                    # EARLIEST due date, so a batch of k jobs was counted once
                    # here and k times in calculate_objectives().  It also fell
                    # back to float('inf') when due_date was absent, which
                    # silently produced zero tardiness.
                    "tardiness": sum(
                        max(0.0, completion - _job_due(j, batch))
                        for j in batch.get("jobs", [])),
                    "jobs": batch.get("jobs", [])
                }

                schedule[best_m]["batches"].append(batch_entry)
                machine_completion[best_m] = completion

        return schedule

    def recalculate_times(schedule):
        """Recalculate all times after a move"""
        for machine in schedule:
            prev_batch = None
            curr_time = 0

            for batch in machine["batches"]:
                setup = calculate_setup_time_between(prev_batch, batch)
                start = curr_time
                completion = start + setup + batch["proc_time"]

                batch["start_time"] = start
                batch["setup_time"] = setup
                batch["completion_time"] = completion

                # PHASE 1.8: tardiness must be summed over JOBS, using each
                # job's OWN due date.  The previous line charged the batch
                # once, against the batch's earliest due date:
                #     batch["tardiness"] = max(0, completion - batch["due_date"])
                # while calculate_objectives() sums job_results, where every
                # job in the batch carries that same value.  A batch of k jobs
                # was therefore counted k times outside and once inside, so
                # EDDTS optimised a different objective than it was scored on.
                # Observed on random_30j_3m_2c_6f: internal 148.81 vs external
                # 240.65, a ratio of 1.617 == the mean batch cardinality.
                batch["tardiness"] = sum(
                    max(0.0, completion - _job_due(job, batch))
                    for job in batch.get("jobs", []))

                curr_time = completion
                prev_batch = batch

        return schedule

    def _job_due(job, batch=None):
        """Due date of a job, resolved from the job itself, then from a
        lookup built over all batches, then from the batch.

        PHASE 1.16: never fall back to float('inf').  That fallback made
        max(0, C - d) evaluate to zero and produced a silent zero-tardiness
        report: on a 6-job instance the schedule's true tardiness was 42.03
        while calculate_objectives() returned 0.000.
        """
        if isinstance(job, dict):
            d = job.get("due_date")
            if d is not None:
                return d
            jid = job.get("id")
        else:
            jid = job
        d = _due_lookup.get(jid)
        if d is not None:
            return d
        if batch is not None:
            d = batch.get("due_date")
            if d is not None:
                return d
        return 0.0          # unknown due date is treated as already due

    _due_lookup = {}
    for _b in batches:
        for _j in _b.get("jobs", []):
            if isinstance(_j, dict) and _j.get("id") is not None:
                _due_lookup[_j["id"]] = _j.get("due_date", _b.get("due_date"))

    def evaluate_machine_seq(batch_list):
        """(tardiness, setup) for one machine's batch order.

        PHASE 1.15: mirrors recalculate_times() exactly but touches a single
        machine and mutates nothing, so it can be called thousands of times
        per iteration without copying anything.
        """
        t = 0.0
        s = 0.0
        prev = None
        clock = 0.0
        for b in batch_list:
            setup = calculate_setup_time_between(prev, b)
            completion = clock + setup + b["proc_time"]
            s += setup
            for job in b.get("jobs", []):
                t += max(0.0, completion - _job_due(job, b))
            clock = completion
            prev = b
        return t, s

    def affected_lists(schedule, move):
        """Batch orders of the machines a move touches, as shallow copies.

        Returns {machine_index: new_batch_list} or None if the move is not
        applicable to the current schedule.
        """
        kind = move[0]

        if kind == "move":
            _, from_m, b_idx, to_m = move
            src = schedule[from_m]["batches"]
            if b_idx >= len(src):
                return None
            new_src = src[:b_idx] + src[b_idx + 1:]
            if from_m == to_m:
                return {from_m: new_src + [src[b_idx]]}
            return {from_m: new_src,
                    to_m: schedule[to_m]["batches"] + [src[b_idx]]}

        if kind == "swap_internal":
            _, m_idx, i, j = move
            lst = schedule[m_idx]["batches"]
            if i >= len(lst) or j >= len(lst):
                return None
            new = list(lst)
            new[i], new[j] = new[j], new[i]
            return {m_idx: new}

        if kind == "insert":
            _, from_m, b_idx, to_m, pos = move
            src = schedule[from_m]["batches"]
            if b_idx >= len(src):
                return None
            batch = src[b_idx]
            new_src = src[:b_idx] + src[b_idx + 1:]
            if from_m == to_m:
                p = pos - 1 if pos > b_idx else pos
                p = max(0, min(p, len(new_src)))
                return {from_m: new_src[:p] + [batch] + new_src[p:]}
            dst = schedule[to_m]["batches"]
            p = max(0, min(pos, len(dst)))
            return {from_m: new_src, to_m: dst[:p] + [batch] + dst[p:]}

        if kind == "swap_machines":
            _, m1, b1, m2, b2 = move
            l1 = schedule[m1]["batches"]
            l2 = schedule[m2]["batches"]
            if b1 >= len(l1) or b2 >= len(l2):
                return None
            n1 = list(l1)
            n2 = list(l2)
            n1[b1], n2[b2] = l2[b2], l1[b1]
            return {m1: n1, m2: n2}

        return None

    def epsilon_cost(total_tardiness, total_setup):
        """Same penalty formula as evaluate_schedule_epsilon."""
        if primary_objective == "tardiness":
            violation = max(0.0, total_setup - epsilon_value)
            return total_tardiness / _R1 + PENALTY * violation / _R2
        violation = max(0.0, total_tardiness - epsilon_value)
        return total_setup / _R1 + PENALTY * violation / _R2

    def generate_neighbors(schedule):
        """Generate neighbor moves"""
        moves = []

        for from_m, machine in enumerate(schedule):
            for b_idx, batch in enumerate(machine["batches"]):
                for to_m in range(len(schedule)):
                    if from_m != to_m:
                        moves.append(("move", from_m, b_idx, to_m))

        for m_idx, machine in enumerate(schedule):
            for i in range(len(machine["batches"])):
                for j in range(i + 1, len(machine["batches"])):
                    moves.append(("swap_internal", m_idx, i, j))

        for m1 in range(len(schedule)):
            for b1 in range(len(schedule[m1]["batches"])):
                for m2 in range(m1 + 1, len(schedule)):
                    for b2 in range(len(schedule[m2]["batches"])):
                        moves.append(("swap_machines", m1, b1, m2, b2))

        # PHASE 1.9 (G3): colour-grouping insertions.
        # The "move" operator above always APPENDS to the end of the target
        # machine, so a batch can never be placed beside a same-colour batch
        # in the middle of a sequence.  Grouping colours is the only lever the
        # setup objective has, which is why the setup-minimising run searched
        # so poorly: it returned 3.78 where the tardiness run found 3.43.
        # These moves insert a batch directly after a batch of its own colour,
        # so the count is bounded by the number of same-colour pairs rather
        # than by all positions and the neighbourhood stays small.
        def _fam(b):
            return b.get("family", b.get("color"))

        for from_m, machine in enumerate(schedule):
            for b_idx, batch in enumerate(machine["batches"]):
                fam = _fam(batch)
                for to_m, target in enumerate(schedule):
                    for pos, other in enumerate(target["batches"]):
                        if from_m == to_m and pos == b_idx:
                            continue
                        if _fam(other) == fam:
                            moves.append(("insert", from_m, b_idx, to_m, pos + 1))

        return moves

    def apply_move(schedule, move):
        """Apply a move and return new schedule"""
        new_schedule = copy.deepcopy(schedule)
        move_type = move[0]

        if move_type == "move":
            _, from_m, b_idx, to_m = move
            if b_idx < len(new_schedule[from_m]["batches"]):
                batch = new_schedule[from_m]["batches"].pop(b_idx)
                new_schedule[to_m]["batches"].append(batch)

        elif move_type == "swap_internal":
            _, m_idx, i, j = move
            batches_list = new_schedule[m_idx]["batches"]
            if i < len(batches_list) and j < len(batches_list):
                batches_list[i], batches_list[j] = batches_list[j], batches_list[i]

        elif move_type == "insert":
            # PHASE 1.9 (G3): remove the batch and re-insert it at a chosen
            # position so it can land next to a same-colour batch.
            _, from_m, b_idx, to_m, pos = move
            if b_idx < len(new_schedule[from_m]["batches"]):
                batch = new_schedule[from_m]["batches"].pop(b_idx)
                if from_m == to_m and pos > b_idx:
                    pos -= 1
                pos = max(0, min(pos, len(new_schedule[to_m]["batches"])))
                new_schedule[to_m]["batches"].insert(pos, batch)

        elif move_type == "swap_machines":
            _, m1, b1, m2, b2 = move
            if (b1 < len(new_schedule[m1]["batches"]) and
                b2 < len(new_schedule[m2]["batches"])):
                batch1 = new_schedule[m1]["batches"][b1]
                batch2 = new_schedule[m2]["batches"][b2]
                new_schedule[m1]["batches"][b1] = batch2
                new_schedule[m2]["batches"][b2] = batch1

        return recalculate_times(new_schedule)

    # Main Tabu Search
    print(f"\n{'='*60}")
    print(f"EDDTS SCHEDULING (Epsilon-Constraint)")
    print(f"{'='*60}")
    print(f"Primary objective: {primary_objective}")
    print(f"Epsilon constraint: {'Setup' if primary_objective == 'tardiness' else 'Tardiness'} ≤ {epsilon_value}")
    print(f"Max iterations: {max_iterations}")

    if tabu_size is None:
        tabu_size = globals().get('TABU_TENURE', 15)
    if globals().get('EDDTS_MAX_ITER_OVERRIDE'):
        max_iterations = int(globals()['EDDTS_MAX_ITER_OVERRIDE'])

    _deadline = (start_time + time_limit) if time_limit else None

    # PHASE 1.11 (H3): tabu search is deterministic from a fixed start, so
    # simply giving it more time changes nothing.  Under a budget the search
    # is restarted from a shuffled batch order and the best run is kept, which
    # is how the extra time is actually used.
    _restart_count = 0
    _global_best = None
    _global_best_cost = float('inf')

    current = build_initial_schedule(batches, machines)
    best = copy.deepcopy(current)

    current_cost, curr_tard, curr_setup = evaluate_schedule_epsilon(current)
    best_cost = current_cost
    best_tard, best_setup = curr_tard, curr_setup

    tabu_list = []

    print(f"Initial: Tard={curr_tard:.2f}, Setup={curr_setup:.2f}, Cost={current_cost:.2f}")

    while True:
      # PHASE 1.11 (H3): outer restart loop.  Tabu search from a fixed start is
      # deterministic, so extra time only helps if the search is restarted from
      # a different point.  With no budget this runs exactly once and the
      # behaviour is unchanged.
      if _restart_count > 0:
        _sh = list(batches)
        random.Random(_restart_count + 1000003 * int(globals().get('RUN_SEED', 0))).shuffle(_sh)
        _fo = None
        if globals().get('EDDTS_RANDOM_FAMILY_ORDER', False):
            _fo = sorted({b.get('family', b.get('color', '')) for b in batches})
            random.Random(_restart_count + 1000003 * int(globals().get('RUN_SEED', 0))).shuffle(_fo)
        current = build_initial_schedule(_sh, machines, _fo)
        best = copy.deepcopy(current)
        best_cost, best_tard, best_setup = evaluate_schedule_epsilon(best)
        tabu_list = []

      for iteration in range(max_iterations):
        # PHASE 1.10 (H2): stop on the wall-clock budget, not only on the
        # iteration count, so every heuristic can be given the same budget.
        if _deadline is not None and time.time() >= _deadline:
            break

        moves = generate_neighbors(current)
        if not moves:
            break

        best_move = None
        best_move_cost = float('inf')
        best_neighbor = None
        best_neighbor_tard = 0
        best_neighbor_setup = 0

      #  for move in moves:
      #      if move in tabu_list:
      #          continue

      #      neighbor = apply_move(current, move)
      #      cost, tard, setup = evaluate_schedule_epsilon(neighbor)

      #      if cost < best_move_cost:
      #          best_move = move
      #          best_move_cost = cost
      #          best_neighbor = neighbor
      #          best_neighbor_tard = tard
      #          best_neighbor_setup = setup


        # PHASE 1.15: cache each machine's contribution once per iteration,
        # then score every candidate from the difference on the one or two
        # machines it touches.  No deep copy, no full re-walk.
        _per_machine = [evaluate_machine_seq(m["batches"]) for m in current]
        _base_t = sum(x[0] for x in _per_machine)
        _base_s = sum(x[1] for x in _per_machine)
        _tabu_set = set(tabu_list)

        for move in moves:
            lists = affected_lists(current, move)
            if lists is None:
                continue

            tard = _base_t
            setup = _base_s
            for _mi, _bl in lists.items():
                _nt, _ns = evaluate_machine_seq(_bl)
                tard += _nt - _per_machine[_mi][0]
                setup += _ns - _per_machine[_mi][1]

            cost = epsilon_cost(tard, setup)

            # Aspirasyon kriteri: tabu bir hamle, ancak küresel en iyiyi
            # iyileştiriyorsa yine de kabul edilir; aksi hâlde atlanır.
            is_tabu = move in _tabu_set
            if is_tabu and cost >= best_cost:
                continue

            if cost < best_move_cost:
                best_move = move
                best_move_cost = cost
                best_neighbor = None          # built after the scan
                best_neighbor_tard = tard
                best_neighbor_setup = setup

        # PHASE 1.15: one deep copy per iteration instead of one per candidate
        if best_move is not None:
            best_neighbor = apply_move(current, best_move)







        if best_move is None:
            break

        current = best_neighbor
        current_cost = best_move_cost

        if current_cost < best_cost:
            best = copy.deepcopy(current)
            best_cost = current_cost
            best_tard = best_neighbor_tard
            best_setup = best_neighbor_setup

            if (iteration + 1) % 10 == 0 and _restart_count == 0:
                print(f"  Iter {iteration+1}: NEW BEST Tard={best_tard:.2f}, Setup={best_setup:.2f}")

        tabu_list.append(best_move)
        if len(tabu_list) > tabu_size:
            tabu_list.pop(0)

      # --- one tabu-search run finished: keep the best across restarts
      _c_now, _t_now, _s_now = evaluate_schedule_epsilon(best)
      if _c_now < _global_best_cost:
          _global_best_cost = _c_now
          _global_best = copy.deepcopy(best)
          _gb_tard, _gb_setup = _t_now, _s_now
      _restart_count += 1

      # PHASE 1.15: with incremental evaluation a 10 s budget now fits about
      # 50 restarts where it previously fit 2, so the old cap of 50 became
      # the binding constraint instead of the clock.
      if (_deadline is None or time.time() >= _deadline
              or _restart_count >= 500
              or not globals().get('EDDTS_RESTARTS', True)):
          break

    if _global_best is not None:
        best = _global_best
        best_tard, best_setup = _gb_tard, _gb_setup

    solve_time = time.time() - start_time
    if _restart_count > 1:
        print(f"  [budget] {_restart_count} restarts in {solve_time:.1f}s")

    # Extract job results
    job_results = []
    for machine in best:
        for batch in machine["batches"]:
            for job in batch.get("jobs", []):
                job_id = job.get("id", job) if isinstance(job, dict) else job
                # PHASE 1.16: computed here rather than looked up in a cached
                # dict.  The cache was absent on schedules produced by
                # build_initial_schedule, and .get(job_id, 0.0) then returned
                # zero for every job without raising.
                job_results.append({
                    "job_id": job_id,
                    "batch_id": batch["batch_id"],
                    "machine_id": machine["machine_id"],
                    "completion_time": batch["completion_time"],
                    "tardiness": max(0.0, batch["completion_time"]
                                     - _job_due(job, batch))
                })

    print(f"\n{'='*60}")
    print(f"EDDTS RESULT")
    print(f"{'='*60}")
    print(f"Total Tardiness: {best_tard:.2f}")
    print(f"Total Setup Time: {best_setup:.2f}")
    print(f"Solve Time: {solve_time:.2f}s")

    if primary_objective == "tardiness":
        if best_setup <= epsilon_value:
            print(f"✓ Epsilon constraint SATISFIED (Setup {best_setup:.2f} ≤ {epsilon_value})")
        else:
            print(f"✘ Epsilon constraint VIOLATED (Setup {best_setup:.2f} > {epsilon_value})")
    else:
        if best_tard <= epsilon_value:
            print(f"✓ Epsilon constraint SATISFIED (Tard {best_tard:.2f} ≤ {epsilon_value})")
        else:
            print(f"✘ Epsilon constraint VIOLATED (Tard {best_tard:.2f} > {epsilon_value})")

    return best, job_results, solve_time, best_tard, best_setup


# ============================================================================
# STAGE 2: SCHEDULING - ALNS (Adaptive Large Neighborhood Search)
# ============================================================================


class ALNS_Epsilon:
    """
    Adaptive Large Neighborhood Search with Epsilon-Constraint support

    IMPROVEMENTS:
    - Adaptive penalty system (gentle → strict over iterations)
    - Higher initial temperature for better exploration
    - Slower cooling rate
    - Violation tracking
    - Better parameter defaults (2000 iterations, 900s time limit)
    """

    def __init__(self, jobs, machines, setup_times, machine_capacity):
        self.jobs = jobs
        self.machines = machines
        self.setup_times = setup_times
        self.capacity = machine_capacity

        # Create lookup dictionary for fast job access
        self.job_lookup = {job['id']: job for job in jobs}

        # Destroy operator weights (adaptive)
        self.destroy_weights = {
            'random': 1.0,
            'worst': 1.0,
            'related': 1.0,
            'color_based': 1.0
        }

        # Repair operator weights (adaptive)
        self.repair_weights = {
            'greedy': 1.0,
            'regret': 1.0,
            'random': 1.0,
            'best_fit': 1.0
        }

        # Adaptive weight parameters
        self.reaction_factor = (globals().get('ALNS_DECAY', 0.8)
                                if globals().get('FIX_ALNS_DECAY', False) else 0.8)
        self.score_best = 10      # Score for finding new best solution
        self.score_better = 5     # Score for finding better solution
        self.score_accepted = 2   # Score for accepted solution

        # Operator performance tracking
        self.operator_scores = {
            'destroy': {op: 0 for op in self.destroy_weights},
            'repair': {op: 0 for op in self.repair_weights}
        }
        self.operator_counts = {
            'destroy': {op: 1 for op in self.destroy_weights},
            'repair': {op: 1 for op in self.repair_weights}
        }

    def solve_epsilon_budgeted(self, primary_objective="tardiness",
                               epsilon_value=1000, max_iterations=2000,
                               budget_seconds=10.0, max_restarts=50,
                               verbose=True, range_primary=None,
                               range_secondary=None):
        """Restart the annealing run until the wall-clock budget is spent.

        PHASE 1.12 (J3): each restart gets a full cooling schedule, so the
        extra time is actually used for search instead of spinning at zero
        temperature.  Mirrors the restart loop added to EDDTS.
        """
        import time as _t
        t0 = _t.time()
        best = None
        best_key = (True, float('inf'), float('inf'))
        restarts = 0

        while restarts < max_restarts:
            remaining = budget_seconds - (_t.time() - t0)
            if restarts > 0 and remaining <= 0.3:
                break
            result = self.solve_epsilon(
                primary_objective=primary_objective,
                epsilon_value=epsilon_value,
                max_iterations=max_iterations,
                time_limit=max(remaining, 0.3),
                verbose=(restarts == 0),
                range_primary=range_primary,
                range_secondary=range_secondary)
            restarts += 1
            if result is None or result[0] is None:
                continue

            # PHASE 1.14: rank restarts FEASIBILITY FIRST, then by the primary
            # objective.  Selecting purely on tardiness picked an
            # epsilon-violating run out of eleven feasible-or-not candidates,
            # which the G2 filter then discarded -- on 2026-09-05 all four of
            # ALNS's intermediate points were lost this way and its front
            # collapsed to the two boundary points.
            _tard, _setup = result[3], result[4]
            if primary_objective == "tardiness":
                _primary, _constrained = _tard, _setup
            else:
                _primary, _constrained = _setup, _tard
            _violation = max(0.0, (_constrained or 0.0) - epsilon_value)
            key = (_violation > 1e-6, _violation, _primary)

            if best is None or key < best_key:
                best_key, best = key, result
            if _t.time() - t0 >= budget_seconds:
                break

        elapsed = _t.time() - t0
        if verbose and restarts > 1 and best is not None:
            _feas = "infeasible" if best_key[0] else "feasible"
            print(f"  [budget] {restarts} ALNS restarts in {elapsed:.1f}s, "
                  f"best = {best_key[2]:.3f} ({_feas})")

        # PHASE 1.13 (L2): report the budget actually consumed, not the last
        # inner run.  The comparison table printed 1.05 s for ALNS while the
        # method had in fact used the full 10 s per point.
        if best is not None:
            best = (best[0], best[1], elapsed) + tuple(best[3:])
        return best

    def solve_epsilon(self, primary_objective="tardiness", epsilon_value=1000,
                      max_iterations=2000, time_limit=900, verbose=True,
                      range_primary=None, range_secondary=None):
        """
        Main ALNS with improved epsilon-constraint handling

        Parameters:
        -----------
        primary_objective : str
            "tardiness" or "setup_time" - which objective to minimize
        epsilon_value : float
            Upper bound on the constrained objective
        max_iterations : int
            Maximum number of ALNS iterations (default: 2000)
        time_limit : int
            Time limit in seconds (default: 900s = 15 minutes)
        """
        if verbose:
            print(f"\n{'='*80}")
            print(f"ALNS WITH EPSILON-CONSTRAINT (IMPROVED)")
            print(f"{'='*80}")
            print(f"Primary objective: Minimize {primary_objective}")
            print(f"Epsilon constraint: {'Setup' if primary_objective == 'tardiness' else 'Tardiness'} ≤ {epsilon_value}")
            print(f"Max iterations: {max_iterations}, Time limit: {time_limit:.1f}s")

        start_time = time.time()

        # IMPROVED: Adaptive penalty that increases over time
        # Starts gentle (exploration), becomes strict (exploitation)
        # PHASE 1.13 (L1): the same scale defect that was fixed in EDDTS.
        # PENALTY_START/END were applied to a RAW violation while tardiness ran
        # in the hundreds and setup in single digits, so a violation of 0.05
        # already outweighed the primary objective and the search became
        # single-objective.  Observed on 2026-09-05: the violation rate sat at
        # 100% for every intermediate point.  Both terms are now divided by
        # their payoff-table ranges, so the coefficients are dimensionless.
        _R1 = float(range_primary) if range_primary else 1.0
        _R2 = float(range_secondary) if range_secondary else 1.0
        if _R1 <= 0:
            _R1 = 1.0
        if _R2 <= 0:
            _R2 = 1.0
        # Calibrated so that the normalised penalty reproduces the strength of
        # the original raw coefficients (1e4 -> 1e5 against a tardiness scale
        # of a few hundred): a violation of 1% of the setup range costs about
        # as much as the entire tardiness range.  The epsilon constraint stays
        # effectively hard, which is what the epsilon-constraint method needs;
        # the only thing that changes is that the strength no longer depends
        # on the instance's units.  A first attempt with 2 -> 20 was far too
        # soft and raised the violation rate instead of lowering it.
        PENALTY_START = globals().get('ALNS_PENALTY_START', 100.0)
        PENALTY_END = globals().get('ALNS_PENALTY_END', 1000.0)

        def evaluate_with_epsilon(solution, iteration):
            """
            Evaluate solution with adaptive penalty

            Returns: cost, tardiness, setup_time, violation_amount
            """
            tard, setup = self.evaluate_solution(solution)

            # Calculate adaptive penalty based on iteration progress
            progress = iteration / max_iterations
            current_penalty = PENALTY_START + (PENALTY_END - PENALTY_START) * progress

            if primary_objective == "tardiness":
                violation = max(0, setup - epsilon_value)
                cost = tard / _R1 + current_penalty * violation / _R2
            else:
                violation = max(0, tard - epsilon_value)
                cost = setup / _R1 + current_penalty * violation / _R2

            return cost, tard, setup, violation

        # Generate initial solution
        current = self.generate_initial_solution()
        best = copy.deepcopy(current)

        current_cost, curr_tard, curr_setup, _ = evaluate_with_epsilon(current, 0)
        best_cost = current_cost
        best_tard, best_setup = curr_tard, curr_setup

        # IMPROVED: Higher initial temperature for better exploration
        temperature = current_cost * 0.5  # Was 0.1, now 0.5 for more exploration
        cooling_rate = globals().get('ALNS_COOLING_RATE', 0.998)
        min_temperature = 0.01            # Minimum temperature threshold

        if verbose: print(f"\nInitial solution:")
        if verbose: print(f"  Tardiness: {curr_tard:.2f}")
        if verbose: print(f"  Setup Time: {curr_setup:.2f}")
        if verbose: print(f"  Initial Temperature: {temperature:.2f}")

        # Statistics tracking
        successful_iterations = 0
        failed_iterations = 0
        violations_count = 0
        accepted_count = 0
        improvements_count = 0

        # Main ALNS loop
        # PHASE 1.12 (J1): lifting the iteration cap was the wrong way to
        # spend a budget.  The cooling schedule is indexed by max_iterations,
        # so past that point the temperature is zero and the search degenerates
        # into a stalled hill-climb -- observed on 2026-09-04: 1.37 million
        # iterations over 370 s with the incumbent frozen at 213.03 from the
        # first few seconds.  The cap is restored; the budget is spent by
        # RESTARTING the whole annealing run (see solve_epsilon_budgeted).
        for iteration in range(max_iterations):
            if time.time() - start_time > time_limit:
                print(f"\n⏱ Time limit reached at iteration {iteration}")
                break

            # Select operators
            destroy_op = self.select_operator(self.destroy_weights)
            repair_op = self.select_operator(self.repair_weights)

            try:
                # Apply destroy and repair
                destroyed = self.destroy(current, destroy_op)
                repaired = self.repair(destroyed, repair_op)
                new_cost, new_tard, new_setup, violation = evaluate_with_epsilon(repaired, iteration)

                successful_iterations += 1

                # Track violations
                if violation > 0:
                    violations_count += 1

            except Exception as e:
                failed_iterations += 1
                if failed_iterations <= 10:
                    print(f"  ⚠ Iteration {iteration} failed: {type(e).__name__}: {str(e)[:50]}")
                continue

            # Update operator usage counts
            self.operator_counts['destroy'][destroy_op] += 1
            self.operator_counts['repair'][repair_op] += 1

            # Calculate acceptance probability
            delta = new_cost - current_cost
            if delta <= 0:
                accept_prob = 1.0
            else:
                accept_prob = min(1.0, math.exp(-delta / max(temperature, min_temperature)))

            # Accept or reject new solution
            if random.random() < accept_prob:
                current = repaired
                current_cost = new_cost
                accepted_count += 1

                # Update best solution
                if new_cost < best_cost:
                    best = copy.deepcopy(repaired)
                    best_cost = new_cost
                    best_tard = new_tard
                    best_setup = new_setup
                    improvements_count += 1

                    # Reward operators that found new best
                    self.operator_scores['destroy'][destroy_op] += self.score_best
                    self.operator_scores['repair'][repair_op] += self.score_best

                    # Progress reporting every 200 iterations
                    if iteration % 200 == 0 or iteration < 100:
                        viol_str = f", Violation={violation:.2f}" if violation > 0 else ""
                        print(f"  Iter {iteration:4d}: 🌟 NEW BEST Tard={best_tard:.2f}, Setup={best_setup:.2f}{viol_str}")

                elif new_cost < current_cost:
                    # Better but not best - still reward
                    self.operator_scores['destroy'][destroy_op] += self.score_better
                    self.operator_scores['repair'][repair_op] += self.score_better
                else:
                    # Accepted despite being worse - small reward
                    self.operator_scores['destroy'][destroy_op] += self.score_accepted
                    self.operator_scores['repair'][repair_op] += self.score_accepted

            # Cool down temperature
            temperature *= cooling_rate

            # Update operator weights periodically
            if iteration > 0 and iteration % 100 == 0:
                self.update_weights()

                # Progress report every 500 iterations
                if iteration % 500 == 0:
                    progress_pct = (iteration / max_iterations) * 100
                    elapsed = time.time() - start_time
                    if verbose:
                        print(f"\n  Progress: {progress_pct:.1f}% ({iteration}/{max_iterations})")
                    print(f"  Elapsed: {elapsed:.1f}s, Temperature: {temperature:.2f}")
                    print(f"  Current Best: Tard={best_tard:.2f}, Setup={best_setup:.2f}")

        # Calculate final statistics
        solve_time = time.time() - start_time
        acceptance_rate = (accepted_count / max(successful_iterations, 1)) * 100
        improvement_rate = (improvements_count / max(successful_iterations, 1)) * 100
        violation_rate = (violations_count / max(successful_iterations, 1)) * 100

        # Print detailed statistics
        if verbose: print(f"\n{'='*80}")
        if verbose: print(f"ALNS ITERATION STATISTICS")
        if verbose: print(f"{'='*80}")
        if verbose: print(f"✓ Successful iterations: {successful_iterations}/{max_iterations} ({100*successful_iterations/max_iterations:.1f}%)")
        if verbose: print(f"✗ Failed iterations: {failed_iterations}/{max_iterations} ({100*failed_iterations/max_iterations:.1f}%)")
        if verbose: print(f"✓ Accepted solutions: {accepted_count}/{successful_iterations} ({acceptance_rate:.1f}%)")
        if verbose: print(f"🌟 Improvements found: {improvements_count} ({improvement_rate:.1f}%)")
        if verbose: print(f"⚠ Constraint violations: {violations_count}/{successful_iterations} ({violation_rate:.1f}%)")

        if failed_iterations > max_iterations * 0.1:
            print(f"⚠ WARNING: High failure rate detected! Check destroy/repair operators.")

        if violation_rate > 50:
            print(f"⚠ WARNING: High violation rate. Solution may not satisfy epsilon constraint.")

        # Print final results
        if verbose: print(f"\n{'='*80}")
        if verbose: print(f"ALNS FINAL RESULT")
        if verbose: print(f"{'='*80}")
        if verbose: print(f"Total Tardiness: {best_tard:.2f}")
        if verbose: print(f"Total Setup Time: {best_setup:.2f}")
        if verbose: print(f"Solve Time: {solve_time:.2f}s ({solve_time/60:.1f} minutes)")
        if verbose: print(f"Iterations per second: {successful_iterations/solve_time:.1f}")

        # Check constraint satisfaction
        if primary_objective == "tardiness":
            satisfied = best_setup <= epsilon_value
            margin = epsilon_value - best_setup
            print(f"\n{'✓' if satisfied else '✗'} Setup constraint: {best_setup:.2f} {'≤' if satisfied else '>'} {epsilon_value}")
            if satisfied:
                print(f"  Margin: {margin:.2f} ({margin/epsilon_value*100:.1f}% slack)")
            else:
                print(f"  Violation: {-margin:.2f} ({-margin/epsilon_value*100:.1f}% over)")
        else:
            satisfied = best_tard <= epsilon_value
            margin = epsilon_value - best_tard
            print(f"\n{'✓' if satisfied else '✗'} Tardiness constraint: {best_tard:.2f} {'≤' if satisfied else '>'} {epsilon_value}")
            if satisfied:
                print(f"  Margin: {margin:.2f} ({margin/epsilon_value*100:.1f}% slack)")
            else:
                print(f"  Violation: {-margin:.2f} ({-margin/epsilon_value*100:.1f}% over)")

        if verbose: print(f"{'='*80}\n")

        # Convert to schedule format and return
        schedule, job_results = self.solution_to_schedule(best)
        return schedule, job_results, solve_time, best_tard, best_setup

    def generate_initial_solution(self):
        """
        Generate initial solution using FFD (First Fit Decreasing) + EDD (Earliest Due Date)

        1. Group jobs by (color, customer)
        2. Sort jobs by size (descending)
        3. Pack into batches using FFD
        4. Assign batches to machines using EDD
        """
        # Group jobs by color and customer
        groups = {}
        for job in self.jobs:
            key = (job['color'], job['customer'])
            if key not in groups:
                groups[key] = []
            groups[key].append(job)

        batches = []
        batch_id = 1

        # Create batches for each group using FFD
        for (color, customer), group_jobs in groups.items():
            # Sort by size descending (FFD)
            jobs_sorted = sorted(group_jobs, key=lambda j: -j['size'])

            current_batch = []
            current_size = 0

            for job in jobs_sorted:
                if current_size + job['size'] <= self.capacity:
                    # Add to current batch
                    current_batch.append(job)
                    current_size += job['size']
                else:
                    # Start new batch
                    if current_batch:
                        batches.append(self._create_batch(batch_id, current_batch, color, customer))
                        batch_id += 1
                    current_batch = [job]
                    current_size = job['size']

            # Add remaining batch
            if current_batch:
                batches.append(self._create_batch(batch_id, current_batch, color, customer))
                batch_id += 1

        # Create solution structure
        solution = {
            'batches': batches,
            'machines': {m: [] for m in range(len(self.machines))}
        }

        # Assign batches to machines using EDD (Earliest Due Date)
        batches_sorted = sorted(batches, key=lambda b: b['due_date'])
        for i, batch in enumerate(batches_sorted):
            machine = i % len(self.machines)  # Round-robin assignment
            batch['machine'] = machine
            solution['machines'][machine].append(batch['id'])

        return solution

    def _create_batch(self, batch_id, jobs, color, customer):
        """Create batch dictionary from list of jobs"""
        return {
            'id': batch_id,
            'jobs': [j['id'] for j in jobs],
            'family': color,
            'customer': customer,
            'size': sum(j['size'] for j in jobs),
            'proc_time': max(j['proc_time'] for j in jobs),  # Max processing time in batch
            'due_date': min(j['due_date'] for j in jobs),    # Earliest due date in batch
            'machine': 0
        }

    def evaluate_solution(self, solution):
        """
        Calculate total tardiness and total setup time for a solution

        Returns: (total_tardiness, total_setup_time)
        """
        total_tardiness = 0
        total_setup = 0

        # Evaluate each machine's schedule
        for machine in range(len(self.machines)):
            prev_batch = None
            completion = 0

            # Process batches in order on this machine
            for bid in solution['machines'][machine]:
                batch = next((b for b in solution['batches'] if b['id'] == bid), None)
                if batch is None:
                    continue

                # Add setup time if there's a previous batch
                if prev_batch:
                    setup = self.setup_times.get((prev_batch['family'], batch['family']), 0)
                    total_setup += setup
                    completion += setup

                # Add processing time
                completion += batch['proc_time']

                # Calculate tardiness for all jobs in batch
                for job_id in batch['jobs']:
                    job = self.job_lookup.get(job_id)
                    if job:
                        tardiness = max(0, completion - job['due_date'])
                        total_tardiness += tardiness

                prev_batch = batch

        return total_tardiness, total_setup


    def destroy(self, solution, operator):
        """
        Apply destroy operator to remove batches from solution

        Operators:
        - random: Remove random batches
        - worst: Remove batches with highest tardiness
        - related: Remove batches with same color/customer
        - color_based: Remove all batches of a specific color
        """
        destroyed = copy.deepcopy(solution)

         # NEW: More aggressive for small instances
        num_batches = len(solution['batches'])
        if num_batches <= 10:
            removal_rate = random.uniform(0.4, 0.6)  # 40-60% for small
        elif num_batches <= 20:
            removal_rate = random.uniform(0.3, 0.5)  # 30-50% for medium
        else:
            removal_rate = random.uniform(0.2, 0.4)  # 20-40% for large

        n_remove = max(2, int(num_batches * removal_rate))  # At least 2

        # Determine number of batches to remove (20-40% of total)
        # PHASE 1.7: this line used to sit here and silently discarded the
        # adaptive schedule computed just above, so the aggressive
        # small-instance rate never fired (effective rate was always 20-40%).
        # n_remove = max(1, int(len(solution['batches']) * random.uniform(0.2, 0.4)))
        to_remove = []

        if operator == 'random':
            # Remove random batches
            to_remove = random.sample(range(len(destroyed['batches'])),
                                     min(n_remove, len(destroyed['batches'])))

        elif operator == 'worst':
            # Remove batches with highest tardiness contribution
            batch_scores = []
            for i, batch in enumerate(destroyed['batches']):
                # Estimate tardiness impact
                tard = sum(max(0, batch['proc_time'] - self.job_lookup[j]['due_date'])
                          for j in batch['jobs'] if j in self.job_lookup)
                batch_scores.append((tard, i))

            batch_scores.sort(reverse=True)
            to_remove = [idx for _, idx in batch_scores[:n_remove]]

        elif operator == 'related':
            # Remove related batches (same color or customer)
            if destroyed['batches']:
                seed = random.choice(destroyed['batches'])
                related = [i for i, b in enumerate(destroyed['batches'])
                          if b['family'] == seed['family'] or b['customer'] == seed['customer']]
                to_remove = related[:min(n_remove, len(related))]

        elif operator == 'color_based':
            # Remove all batches of a specific color
            if destroyed['batches']:
                colors = list(set(b['family'] for b in destroyed['batches']))
                target_color = random.choice(colors)
                to_remove = [i for i, b in enumerate(destroyed['batches'])
                            if b['family'] == target_color][:n_remove]

        # Remove batches and collect their jobs
        removed_jobs = []
        for idx in sorted(to_remove, reverse=True):
            if idx < len(destroyed['batches']):
                batch = destroyed['batches'].pop(idx)
                removed_jobs.extend(batch['jobs'])

                # Remove from machine assignment
                machine = batch['machine']
                if batch['id'] in destroyed['machines'][machine]:
                    destroyed['machines'][machine].remove(batch['id'])

        destroyed['removed_jobs'] = removed_jobs
        return destroyed






    def repair(self, destroyed, operator):
        """
        Apply repair operator to reinsert removed jobs.

        Operators:
        - greedy   : Insert each job (in arbitrary order) into the compatible
                     batch with the earliest due date; new batch if none fits.
        - regret   : Regret-2 insertion. Repeatedly insert the job whose
                     (second-best cost − best-best cost) regret is largest,
                     placing it in its best batch. Prioritizes jobs that would
                     "suffer most" if deferred.
        - random   : Insert each job into a random compatible batch.
        - best_fit : Insert each job into the compatible batch that leaves the
                     least residual capacity (tightest fit), improving packing.
        """
        solution = copy.deepcopy(destroyed)
        removed_jobs = solution.pop('removed_jobs', [])

        if not removed_jobs:
            return solution

        # ---- REGRET-2 INSERTION ------------------------------------------
        if operator == 'regret':
            pending = list(removed_jobs)
            while pending:
                best_job = None
                best_job_batch = None
                best_regret = -float('inf')
                best_job_cost = float('inf')

                for job_id in pending:
                    job = self.job_lookup.get(job_id)
                    if job is None:
                        continue

                    # Cost of inserting this job into each compatible batch.
                    # Lower cost = better. We use the batch due date as the
                    # insertion cost (consistent with the greedy operator),
                    # so that same-color consolidation with tight due dates
                    # is preferred.
                    costs = []
                    for b in solution['batches']:
                        if self._can_add_job(job, b):
                            # PHASE 1.7: was b['due_date'], which is not a
                            # cost and is blind to the setup objective.
                            costs.append(insertion_cost(job, b, self.capacity))

                    if len(costs) == 0:
                        # No compatible batch: opening a new batch is the only
                        # option. Assign it a large regret so it is placed now
                        # rather than deferred (its situation cannot improve).
                        regret = float('inf')
                        insert_cost = float('inf')
                    else:
                        costs.sort()
                        best_cost = costs[0]
                        second = costs[1] if len(costs) > 1 else costs[0]
                        regret = second - best_cost
                        insert_cost = best_cost

                    # Select the job with the largest regret; break ties by
                    # the cheaper best-insertion cost.
                    if (regret > best_regret or
                            (regret == best_regret and insert_cost < best_job_cost)):
                        best_regret = regret
                        best_job = job
                        best_job_cost = insert_cost
                        # Remember the actual best batch object for this job
                        best_job_batch = None
                        cheapest = float('inf')
                        for b in solution['batches']:
                            if self._can_add_job(job, b) and b['due_date'] < cheapest:
                                cheapest = b['due_date']
                                best_job_batch = b

                if best_job is None:
                    break

                if best_job_batch is not None:
                    self._add_job_to_batch(best_job, best_job_batch)
                else:
                    self._create_new_batch_for_job(solution, best_job)

                pending.remove(best_job['id'])

            return solution

        # ---- PER-JOB OPERATORS (greedy / best_fit / random) --------------
        for job_id in removed_jobs:
            job = self.job_lookup.get(job_id)
            if job is None:
                continue

            inserted = False

            if operator == 'greedy':
                # Earliest-due-date compatible batch
                best_batch = None
                best_score = float('inf')
                for batch in solution['batches']:
                    if self._can_add_job(job, batch):
                        # PHASE 1.7: was batch['due_date'] (see above)
                        score = insertion_cost(job, batch, self.capacity)
                        if score < best_score:
                            best_score = score
                            best_batch = batch
                if best_batch:
                    self._add_job_to_batch(job, best_batch)
                    inserted = True

            elif operator == 'best_fit':
                # Tightest residual-capacity compatible batch (better packing)
                best_batch = None
                best_residual = float('inf')
                for batch in solution['batches']:
                    if self._can_add_job(job, batch):
                        residual = self.capacity - (batch['size'] + job['size'])
                        if residual < best_residual:
                            best_residual = residual
                            best_batch = batch
                if best_batch:
                    self._add_job_to_batch(job, best_batch)
                    inserted = True

            elif operator == 'random':
                compatible = [b for b in solution['batches'] if self._can_add_job(job, b)]
                if compatible:
                    batch = random.choice(compatible)
                    self._add_job_to_batch(job, batch)
                    inserted = True

            if not inserted:
                self._create_new_batch_for_job(solution, job)

        return solution



