# COMPARISON AND ANALYSIS FUNCTIONS
# ============================================================================

def get_approaches_for_comparison(preset, custom_list=None):
    """Get list of approaches based on preset"""
    presets = {
        "ALL": ["INTEGRATED", "MILP1+MILP2", "FFD+SA-MILP2", "MILP1+EDDTS", "FFD+SA-EDDTS", "ALNS", "NSGA-II", "LPT+EDD"],
        "NO_INTEGRATED": ["MILP1+MILP2", "FFD+SA-MILP2", "FFD+SA-EDDTS", "ALNS", "NSGA-II", "LPT+EDD"],
        "HEURISTICS": ["FFD+SA-EDDTS", "ALNS", "NSGA-II", "LPT+EDD"],
        "MILP_ONLY": ["INTEGRATED", "MILP1+MILP2", "FFD+SA-MILP2"],
        "EXACT_ONLY": ["INTEGRATED", "MILP1+MILP2"],
        "CUSTOM": custom_list if custom_list else []
    }
    return presets.get(preset, presets["HEURISTICS"])


def get_approaches_for_size(num_jobs, tier_config):
    """
    Get appropriate approaches based on problem size

    Tier 1 (≤15 jobs): All approaches including INTEGRATED
    Tier 2 (16-25 jobs): Exclude INTEGRATED (too slow)
    Tier 3 (>25 jobs): Only scalable approaches
    """
    if num_jobs <= tier_config["TIER_1_MAX_JOBS"]:
        return ["INTEGRATED", "MILP1+MILP2", "FFD+SA-MILP2", "MILP1+EDDTS", "FFD+SA-EDDTS", "ALNS", "NSGA-II", "LPT+EDD"], "TIER_1"
    elif num_jobs <= tier_config["TIER_2_MAX_JOBS"]:
        return ["MILP1+MILP2", "FFD+SA-MILP2", "MILP1+EDDTS", "FFD+SA-EDDTS", "ALNS", "NSGA-II", "LPT+EDD"], "TIER_2"
    else:
        return ["FFD+SA-EDDTS", "ALNS", "NSGA-II", "LPT+EDD"], "TIER_3"


def compare_approaches(jobs, machines, approaches, num_points=16, time_limit=600, setup_matrix=None):
    """Compare multiple approaches on a single dataset"""

    print(f"\n  Comparing {len(approaches)} approaches...")

    all_results = {}
    comparison_data = []

    for idx, approach_name in enumerate(approaches, 1):
        print(f"\n    [{idx}/{len(approaches)}] {approach_name}...", end=" ", flush=True)

        try:
            start_time_compare = time.time()

            pareto_solutions, pareto_df = generate_pareto_front_epsilon(
                jobs, machines,
                approach=approach_name,
                num_points=num_pareto_points,
                time_limit_per_point=time_limit,
                setup_matrix=setup_matrix
            )

            total_time = time.time() - start_time_compare

            if pareto_solutions:
                tardiness_values = [sol['tardiness'] for sol in pareto_solutions]
                setup_values = [sol['setup_time'] for sol in pareto_solutions]

                all_results[approach_name] = {
                    'pareto_solutions': pareto_solutions,
                    'pareto_df': pareto_df,
                    'total_time': total_time,
                    'num_points': len(pareto_solutions),
                    'min_tardiness': min(tardiness_values),
                    'max_tardiness': max(tardiness_values),
                    'min_setup': min(setup_values),
                    'max_setup': max(setup_values),
                    'avg_solve_time': np.mean([sol['solve_time'] for sol in pareto_solutions])
                }

                comparison_data.append({
                    'Approach': approach_name,
                    'Points': len(pareto_solutions),
                    'Min_Tard': round(min(tardiness_values), 2),
                    'Max_Tard': round(max(tardiness_values), 2),
                    'Min_Setup': round(min(setup_values), 2),
                    'Max_Setup': round(max(setup_values), 2),
                    'Avg_Time': round(np.mean([sol['solve_time'] for sol in pareto_solutions]), 2),
                    'Total_Time': round(total_time, 2)
                })

                print(f"✓ (Tard: {min(tardiness_values):.1f}-{max(tardiness_values):.1f})")
            else:
                print(f"✘ Failed")
                all_results[approach_name] = None

        except Exception as e:
            print(f"✘ Error: {str(e)[:40]}")
            all_results[approach_name] = None

    comparison_df = pd.DataFrame(comparison_data)
    return all_results, comparison_df


def print_comparison_results(comparison_df, dataset_name=""):
    """Print formatted comparison results"""

    print("\n" + "="*100)
    print(f"COMPARISON RESULTS{' - ' + dataset_name if dataset_name else ''}")
    print("="*100)

    if len(comparison_df) == 0:
        print("No results to display")
        return

    print("\n" + comparison_df.to_string(index=False))

    print("\n" + "-"*100)
    print("RANKINGS:")
    print("-"*100)

    best_tard = comparison_df.loc[comparison_df['Min_Tard'].idxmin()]
    print(f"  🏆 Best Tardiness:  {best_tard['Approach']} (Min={best_tard['Min_Tard']:.2f})")

    best_setup = comparison_df.loc[comparison_df['Min_Setup'].idxmin()]
    print(f"  🏆 Best Setup:      {best_setup['Approach']} (Min={best_setup['Min_Setup']:.2f})")

    fastest = comparison_df.loc[comparison_df['Total_Time'].idxmin()]
    print(f"  ⚡ Fastest:         {fastest['Approach']} ({fastest['Total_Time']:.2f}s)")

    print("="*100)


