def visualize_schedule(schedule, title="Schedule Gantt Chart"):
    """Visualize Gantt chart with improved readability"""
    if not schedule:
        print("Warning: Empty schedule")
        return

    fig, ax = plt.subplots(figsize=(16, 10))

    colors = {
        'pastel': '#FFB3BA',
        'light': '#BAFFC9',
        'medium': '#BAE1FF',
        'ecru': '#FFFFBA',
        'pink': '#FFD1DC',
        'brown': '#D2B48C',
        'beige': '#F5F5DC',
        'dark': '#A9A9A9',
        'unknown': '#E0E0E0'
    }

    sorted_schedule = sorted(schedule, key=lambda m: m["machine_id"])

    y_ticks = []
    y_labels = []
    for i, machine in enumerate(sorted_schedule):
        y_pos = i * 3
        y_ticks.append(y_pos)
        y_labels.append(f"Machine {machine['machine_id']}\n({machine['capacity']}kg)")

    ax.set_yticks(y_ticks)
    ax.set_yticklabels(y_labels, fontsize=11, fontweight='bold')

    makespan = max([
        max([batch.get("completion_time", 0) for batch in machine["batches"]], default=0)
        for machine in sorted_schedule
    ], default=50)

    for i, machine in enumerate(sorted_schedule):
        y_pos = i * 3
        bar_height = 1.5

        for batch in machine["batches"]:
            setup_time_val = batch.get("setup_time", 0)
            start_time_val = batch.get("start_time", 0)
            proc_time = batch.get("proc_time", 0)

            if setup_time_val > 0:
                setup_rect = Rectangle(
                    (start_time_val, y_pos - bar_height/2),
                    setup_time_val,
                    bar_height,
                    facecolor='#FF6B6B',
                    edgecolor='black',
                    linewidth=1.5,
                    alpha=0.9
                )
                ax.add_patch(setup_rect)

                if setup_time_val >= 0.5:
                    ax.text(
                        start_time_val + setup_time_val/2,
                        y_pos,
                        f"{setup_time_val:.1f}",
                        ha='center', va='center',
                        fontsize=7, fontweight='bold', color='white'
                    )

            proc_start = start_time_val + setup_time_val
            color = colors.get(batch.get("family"), '#E0E0E0')

            if proc_time > 0:
                proc_rect = Rectangle(
                    (proc_start, y_pos - bar_height/2),
                    proc_time,
                    bar_height,
                    facecolor=color,
                    edgecolor='black',
                    linewidth=2,
                    alpha=0.85
                )
                ax.add_patch(proc_rect)

                batch_id = batch.get("batch_id", batch.get("id", "?"))
                family_short = batch.get('family', '?')[:3].upper()

                label = f"B{batch_id}"
                sublabel = f"{family_short}"

                ax.text(
                    proc_start + proc_time/2,
                    y_pos + 0.2,
                    label,
                    ha='center', va='center',
                    fontsize=10, fontweight='bold'
                )
                ax.text(
                    proc_start + proc_time/2,
                    y_pos - 0.4,
                    sublabel,
                    ha='center', va='center',
                    fontsize=8, style='italic'
                )

    ax.set_xlim(-1, makespan * 1.08)
    ax.set_ylim(-2, len(sorted_schedule) * 3)
    ax.set_xlabel('Time (hours)', fontsize=12, fontweight='bold')
    ax.set_title(title, fontsize=14, fontweight='bold', pad=15)
    ax.grid(True, axis='x', linestyle='--', alpha=0.5)

    legend_elements = [
        Patch(facecolor='#FF6B6B', edgecolor='black', label='Setup'),
        Patch(facecolor='#FFB3BA', edgecolor='black', label='Pastel'),
        Patch(facecolor='#BAFFC9', edgecolor='black', label='Light'),
        Patch(facecolor='#BAE1FF', edgecolor='black', label='Medium'),
    ]
    ax.legend(handles=legend_elements, loc='upper right', fontsize=10)

    plt.tight_layout()
    plt.savefig('gantt_schedule.png', dpi=150, bbox_inches='tight')
    plt.show()
    print("✓ Saved to 'gantt_schedule.png'")


def visualize_pareto_front(pareto_front, approach_name):
    """Visualize Pareto front from epsilon-constraint"""
    if len(pareto_front) < 2:
        print("Not enough points for visualization")
        return

    tardiness = [sol['tardiness'] for sol in pareto_front]
    setup = [sol['setup_time'] for sol in pareto_front]

    fig, axes = plt.subplots(1, 2, figsize=(15, 6))

    ax1 = axes[0]
    ax1.plot(tardiness, setup, 'b-o', markersize=10, linewidth=2, label='Pareto front')
    ax1.scatter(tardiness, setup, c='red', s=150, zorder=5, marker='*', edgecolors='black', linewidth=2)

    for i, sol in enumerate(pareto_front):
        ax1.annotate(f"P{sol['point_id']}",
                    (sol['tardiness'], sol['setup_time']),
                    xytext=(8, 8), textcoords='offset points',
                    fontsize=10, fontweight='bold',
                    bbox=dict(boxstyle='round,pad=0.3', facecolor='yellow', alpha=0.7))

    ax1.set_xlabel('Total Tardiness', fontsize=14, fontweight='bold')
    ax1.set_ylabel('Total Setup Time', fontsize=14, fontweight='bold')
    ax1.set_title(f'Pareto Front - {approach_name}\n(Augmented Epsilon-Constraint)',
                  fontsize=14, fontweight='bold')
    ax1.grid(True, alpha=0.3)
    ax1.legend(fontsize=12)

    ax2 = axes[1]
    point_ids = [sol['point_id'] for sol in pareto_front]
    solve_times = [sol['solve_time'] for sol in pareto_front]
    phases = [sol['phase'] for sol in pareto_front]

    colors_phase = {'boundary': '#FF6B6B', 'intermediate': '#4ECDC4'}
    bar_colors = [colors_phase.get(p, '#999999') for p in phases]

    bars = ax2.bar(point_ids, solve_times, color=bar_colors, edgecolor='black', linewidth=1.5)

    ax2.set_xlabel('Pareto Point ID', fontsize=14, fontweight='bold')
    ax2.set_ylabel('Solve Time (seconds)', fontsize=14, fontweight='bold')
    ax2.set_title('Computational Time per Point', fontsize=14, fontweight='bold')
    ax2.grid(True, alpha=0.3, axis='y')

    legend_elements = [
        Patch(facecolor='#FF6B6B', edgecolor='black', label='Boundary'),
        Patch(facecolor='#4ECDC4', edgecolor='black', label='Intermediate')
    ]
    ax2.legend(handles=legend_elements, fontsize=11)

    avg_time = np.mean(solve_times)
    ax2.axhline(y=avg_time, color='red', linestyle='--', linewidth=2,
                label=f'Avg: {avg_time:.1f}s')

    plt.tight_layout()
    plt.savefig(f'pareto_epsilon_{approach_name}.png', dpi=300, bbox_inches='tight')
    plt.show()

    print(f"\n✓ Saved to 'pareto_epsilon_{approach_name}.png'")

