# =============================================================================
# SECTION 1  --  ASYMMETRIC SETUP MATRIX                              (1.1)
# =============================================================================
# sigma(f1,f2) = 0                                              if f1 == f2
#              = rho(f1) * (p_f1/10) * (1 + lam*max(0,d1-d2)/D)  otherwise
#
# The depth term makes purging to a LIGHTER shade expensive.  The staining
# term rho breaks the monotone coupling between cleaning cost and depth --
# without it, ordering light->dark is provably optimal and the single-machine
# sequencing subproblem collapses to a sort, which would leave the sequencing
# variables and the metaheuristics with nothing to do.
#
# lam = 0, RHO_H = 1 reproduces the previous matrix exactly.
# =============================================================================

PROCESSING_TIMES = {
    'ecru': 4, 'pink': 5, 'light': 6, 'medium': 8,
    'pastel': 10, 'brown': 12, 'beige': 13, 'dark': 14,
}
COLOR_ORDER = ['ecru', 'pink', 'light', 'medium', 'pastel', 'brown', 'beige', 'dark']
COLOR_DEPTH = {c: i for i, c in enumerate(
    sorted(COLOR_ORDER, key=lambda c: (PROCESSING_TIMES[c], c)))}
DEPTH_SPAN = len(COLOR_ORDER) - 1
CHROMATIC_COLORS = {'pink', 'brown'}

LAMBDA_ASYM = 1.0     # asymmetry intensity   -- sensitivity: {0, 0.5, 1.0, 2.0}
RHO_H = 1.8           # staining multiplier   -- sensitivity: {1.0, 1.4, 1.8}

# keep the generator's aliases pointing at the same palette
PROCESSING_TIMES_GEN = PROCESSING_TIMES
COLOR_ORDER_GEN = COLOR_ORDER


def base_setup_time(color, processing_times=None):
    return (processing_times or PROCESSING_TIMES).get(color, 8) / 10.0


def staining_factor(color, rho_h=None):
    return (RHO_H if rho_h is None else rho_h) if color in CHROMATIC_COLORS else 1.0


def setup_time(from_color, to_color, lam=None, rho_h=None, ndigits=3):
    if from_color == to_color:
        return 0.0
    lam = LAMBDA_ASYM if lam is None else lam
    drop = max(0, COLOR_DEPTH.get(from_color, 0) - COLOR_DEPTH.get(to_color, 0))
    return round(staining_factor(from_color, rho_h) * base_setup_time(from_color)
                 * (1.0 + lam * drop / DEPTH_SPAN), ndigits)


def generate_setup_matrix(colors=None, lam=None, rho_h=None):
    colors = colors or COLOR_ORDER
    return {(a, b): setup_time(a, b, lam, rho_h) for a in colors for b in colors}


generate_setup_matrix_gen = generate_setup_matrix
SETUP_MATRIX = generate_setup_matrix()
SETUP_TIMES_BY_COLOR = {c: base_setup_time(c) for c in COLOR_ORDER}
SETUP_TIMES_BY_COLOR_GEN = SETUP_TIMES_BY_COLOR
MAX_SIGMA = max(v for v in SETUP_MATRIX.values())


def get_setup_time_for_color(color, *_args, **_kw):
    """Legacy shim.  The old signature took only the departing colour, which
    is no longer sufficient -- callers must supply both colours.  Kept so that
    stale call sites fail loudly instead of silently returning a wrong number."""
    raise TypeError(
        "get_setup_time_for_color() is obsolete under the asymmetric matrix. "
        "Use get_setup_time(from_color, to_color).")


def get_setup_time(from_color, to_color, matrix=None):
    if from_color == to_color or from_color is None:
        return 0.0
    return (matrix or SETUP_MATRIX).get((from_color, to_color), 0.0)


def calculate_setup_time(from_batch, to_batch, matrix=None):
    if from_batch is None:
        return 0.0
    fam = lambda b: b.get('family', b.get('color', ''))
    return get_setup_time(fam(from_batch), fam(to_batch), matrix)


def calculate_setup_time_between(prev_batch, batch, matrix=None):
    return calculate_setup_time(prev_batch, batch, matrix)


def average_off_diagonal_setup(colors, matrix=None):
    m = matrix or SETUP_MATRIX
    v = [m[(a, b)] for a in colors for b in colors if a != b and (a, b) in m]
    return float(np.mean(v)) if v else 0.0


print(f"[1.1] asymmetric matrix   lambda={LAMBDA_ASYM}  rho_h={RHO_H}  "
      f"max sigma={MAX_SIGMA:.3f}")


# =============================================================================
# SECTION 2  --  INSTANCE GENERATOR: HORIZON AND DUE DATES            (1.5)
# =============================================================================
# The horizon P summed per-JOB processing times.  In a p-batch problem a batch
# takes max_{j in b} p_j = p_colour, so P was inflated by the average batch
# cardinality (measured: 1.5-2.0x).  Every tau was that much looser than
# intended, which is why the earlier runs reported 100% zero tardiness.
# =============================================================================

def ffd_bin_count(sizes, capacity):
    bins = []
    for s in sorted(sizes, reverse=True):
        for i, load in enumerate(bins):
            if load + s <= capacity:
                bins[i] = load + s
                break
        else:
            bins.append(s)
    return len(bins)


def expected_horizon(color_assignments, customer_assignments, sizes,
                     machine_capacity, num_machines, matrix=None):
    groups = defaultdict(list)
    for col, cust, sz in zip(color_assignments, customer_assignments, sizes):
        groups[(col, cust)].append(sz)

    n_batches, total_batch_proc, families = 0, 0.0, set()
    for (color, _cust), grp in groups.items():
        nb = ffd_bin_count(grp, machine_capacity)
        n_batches += nb
        total_batch_proc += nb * PROCESSING_TIMES[color]
        families.add(color)

    n_switches = max(0, len(families) - num_machines)
    avg_setup = average_off_diagonal_setup(sorted(families), matrix)
    P = (total_batch_proc + avg_setup * n_switches) / num_machines

    return P, {
        'n_jobs': len(sizes), 'n_batches': n_batches,
        'avg_batch_cardinality': len(sizes) / n_batches if n_batches else 0.0,
        'n_families': len(families), 'n_groups': len(groups),
        'estimated_switches': n_switches, 'horizon_P': P,
        'saturated': len(families) <= num_machines,
    }


def check_instance_design(num_colors, num_machines, num_customers, num_jobs,
                          verbose=True):
    issues = []
    if num_colors <= num_machines:
        issues.append(f"F={num_colors} <= m={num_machines}: a zero-setup "
                      f"schedule always exists, so the setup objective "
                      f"degenerates. Use F > m.")
    n_groups = max(1, num_colors * num_customers)
    if num_jobs / n_groups < 2.0:
        issues.append(f"{num_jobs} jobs over {n_groups} (colour, customer) "
                      f"groups = {num_jobs / n_groups:.1f} per group: batches "
                      f"hold ~1 job and the batching decision is trivial.")
    if verbose:
        for msg in issues:
            print(f"  [design warning] {msg}")
        if not issues:
            print(f"  [design check] OK  (F={num_colors} > m={num_machines}, "
                  f"{num_jobs / n_groups:.1f} jobs per group)")
    return issues


