def _patched_generate_jobs(self):
    """Replaces RandomInstanceGenerator._generate_jobs.

    Same sequence as before, except the horizon is now batch-aware and the
    batch diagnostics are retained so the experimental design section can
    report tau, R, P and the batch structure -- none of which appeared in the
    submitted manuscript, which is why reproducibility could not be checked.
    """
    customer_assignments = self._generate_assignments(
        self.config.num_customers, self.config.customer_balance)
    color_assignments = self._generate_color_assignments()
    sizes = self._generate_job_sizes()

