# =============================================================================
# SECTION 3  --  MILP1 SEQUENCING AND LINEARIZATION            (1.2 and 1.3)
# =============================================================================
# MANUAL EDIT REQUIRED inside build_integrated_milp() in cell 3.
#
# THE DEFECT.  Two constraint families contradict each other:
#   * flow conservation + first/last  builds a PATH on each machine
#   * exactly_one_ordering_rule       forces an arc on EVERY same-machine pair
# A path has no arc between non-adjacent batches, a tournament has one for
# every pair.  Verified with HiGHS on fixed assignments:
#
#     batches/machine     old constraints        new constraints
#          2              optimal  TS=0.400      optimal  TS=0.400
#          3              INFEASIBLE             optimal  TS=1.086
#          4              INFEASIBLE             optimal  TS=1.900
#          5              INFEASIBLE             optimal  TS=2.700
#          6              INFEASIBLE             optimal  TS=3.700
#
# The only structures satisfying both families contain cycles, and cycles are
# killed by the big-M timing constraint.  So MILP1 has only ever been solvable
# when every machine received at most two batches.
#
# Brute-force count confirms the replacement is exact, not merely feasible:
# it admits exactly k! acyclic solutions on a machine holding k batches
# (2, 6, 24, 120 for k = 2..5) -- all orderings, and nothing more.
# =============================================================================

MILP1_SEQUENCING_PATCH = r'''
# ---------------------------------------------------------------- DELETE ----
#   model.flow_conservation          (flow_conservation_rule)
#   model.must_have_incoming_or_first
#   model.must_have_outgoing_or_last
#   model.exactly_one_ordering       (exactly_one_ordering_rule)  <-- the bug
#   model.setup_linearization_1/2/3  and  model.u                 (see 1.3)
#   model.setup_time_calc            (setup_time_calc_rule)
# ------------------------------------------------------------------ ADD ----

# (S1) exactly one predecessor, or the batch starts the machine
def in_degree_rule(model, b, m):
    return (sum(model.seq[i, b, m] for i in model.B if i != b)
            + model.first[b, m] == model.a[b, m])
model.in_degree = pyo.Constraint(model.B, model.M, rule=in_degree_rule)

# (S2) exactly one successor, or the batch ends the machine
def out_degree_rule(model, b, m):
    return (sum(model.seq[b, j, m] for j in model.B if j != b)
            + model.last[b, m] == model.a[b, m])
model.out_degree = pyo.Constraint(model.B, model.M, rule=out_degree_rule)

# (S3)(S4) at most one path per machine   [one_first / one_last stay as they are]

# (S5) MTZ subtour elimination.  The timing constraints already forbid cycles
#      in any integer solution; MTZ also tightens the LP relaxation, which
#      MILP1 badly needs.
model.rank = pyo.Var(model.B, domain=pyo.NonNegativeReals,
                     bounds=(0, len(model.B) - 1))
def mtz_rule(model, i, j, m):
    if i == j:
        return pyo.Constraint.Skip
    return model.rank[j] >= model.rank[i] + 1 - len(model.B) * (1 - model.seq[i, j, m])
model.mtz = pyo.Constraint(model.B, model.B, model.M, rule=mtz_rule)

# (S6) setup between two batches, WITHOUT the u[i,j,f1,f2] product variables.
#      Given z[i,f1] = 1 the expression is already linear in z[j,.], so one
#      big-M constraint per (i, j, f1) suffices.  Both the objective and the
#      epsilon bound push setup_ij down, so >= is tight at optimality.
#      Use M_SIGMA (the largest transition), NOT the horizon-scale M_big --
#      a horizon-scale big-M here destroys the LP relaxation.
M_SIGMA = max(setup_matrix.values())
def setup_link_rule(model, i, j, f1):
    if i == j:
        return pyo.Constraint.Skip
    return (model.setup_ij[i, j]
            >= sum(setup_matrix[(f1, f2)] * model.z[j, f2] for f2 in model.F)
            - M_SIGMA * (1 - model.z[i, f1]))
model.setup_link = pyo.Constraint(model.B, model.B, model.F, rule=setup_link_rule)

# (S7) tighten active_setup with M_SIGMA as well (currently uses M_big)
#      model.active_setup_1: active_setup[i,j,m] <= M_SIGMA * seq[i,j,m]
#      model.active_setup_3: active_setup[i,j,m] >= setup_ij[i,j]
#                                                  - M_SIGMA * (1 - seq[i,j,m])
'''

# Size comparison for the manuscript (Reviewer 2 asks why the decomposition):
def linearization_size(n_batches, n_families):
    old_v = n_batches ** 2 * n_families ** 2
    return {'old_aux_binaries': old_v, 'old_constraints': 3 * old_v,
            'new_aux_binaries': 0,
            'new_constraints': n_batches ** 2 * n_families}


print("[1.2] MILP1 sequencing patch prepared  -> print(MILP1_SEQUENCING_PATCH)")
_s = linearization_size(15, 6)
print(f"[1.3] linearization  {_s['old_aux_binaries']} binaries + "
      f"{_s['old_constraints']} constraints  ->  0 binaries + "
      f"{_s['new_constraints']} constraints   (15 batches, 6 families)")


# =============================================================================
# SECTION 4  --  MILP2 SETUP ACCOUNTING                               (1.4)
# =============================================================================
# MANUAL EDIT REQUIRED inside solve_stage2_milp_epsilon() in cell 3.
#
# model.y[i,j] is a GENERAL PRECEDENCE variable, and precedence_required_rule
# forces an arc on every same-machine pair.  Total setup then sums k(k-1)/2
# terms where a schedule has k-1 transitions.  Measured with HiGHS:
#
#     batches  machines   current   corrected   factor
#           3         1     1.486       1.086    1.37x
#           4         1     3.386       1.900    1.78x
#           5         1     6.086       2.700    2.25x
#           6         1     9.786       3.700    2.64x
#           8         2     8.700       5.000    1.74x
#
# The heuristics count correctly (they walk the machine sequence), so MILP2
# and the heuristics have been optimising DIFFERENT objectives.  Every
# reported optimality gap against FFD+SA-MILP2 compares two different
# quantities, and the epsilon bound was applied to an inflated value, which
# displaces the Pareto points themselves.
# =============================================================================

MILP2_SEQUENCING_PATCH = r'''
# ---------------------------------------------------------------- DELETE ----
#   model.y  and  precedence_required / precedence_antisymmetry /
#   y_same_machine / sequencing_time / total_setup_calc
# ------------------------------------------------------------------ ADD ----

model.succ  = pyo.Var(model.B, model.B, model.M, domain=pyo.Binary)
model.first = pyo.Var(model.B, model.M, domain=pyo.Binary)
model.last  = pyo.Var(model.B, model.M, domain=pyo.Binary)

def in_degree_rule(model, b, m):
    return (sum(model.succ[i, b, m] for i in model.B if i != b)
            + model.first[b, m] == model.x[b, m])
model.in_degree = pyo.Constraint(model.B, model.M, rule=in_degree_rule)

def out_degree_rule(model, b, m):
    return (sum(model.succ[b, j, m] for j in model.B if j != b)
            + model.last[b, m] == model.x[b, m])
model.out_degree = pyo.Constraint(model.B, model.M, rule=out_degree_rule)

model.one_first = pyo.Constraint(model.M,
    rule=lambda mm, m: sum(mm.first[b, m] for b in mm.B) <= 1)
model.one_last = pyo.Constraint(model.M,
    rule=lambda mm, m: sum(mm.last[b, m] for b in mm.B) <= 1)

model.rank = pyo.Var(model.B, domain=pyo.NonNegativeReals,
                     bounds=(0, len(model.B) - 1))
def mtz_rule(model, i, j, m):
    if i == j:
        return pyo.Constraint.Skip
    return model.rank[j] >= model.rank[i] + 1 - len(model.B) * (1 - model.succ[i, j, m])
model.mtz = pyo.Constraint(model.B, model.B, model.M, rule=mtz_rule)

def succession_time_rule(model, i, j, m):
    if i == j:
        return pyo.Constraint.Skip
    return (model.start[j] >= model.C[i] + model.setup[i, j]
            - big_M_value * (1 - model.succ[i, j, m]))
model.succession_time = pyo.Constraint(model.B, model.B, model.M,
                                       rule=succession_time_rule)

# THE ACTUAL FIX: setup accumulates over SUCCESSIONS ONLY
def total_setup_rule(model):
    return model.total_setup == sum(
        model.setup[i, j] * model.succ[i, j, m]
        for i in model.B for j in model.B for m in model.M if i != j)
model.total_setup_calc = pyo.Constraint(rule=total_setup_rule)

# Tighter big-M: a machine can hold at most all batches, so the horizon is
# bounded by total processing plus (n-1) worst-case transitions.
# big_M_value = sum(b["proc_time"] for b in batches_for_stage2) \
#               + max(setup_times.values()) * max(0, len(batches_for_stage2) - 1)
'''

print("[1.4] MILP2 sequencing patch prepared  -> print(MILP2_SEQUENCING_PATCH)")


# =============================================================================
# SECTION 5  --  AUGMECON2 AUGMENTATION SIGN                         (1.2b)
# =============================================================================
# Both MILP builders use
#       expr = sum(T_job) + augmentation_coefficient * slack
#       total_setup + slack == epsilon
# Since slack = epsilon - total_setup, ADDING it rewards a SMALL slack, i.e.
# it pushes the secondary objective UP against its bound and returns weakly
# dominated points -- the opposite of what AUGMECON2 exists to prevent.
#
# Worked example.  epsilon = 5, candidates (tardiness; setup):
#       (10; 2)   (10; 5)   (12; 1)
# current code scores 10 + 1e-6*3, 10 + 1e-6*0, 12 + 1e-6*4 and returns
# (10; 5), which is dominated by (10; 2).  With the sign corrected the scores
# become 10 - 1e-6*3, 10 - 1e-6*0, 12 - 1e-6*4 and (10; 2) wins.
# =============================================================================

AUGMECON2_OBJECTIVE_PATCH = r'''
def build_augmecon2_objective(model, primary_objective,
                              augmentation_coefficient=1e-6,
                              range_secondary=1.0):
    """AUGMECON2 for a min-min problem:
           min  f1 - delta * (s / r)     s.t.  f2 + s = epsilon,  s >= 0
    r is the payoff-table range of the secondary objective, so delta is scale
    free and the same value works across instances."""
    total_tardiness = sum(model.T_job[j] for j in model.J)
    primary = total_tardiness if primary_objective == "tardiness" else model.total_setup
    if augmentation_coefficient > 0:
        expr = primary - augmentation_coefficient * (model.slack / max(range_secondary, 1e-9))
    else:
        expr = primary
    model.objective = pyo.Objective(expr=expr, sense=pyo.minimize)
    return model

# In generate_pareto_front_epsilon(): pass augmentation_coefficient=1e-6
# (not 0) and range_secondary = payoff_max_setup - payoff_min_setup.
# Also raise the grid from 6 to 15-20 points: with 6 points each method
# contributes only 3-4 non-dominated solutions, which is too sparse for
# hypervolume to be meaningful.
'''

print("[1.2b] AUGMECON2 sign patch prepared -> print(AUGMECON2_OBJECTIVE_PATCH)")


# =============================================================================
# SECTION 6  --  ALNS CORRECTIONS                                     (1.7)
# =============================================================================
# (a) the adaptive removal rate is overwritten one line later, so the
#     aggressive small-instance setting never fires;
# (b) regret-2 assigns regret 0 to a job with exactly ONE feasible batch,
#     although such a job has the most to lose -- the ranking is
#     0 options -> inf, 1 option -> 0, 2 options -> positive, i.e. not
#     monotone.  Cause: `second = costs[1] if len(costs) > 1 else costs[0]`.
#     The fix is to put the cost of opening a NEW batch into the option list;
# (c) insertion costs use batch['due_date'], which is not a cost and is blind
#     to the setup objective -- half of a bi-objective problem.
#
# This matters for fairness: in the last run every ALNS point was dominated
# ( C(NSGA-II, ALNS) = 1.00, C(ALNS, *) = 0.00 ).  A benchmark that loses that
# completely invites the reading that it was built to lose.
# =============================================================================

def alns_removal_count(num_batches):
    if num_batches <= 10:
        rate = random.uniform(0.40, 0.60)
    elif num_batches <= 20:
        rate = random.uniform(0.30, 0.50)
    else:
        rate = random.uniform(0.20, 0.40)
    return max(2, min(num_batches, int(num_batches * rate)))


def insertion_cost(job, batch, capacity, epsilon_setup=None, penalty=1e4):
    """Objective-based insertion cost: delta(tardiness) + delta(setup) + a
    small packing preference.  inf when infeasible."""
    if batch['size'] + job['size'] > capacity:
        return float('inf')
    if batch.get('family', batch.get('color')) != job['color']:
        return float('inf')
    if batch.get('customer') != job.get('customer'):
        return float('inf')

    new_due = min(batch['due_date'], job['due_date'])
    n_exposed = len(batch.get('jobs', [])) + 1
    delta_tardiness = max(0.0, batch['due_date'] - new_due) * n_exposed
    delta_setup = 0.0                      # joining an existing batch adds none
    packing = 0.01 * (capacity - batch['size'] - job['size']) / max(capacity, 1)

    cost = delta_tardiness + delta_setup + packing
    if epsilon_setup is not None and delta_setup > epsilon_setup:
        cost += penalty * (delta_setup - epsilon_setup)
    return cost


def new_batch_cost(job, avg_setup, epsilon_setup=None, penalty=1e4):
    """Opening a batch adds one transition somewhere, so it is NOT free.
    Including this in the option list is what makes regret-k well defined."""
    cost = avg_setup
    if epsilon_setup is not None and avg_setup > epsilon_setup:
        cost += penalty * (avg_setup - epsilon_setup)
    return cost


def regret_k_scores(job, batches, capacity, avg_setup, k=2, epsilon_setup=None):
    """Returns (regret, best_cost, best_batch_or_None).

    The new-batch option is part of the list, so a job with a single feasible
    batch now receives a large regret rather than zero.
    """
    options = [(insertion_cost(job, b, capacity, epsilon_setup), b)
               for b in batches]
    options = [(c, b) for c, b in options if c < float('inf')]
    open_cost = new_batch_cost(job, avg_setup, epsilon_setup)

    if not options:
        return float('inf'), open_cost, None

    options.sort(key=lambda t: t[0])
    costs = sorted([c for c, _ in options] + [open_cost])
    regret = sum(costs[i] - costs[0] for i in range(1, min(k, len(costs))))
    best_cost, best_batch = options[0]
    return regret, best_cost, (best_batch if best_cost <= open_cost else None)


print("[1.7] ALNS helpers defined: alns_removal_count, insertion_cost, "
      "regret_k_scores")


# =============================================================================
# SECTION 7  --  MULTI-OBJECTIVE PERFORMANCE INDICATORS               (1.6)
# =============================================================================
# Two rules the implementation enforces:
#   * ONE reference point per instance, from the union of every front of every
#     method and replication.  A per-method reference point makes hypervolumes
#     incomparable across the very methods being compared.
#   * The reference front is the non-dominated subset of that union, unless an
#     exact front is supplied via true_front.
#
# All objectives minimised; each point is (total_tardiness, total_setup).
# =============================================================================

def dominates(p, q):
    p, q = np.asarray(p, float), np.asarray(q, float)
    return bool(np.all(p <= q) and np.any(p < q))


def non_dominated(points, tol=1e-9):
    pts = np.atleast_2d(np.asarray(points, float))
    if pts.size == 0:
        return np.empty((0, 2))
    pts = np.unique(np.round(pts, 9), axis=0)
    keep = np.ones(len(pts), bool)
    for i in range(len(pts)):
        if not keep[i]:
            continue
        for j in range(len(pts)):
            if i != j and keep[j] and np.all(pts[j] <= pts[i] + tol) \
                    and np.any(pts[j] < pts[i] - tol):
                keep[i] = False
                break
    return pts[keep]


def bounds_from_fronts(list_of_fronts):
    stacked = np.vstack([np.atleast_2d(np.asarray(f, float))
                         for f in list_of_fronts if len(f)])
    return stacked.min(axis=0), stacked.max(axis=0)


def normalize_front(front, ideal, nadir):
    front = np.atleast_2d(np.asarray(front, float))
    if front.size == 0:
        return np.empty((0, len(ideal)))
    span = np.where(np.asarray(nadir) - np.asarray(ideal) > 1e-12,
                    np.asarray(nadir) - np.asarray(ideal), 1.0)
    return (front - np.asarray(ideal)) / span


def hypervolume_2d(front, ref_point=(1.1, 1.1)):
    pts = non_dominated(front)
    if len(pts) == 0:
        return 0.0
    ref = np.asarray(ref_point, float)
    pts = pts[np.all(pts < ref, axis=1)]
    if len(pts) == 0:
        return 0.0
    pts = pts[np.argsort(pts[:, 0])]
    hv = 0.0
    for i, (x, y) in enumerate(pts):
        x_next = pts[i + 1, 0] if i + 1 < len(pts) else ref[0]
        hv += (x_next - x) * (ref[1] - y)
    return float(hv)


def igd_plus(front, reference_front):
    """Pareto-compliant IGD variant (Ishibuchi et al., 2015). Plain IGD is not
    compliant and can rank a dominated front above a dominating one."""
    A = np.atleast_2d(np.asarray(front, float))
    R = np.atleast_2d(np.asarray(reference_front, float))
    if A.size == 0 or R.size == 0:
        return float('inf')
    diff = np.maximum(A[None, :, :] - R[:, None, :], 0.0)
    return float(np.sqrt((diff ** 2).sum(axis=2)).min(axis=1).mean())


def igd(front, reference_front):
    A = np.atleast_2d(np.asarray(front, float))
    R = np.atleast_2d(np.asarray(reference_front, float))
    if A.size == 0 or R.size == 0:
        return float('inf')
    d = np.sqrt(((R[:, None, :] - A[None, :, :]) ** 2).sum(axis=2))
    return float(d.min(axis=1).mean())


def epsilon_additive(front, reference_front):
    A = np.atleast_2d(np.asarray(front, float))
    R = np.atleast_2d(np.asarray(reference_front, float))
    if A.size == 0 or R.size == 0:
        return float('inf')
    return float((A[None, :, :] - R[:, None, :]).max(axis=2).min(axis=1).max())


def set_coverage(front_a, front_b):
    """C(A,B): fraction of B weakly dominated by some member of A.
    Asymmetric -- report both directions, they do not sum to 1."""
    A = np.atleast_2d(np.asarray(front_a, float))
    B = np.atleast_2d(np.asarray(front_b, float))
    if B.size == 0:
        return float('nan')
    if A.size == 0:
        return 0.0
    return sum(1 for b in B if any(dominates(a, b) or np.allclose(a, b)
                                   for a in A)) / len(B)


def spacing(front):
    pts = non_dominated(front)
    if len(pts) < 2:
        return float('nan')
    d = np.array([min(np.abs(pts[i] - pts[j]).sum()
                      for j in range(len(pts)) if j != i)
                  for i in range(len(pts))])
    return float(np.sqrt(((d.mean() - d) ** 2).sum() / (len(d) - 1)))


def spread_extent(front):
    pts = np.atleast_2d(np.asarray(front, float))
    if len(pts) < 2:
        return 0.0
    return float(np.sqrt(((pts.max(axis=0) - pts.min(axis=0)) ** 2).sum()))


def evaluate_fronts(fronts_by_method, true_front=None, ref_point=(1.1, 1.1)):
    fronts = {m: non_dominated(f) for m, f in fronts_by_method.items() if len(f)}
    if not fronts:
        return {}, {}
    all_fronts = list(fronts.values())
    if true_front is not None and len(true_front):
        all_fronts.append(np.atleast_2d(np.asarray(true_front, float)))

    ideal, nadir = bounds_from_fronts(all_fronts)
    norm = {m: normalize_front(f, ideal, nadir) for m, f in fronts.items()}

    if true_front is not None and len(true_front):
        ref_front = normalize_front(non_dominated(true_front), ideal, nadir)
        ref_source = 'exact'
    else:
        ref_front = non_dominated(np.vstack(list(norm.values())))
        ref_source = 'union'

    results = {}
    for m, f in norm.items():
        results[m] = {
            'HV': hypervolume_2d(f, ref_point),
            'IGD+': igd_plus(f, ref_front),
            'IGD': igd(f, ref_front),
            'EPS': epsilon_additive(f, ref_front),
            'SP': spacing(f),
            'SPREAD': spread_extent(f),
            'ND': int(len(f)),
            'ND_in_ref': int(sum(1 for p in f
                                 if any(np.allclose(p, r) for r in ref_front))),
        }
    names = list(norm)
    meta = {'ideal': ideal, 'nadir': nadir, 'ref_point': ref_point,
            'ref_front_source': ref_source, 'ref_front_size': int(len(ref_front)),
            'coverage': {a: {b: set_coverage(norm[a], norm[b])
                             for b in names if b != a} for a in names}}
    return results, meta


def aggregate_replications(per_run_results):
    methods = sorted({m for r in per_run_results for m in r})
    keys = ['HV', 'IGD+', 'IGD', 'EPS', 'SP', 'SPREAD', 'ND']
    out = {}
    for m in methods:
        out[m] = {}
        for k in keys:
            v = [r[m][k] for r in per_run_results
                 if m in r and np.isfinite(r[m][k])]
            out[m][f'{k}_mean'] = float(np.mean(v)) if v else float('nan')
            out[m][f'{k}_std'] = float(np.std(v, ddof=1)) if len(v) > 1 else 0.0
    return out


def wilcoxon_pairwise(scores_a, scores_b, alternative='two-sided'):
    if not _SCIPY:
        return {'error': 'scipy not available'}
    a, b = np.asarray(scores_a, float), np.asarray(scores_b, float)
    mask = np.isfinite(a) & np.isfinite(b)
    a, b = a[mask], b[mask]
    if len(a) < 3 or np.allclose(a, b):
        return {'n': int(len(a)), 'p_value': float('nan'),
                'note': 'insufficient or tied data'}
    stat, p = _sstats.wilcoxon(a, b, alternative=alternative)
    d = (a - b)[a != b]
    r = _sstats.rankdata(np.abs(d))
    rbc = (r[d > 0].sum() - r[d < 0].sum()) / r.sum() if len(d) else 0.0
    return {'n': int(len(a)), 'statistic': float(stat), 'p_value': float(p),
            'rank_biserial': float(rbc), 'median_diff': float(np.median(a - b))}


def friedman_test(score_matrix, method_names=None):
    if not _SCIPY:
        return {'error': 'scipy not available'}
    X = np.asarray(score_matrix, float)
    X = X[np.all(np.isfinite(X), axis=1)]
    n, k = X.shape
    if n < 3 or k < 3:
        return {'note': 'needs >= 3 instances and >= 3 methods'}
    stat, p = _sstats.friedmanchisquare(*[X[:, j] for j in range(k)])
    ranks = np.array([_sstats.rankdata(row) for row in X]).mean(axis=0)
    q = {3: 2.343, 4: 2.569, 5: 2.728, 6: 2.850, 7: 2.949,
         8: 3.031, 9: 3.102, 10: 3.164}.get(k, 3.164)
    return {'n_instances': int(n), 'n_methods': int(k),
            'statistic': float(stat), 'p_value': float(p),
            'avg_ranks': dict(zip(method_names or list(range(k)), ranks.round(3))),
            'critical_difference': float(q * np.sqrt(k * (k + 1) / (6.0 * n)))}


def print_indicator_table(results, meta=None, title="Multi-objective indicators"):
    cols = ['HV', 'IGD+', 'EPS', 'SP', 'ND', 'ND_in_ref']
    print(f"\n{title}")
    if meta:
        print(f"  reference front: {meta['ref_front_source']} "
              f"({meta['ref_front_size']} points), ref point {meta['ref_point']}")
    print("-" * 80)
    print(f"{'method':<26}" + "".join(f"{c:>9}" for c in cols))
    print("-" * 80)
    for m, r in sorted(results.items(), key=lambda kv: -kv[1]['HV']):
        row = f"{m:<26}"
        for c in cols:
            v = r[c]
            row += f"{v:>9d}" if isinstance(v, int) else f"{v:>9.4f}"
        print(row)
    print("-" * 80)
    print("HV higher is better; IGD+, EPS, SP lower is better.")


def print_coverage_matrix(meta):
    cov = meta['coverage']
    names = sorted(cov)
    w = max(len(n) for n in names) + 2
    print("\nSet coverage  C(row, column)")
    print("-" * (w + 10 * len(names)))
    print(" " * w + "".join(n[:9].rjust(10) for n in names))
    for a in names:
        row = a.ljust(w)
        for b in names:
            row += "        --" if a == b else f"{cov[a][b]:10.2f}"
        print(row)


print("[1.6] indicators: HV, IGD+, IGD, EPS, C-metric, SP, ND "
      "+ Wilcoxon / Friedman")


# =============================================================================
# SECTION 8  --  CONSISTENCY AUDIT
# =============================================================================
# The point of the MILP2 fix is that the exact model and the heuristics now
# measure the same thing.  Verify it; do not assume it.
# =============================================================================

def audit_setup_consistency(schedule, reported_total, matrix=None,
                            tol=1e-6, verbose=True):
    """Recompute total setup by walking each machine sequence and compare it
    with the value the solver reported."""
    m = matrix or SETUP_MATRIX
    walked = 0.0
    for machine in schedule:
        prev = None
        for batch in machine.get('batches', []):
            fam = batch.get('family', batch.get('color'))
            if prev is not None:
                walked += m.get((prev, fam), 0.0)
            prev = fam
    ok = abs(walked - reported_total) <= tol
    if verbose:
        print(f"[audit] walked={walked:.3f}  reported={reported_total:.3f}  "
              f"-> {'MATCH' if ok else 'MISMATCH'}")
        if not ok:
            print("        MILP and heuristics are still measuring different "
                  "objectives -- do not regenerate results yet.")
    return walked, ok


def self_test():
    """Sanity checks with hand-computed expected values."""
    print("\n" + "-" * 78)
    print("SELF-TEST")
    print("-" * 78)
    checks = []

    checks.append(("backward compatibility (lam=0, rho=1)",
                   all(abs(setup_time(a, b, 0.0, 1.0)
                           - (0.0 if a == b else round(PROCESSING_TIMES[a] / 10, 3))) < 1e-9
                       for a in COLOR_ORDER for b in COLOR_ORDER)))
    checks.append(("asymmetry present",
                   setup_time('dark', 'ecru') > setup_time('ecru', 'dark')))
    checks.append(("brown->ecru = 1.8*1.2*(1+5/7) = 3.703",
                   abs(setup_time('brown', 'ecru') - 3.703) < 1e-3))
    checks.append(("HV two extreme points = 0.21",
                   abs(hypervolume_2d([[0, 1], [1, 0]]) - 0.21) < 1e-9))
    checks.append(("HV single ideal point = 1.21",
                   abs(hypervolume_2d([[0, 0]]) - 1.21) < 1e-9))
    checks.append(("HV ignores a dominated point",
                   abs(hypervolume_2d([[0, 1], [1, 0], [0.5, 1.05]]) - 0.21) < 1e-9))
    checks.append(("IGD+ zero on identical fronts",
                   igd_plus([[0, 1], [1, 0]], [[0, 1], [1, 0]]) < 1e-9))
    checks.append(("C(A,B)=1 and C(B,A)=0 for a dominating point",
                   set_coverage([[0, 0]], [[1, 1]]) == 1.0
                   and set_coverage([[1, 1]], [[0, 0]]) == 0.0))
    checks.append(("spacing zero on a uniform front",
                   abs(spacing([[0, 3], [1, 2], [2, 1], [3, 0]])) < 1e-9))
    checks.append(("regret > 0 when a job has one feasible batch",
                   regret_k_scores({'id': 1, 'size': 100, 'color': 'dark',
                                    'customer': 'C1', 'due_date': 40.0},
                                   [{'size': 100, 'family': 'dark',
                                     'customer': 'C1', 'due_date': 30.0,
                                     'jobs': [1]}],
                                   500, avg_setup=1.5)[0] > 0))

    for name, passed in checks:
        print(f"  {'PASS' if passed else 'FAIL'}  {name}")
    n_ok = sum(1 for _, p in checks if p)
    print(f"\n  {n_ok}/{len(checks)} passed")
    return n_ok == len(checks)


