# ==========================================================================
# NOTEBOOK CELL 5
# ==========================================================================
# =============================================================================
# PHASE 2 -- EXPERIMENTAL CAMPAIGN
# =============================================================================
# Design
#   tightness   tau in {0.2, 0.4, 0.6}      -- LOOSE / MEDIUM / TIGHT
#   size        n in {30, 50, 80, 100}
#   instances   5 seeds per (tau, n) cell   -> 60 instances
#   replications R independent runs per instance per method
#   budget      equal wall-clock per epsilon point for every heuristic
#
# Reported per instance: HV, IGD+, epsilon-indicator, spacing, |ND| against a
# reference front built from the union of every front of every method and
# replication on that instance, with one ideal/nadir pair per instance.
#
# Reported across instances: mean and standard deviation, pairwise Wilcoxon
# signed-rank with rank-biserial effect size, and Friedman with the Nemenyi
# critical difference.
# =============================================================================

import itertools
import json
import os
import time

import numpy as np
import pandas as pd


# -----------------------------------------------------------------------------
# Design
# -----------------------------------------------------------------------------

CAMPAIGN = {
    "presets": ["LOOSE", "MEDIUM", "TIGHT"],       # tau = 0.2 / 0.4 / 0.6
    "sizes": [30, 50, 80, 100],
    "seeds": [11, 22, 33, 44, 55],                  # 5 instances per cell
    "replications": 10,
    "machines": {30: 3, 50: 4, 80: 5, 100: 6},
    "colors": 8,                                    # must exceed machines
    "customers": 3,
    "capacity": 600,
    "methods": ["FFD+SA-EDDTS", "ALNS", "NSGA-II", "LPT+EDD"],
    "grid_points": 12,
    "budget_seconds": {30: 10.0, 50: 20.0, 80: 30.0, 100: 40.0},
    "out_dir": "phase2_results",
}


def campaign_size(cfg=CAMPAIGN):
    """Print the size of the campaign before committing hours to it."""
    n_inst = len(cfg["presets"]) * len(cfg["sizes"]) * len(cfg["seeds"])
    total = 0.0
    for size in cfg["sizes"]:
        b = cfg["budget_seconds"][size]
        per_run = b * cfg["grid_points"]                 # per method per rep
        n_cells = len(cfg["presets"]) * len(cfg["seeds"])
        total += n_cells * cfg["replications"] * len(cfg["methods"]) * per_run

    print(f"Instances:      {n_inst}")
    print(f"Replications:   {cfg['replications']}")
    print(f"Methods:        {len(cfg['methods'])}")
    print(f"Runs:           {n_inst * cfg['replications'] * len(cfg['methods'])}")
    print(f"Estimated time: {total/3600:.1f} hours "
          f"({total/3600/24:.1f} days) on one core")
    print()
    print("If that is too long, cut in this order: replications 10 -> 5,")
    print("seeds 5 -> 3, sizes drop 100.  Do NOT cut below 5 replications:")
    print("a Wilcoxon test on fewer pairs has no power.")
    return total


# -----------------------------------------------------------------------------
# One instance, one replication
# -----------------------------------------------------------------------------

def run_one(preset, size, seed, rep, cfg=CAMPAIGN, verbose=False):
    """Generate one instance and run every method once on it.

    Returns {method: [(tardiness, setup), ...]}.
    """
    machines_n = cfg["machines"][size]

    issues = check_instance_design(cfg["colors"], machines_n,
                                   cfg["customers"], size, verbose=False)
    if issues and verbose:
        for msg in issues:
            print(f"  [design] {msg}")

    gen = RandomInstanceGenerator.from_preset(
        preset, num_jobs=size, num_machines=machines_n,
        num_colors=cfg["colors"], num_customers=cfg["customers"],
        machine_capacity=cfg["capacity"], seed=seed * 1000 + rep)
    jobs, machines, meta, setup_matrix = gen.generate()

    globals()["HEURISTIC_TIME_BUDGET"] = cfg["budget_seconds"][size]

    fronts = {}
    for method in cfg["methods"]:
        try:
            # generate_pareto_front_epsilon returns (pareto_front, dataframe)
            # where pareto_front is a list of solution dicts.
            out = generate_pareto_front_epsilon(
                jobs, machines, approach=method,
                num_points=cfg["grid_points"],
                setup_matrix=setup_matrix)

            front = out[0] if isinstance(out, tuple) else out
            if hasattr(front, "to_dict"):                 # a DataFrame
                front = front.to_dict("records")

            pts = []
            for s in front:
                t = s.get("tardiness", s.get("Tardiness"))
                u = s.get("setup_time", s.get("Setup_Time"))
                if t is not None and u is not None:
                    pts.append((float(t), float(u)))
            fronts[method] = pts

        except Exception as exc:
            import traceback
            print(f"    ! {method} failed on {preset}/{size}/{seed}/r{rep}: "
                  f"{type(exc).__name__}: {exc}")
            if verbose:
                traceback.print_exc(limit=3)
            fronts[method] = []

    return fronts, gen.horizon_diagnostics


# -----------------------------------------------------------------------------
# Campaign driver
# -----------------------------------------------------------------------------

def run_campaign(cfg=CAMPAIGN, resume=True, verbose=True):
    """Run the whole design, checkpointing after every instance.

    Checkpointing matters: the campaign takes hours and a Colab disconnect
    should not cost the whole run.
    """
    os.makedirs(cfg["out_dir"], exist_ok=True)
    rows = []
    ckpt = os.path.join(cfg["out_dir"], "raw_fronts.json")

    done = {}
    if resume and os.path.exists(ckpt):
        done = json.load(open(ckpt))
        print(f"Resuming: {len(done)} instance(s) already complete")

    cells = list(itertools.product(cfg["presets"], cfg["sizes"], cfg["seeds"]))
    t_start = time.time()

    for idx, (preset, size, seed) in enumerate(cells, 1):
        key = f"{preset}_{size}_{seed}"
        if key in done:
            continue

        if verbose:
            print(f"[{idx}/{len(cells)}] {key}", flush=True)

        per_rep = []
        for rep in range(cfg["replications"]):
            fronts, diag = run_one(preset, size, seed, rep, cfg)
            per_rep.append({m: [list(p) for p in f] for m, f in fronts.items()})

        done[key] = {"replications": per_rep, "diagnostics": diag}
        json.dump(done, open(ckpt, "w"))

        elapsed = time.time() - t_start
        remaining = elapsed / idx * (len(cells) - idx)
        if verbose:
            print(f"    done in {elapsed/60:.1f} min, "
                  f"~{remaining/60:.0f} min left", flush=True)

    print(f"\nCampaign finished in {(time.time()-t_start)/3600:.2f} h")
    return done


# -----------------------------------------------------------------------------
# Analysis
# -----------------------------------------------------------------------------

def analyse_campaign(done, cfg=CAMPAIGN):
    """Indicator table per instance, then aggregation and statistical tests."""
    rows = []

    for key, entry in done.items():
        preset, size, seed = key.split("_")
        reps = entry["replications"]

        # One ideal/nadir pair per INSTANCE, from every front of every method
        # and every replication.  A per-replication basis would make the
        # hypervolumes incomparable across the very methods being compared.
        all_fronts = [np.array(f) for rep in reps for f in rep.values() if f]
        if not all_fronts:
            continue
        ideal, nadir = bounds_from_fronts(all_fronts)

        ref_pool = np.vstack(all_fronts)
        ref_front = non_dominated(normalize_front(ref_pool, ideal, nadir))

        for r, rep in enumerate(reps):
            for method, front in rep.items():
                if not front:
                    continue
                f = normalize_front(non_dominated(front), ideal, nadir)
                rows.append({
                    "preset": preset, "size": int(size), "seed": int(seed),
                    "rep": r, "method": method,
                    "HV": hypervolume_2d(f),
                    "IGD+": igd_plus(f, ref_front),
                    "EPS": epsilon_additive(f, ref_front),
                    "SP": spacing(f),
                    "ND": len(f),
                    "min_tard": min(p[0] for p in front),
                    "min_setup": min(p[1] for p in front),
                })

    df = pd.DataFrame(rows)
    if df.empty:
        print("No results to analyse.")
        return df, None, None

    # --- aggregate: mean over replications, then over instances
    per_instance = (df.groupby(["preset", "size", "seed", "method"])
                      [["HV", "IGD+", "EPS", "SP", "ND"]].mean().reset_index())

    summary = (per_instance.groupby("method")[["HV", "IGD+", "EPS", "SP", "ND"]]
               .agg(["mean", "std"]).round(4))

    print("\n" + "=" * 78)
    print("AGGREGATE OVER ALL INSTANCES (mean of per-instance means)")
    print("=" * 78)
    print(summary)

    by_preset = (per_instance.groupby(["preset", "method"])[["HV", "IGD+"]]
                 .mean().round(4))
    print("\nBy due-date tightness:")
    print(by_preset)

    by_size = (per_instance.groupby(["size", "method"])[["HV", "IGD+"]]
               .mean().round(4))
    print("\nBy instance size:")
    print(by_size)

    # --- statistical tests on the per-instance HV values (paired by instance)
    print("\n" + "=" * 78)
    print("STATISTICAL TESTS on hypervolume (paired by instance)")
    print("=" * 78)

    pivot = per_instance.pivot_table(
        index=["preset", "size", "seed"], columns="method", values="HV")
    methods = [m for m in cfg["methods"] if m in pivot.columns]

    fr = friedman_test(pivot[methods].values, method_names=methods)
    print("\nFriedman:")
    for k, v in fr.items():
        print(f"  {k}: {v}")

    print("\nPairwise Wilcoxon signed-rank:")
    proposed = "FFD+SA-EDDTS"
    if proposed in methods:
        for other in methods:
            if other == proposed:
                continue
            res = wilcoxon_pairwise(pivot[proposed].values, pivot[other].values)
            p = res.get("p_value", float("nan"))
            verdict = ("no significant difference" if not np.isfinite(p) or p >= 0.05
                       else ("proposed better" if res.get("median_diff", 0) > 0
                             else "proposed worse"))
            print(f"  {proposed} vs {other:<14} n={res.get('n')}, "
                  f"p={p:.4f}, effect={res.get('rank_biserial', float('nan')):+.3f}"
                  f"  -> {verdict}")

    print("\nRead this honestly: with p >= 0.05 the correct statement is that")
    print("the methods are indistinguishable on this indicator, not that the")
    print("proposed method is better.")

    out = os.path.join(cfg["out_dir"], "indicators.csv")
    df.to_csv(out, index=False)
    print(f"\nPer-run indicators written to {out}")

    return df, per_instance, summary


