# =============================================================================
# TAGUCHI L9 PARAMETER SCREENING
# =============================================================================
# Paste as a new cell after the Phase 2 driver.
#
# Purpose. Reviewer 1's eighth comment asks how the parameters were set. The
# submitted paper listed values without saying where they came from. This cell
# runs the screening experiment that justifies them, and writes a LaTeX table.
#
# DESIGN
#   Three algorithms are screened, three factors each at three levels, using
#   the standard L9(3^4) orthogonal array: nine runs instead of the 27 a full
#   factorial would need. The array is orthogonal, so each level of each factor
#   appears the same number of times against every level of every other factor,
#   and main effects can be estimated independently.
#
#   Response: hypervolume, the primary indicator of Section \ref{sec:overall}.
#   Larger is better, so the signal-to-noise ratio is the larger-the-better
#   form,  SN = -10 log10( mean(1/y^2) ).
#
# TUNING INSTANCES ARE SEPARATE FROM TEST INSTANCES
#   Six instances are drawn with seeds NOT used in the main campaign
#   (101, 202, 303 against 11, 22, 33, 44, 55). Tuning on the instances the
#   method is then evaluated on inflates the result, and a referee who checks
#   the seed lists will notice if they overlap.
#
# Runtime: 3 algorithms x 9 runs x 6 instances x 2 replications, roughly
# 1.5 to 2 hours at the budgets below.
# =============================================================================

import itertools
import json
import os
import time

import numpy as np
import pandas as pd


# --- L9(3^4): rows are runs, columns are factors, entries are level indices
L9 = [
    [0, 0, 0], [0, 1, 1], [0, 2, 2],
    [1, 0, 1], [1, 1, 2], [1, 2, 0],
    [2, 0, 2], [2, 1, 0], [2, 2, 1],
]

TAGUCHI = {
    "instances": [("MEDIUM", 30, 101), ("MEDIUM", 50, 202),
                  ("TIGHT", 30, 303), ("TIGHT", 50, 101),
                  ("LOOSE", 30, 202), ("LOOSE", 50, 303)],
    "replications": 2,
    "grid_points": 8,
    "machines": {30: 3, 50: 4},
    "budget_seconds": {30: 8.0, 50: 12.0},
    "colors": 8, "customers": 3, "capacity": 600,
    "out_dir": "/content/drive/MyDrive/phase2_taguchi",

    "factors": {
        "FFD+SA-EDDTS": {
            "sa_alpha":   [0.90, 0.95, 0.99],
            "tabu_tenure": [10, 15, 20],
            "penalty":    [1.0, 5.0, 25.0],
        },
        "ALNS": {
            "decay":      [0.7, 0.8, 0.9],
            "iterations": [1000, 2000, 4000],
            "penalty":    [20.0, 100.0, 500.0],
        },
        "NSGA-II": {
            "pop_size":   [50, 100, 200],
            "p_c":        [0.7, 0.8, 0.9],
            "eta_c":      [10, 20, 30],
        },
    },
}


def _apply_factors(method, factor_names, levels, cfg):
    """Push the chosen levels into the globals the algorithms read."""
    chosen = {}
    for fname, li in zip(factor_names, levels):
        val = cfg["factors"][method][fname][li]
        chosen[fname] = val
        globals()[GLOBAL_OF[(method, fname)]] = val
    return chosen


# Factor name -> the global the algorithm actually reads. These were verified
# against the source: several parameters were hard-coded inside the functions
# and had to be exposed first. A screening script that sets a global no
# function reads produces a factor with a near-zero range and an apparently
# meaningless result, so the mapping is stated explicitly here rather than
# inferred from the factor names.
GLOBAL_OF = {
    ("FFD+SA-EDDTS", "sa_alpha"):    "SA_COOLING_RATE",
    ("FFD+SA-EDDTS", "tabu_tenure"): "TABU_TENURE",
    ("FFD+SA-EDDTS", "penalty"):     "EDDTS_PENALTY",
    ("ALNS", "decay"):               "ALNS_DECAY",
    ("ALNS", "iterations"):          "ALNS_MAX_ITERATIONS",
    ("ALNS", "penalty"):             "ALNS_PENALTY_START",
    ("NSGA-II", "pop_size"):         "NSGA2_POP_SIZE",
    ("NSGA-II", "p_c"):              "NSGA2_CROSSOVER_PROB",
    ("NSGA-II", "eta_c"):            "NSGA2_ETA_C",
}


def check_globals(cfg=TAGUCHI):
    """Confirm every factor maps to a global that exists before committing
    two hours to the screening."""
    missing = []
    for method, factors in cfg["factors"].items():
        for fname in factors:
            gname = GLOBAL_OF.get((method, fname))
            if gname is None or gname not in globals():
                missing.append(f"{method}.{fname} -> {gname}")
    if missing:
        print("MISSING GLOBALS -- these factors would be silently ignored:")
        for m in missing:
            print("  " + m)
    else:
        print("All factors map to existing globals.")
    return not missing


def run_taguchi(cfg=TAGUCHI, methods=None, resume=True, verbose=True):
    """Nine runs per algorithm over the tuning instances, checkpointed."""
    os.makedirs(cfg["out_dir"], exist_ok=True)
    ckpt = os.path.join(cfg["out_dir"], "taguchi.json")
    done = json.load(open(ckpt)) if (resume and os.path.exists(ckpt)) else {}

    methods = methods or list(cfg["factors"])
    t0 = time.time()

    for method in methods:
        fnames = list(cfg["factors"][method])
        for run_idx, levels in enumerate(L9):
            key = f"{method}|run{run_idx}"
            if key in done:
                continue

            chosen = _apply_factors(method, fnames, levels, cfg)
            if verbose:
                print(f"[{method}] run {run_idx + 1}/9  {chosen}", flush=True)

            hvs = []
            for preset, size, seed in cfg["instances"]:
                sub = dict(cfg)
                sub["methods"] = [method]
                fronts_by_rep = []
                for rep in range(cfg["replications"]):
                    fronts, _ = run_one(preset, size, seed, rep, sub)
                    fronts_by_rep.append(fronts.get(method, []))

                pool = [np.array(f) for f in fronts_by_rep if f]
                if not pool:
                    continue
                ideal, nadir = bounds_from_fronts(pool)
                for f in pool:
                    hvs.append(hypervolume_2d(
                        normalize_front(non_dominated(f), ideal, nadir)))

            done[key] = {"method": method, "run": run_idx,
                         "levels": dict(zip(fnames, levels)),
                         "values": chosen,
                         "hv_mean": float(np.mean(hvs)) if hvs else float("nan"),
                         "hv_all": [float(h) for h in hvs]}
            json.dump(done, open(ckpt, "w"))
            if verbose:
                print(f"    HV = {done[key]['hv_mean']:.4f}  "
                      f"({(time.time()-t0)/60:.0f} min elapsed)", flush=True)

    print(f"\nScreening finished in {(time.time()-t0)/60:.1f} min")
    return done


def analyse_taguchi(done, cfg=TAGUCHI):
    """Main effects, signal-to-noise ratios, retained levels, LaTeX table."""
    rows = [v for v in done.values()]
    df = pd.DataFrame(rows)
    retained = {}

    for method in df["method"].unique():
        sub = df[df["method"] == method]
        fnames = list(cfg["factors"][method])

        print("\n" + "=" * 68)
        print(f"{method}: main effects on hypervolume (larger is better)")
        print("=" * 68)

        best = {}
        for fname in fnames:
            print(f"\n  {fname}")
            eff = []
            for li, val in enumerate(cfg["factors"][method][fname]):
                mask = sub["levels"].apply(lambda d: d[fname] == li)
                ys = np.concatenate([np.array(h) for h in sub[mask]["hv_all"]
                                     if len(h)]) if mask.any() else np.array([])
                if ys.size == 0:
                    continue
                mean_hv = ys.mean()
                # larger-the-better signal-to-noise
                sn = -10 * np.log10(np.mean(1.0 / np.square(ys)))
                eff.append((val, mean_hv, sn))
                print(f"    level {val!s:>8}   HV = {mean_hv:.4f}   S/N = {sn:+.2f}")
            if eff:
                bv = max(eff, key=lambda t: t[1])
                best[fname] = bv[0]
                delta = max(e[1] for e in eff) - min(e[1] for e in eff)
                print(f"    -> retained {bv[0]}   (range of means: {delta:.4f})")
        retained[method] = best

    print("\n" + "=" * 68)
    print("RETAINED SETTINGS")
    print("=" * 68)
    for m, b in retained.items():
        print(f"  {m:<14} {b}")

    # --- LaTeX
    lines = [r"\begin{table}[htbp]", r"\centering",
             r"\caption{Taguchi $L_9(3^3)$ parameter screening. Mean "
             r"hypervolume over six tuning instances disjoint from the test "
             r"set, two replications each. The retained level is the one with "
             r"the highest mean response; the range is the spread of the "
             r"factor's level means and indicates its influence.}",
             r"\label{tab:taguchi}", r"\small",
             r"\begin{tabular}{llccc}", r"\toprule",
             r"\textbf{Algorithm} & \textbf{Factor} & \textbf{Levels} "
             r"& \textbf{Retained} & \textbf{Range} \\", r"\midrule"]
    for method in df["method"].unique():
        sub = df[df["method"] == method]
        fnames = list(cfg["factors"][method])
        for i, fname in enumerate(fnames):
            means = []
            for li in range(3):
                mask = sub["levels"].apply(lambda d: d[fname] == li)
                ys = np.concatenate([np.array(h) for h in sub[mask]["hv_all"]
                                     if len(h)]) if mask.any() else np.array([])
                means.append(ys.mean() if ys.size else np.nan)
            rng = np.nanmax(means) - np.nanmin(means)
            lvl = ", ".join(str(v) for v in cfg["factors"][method][fname])
            name = method if i == 0 else ""
            lines.append(f"{name} & {fname.replace('_', ' ')} & {lvl} & "
                         f"{retained[method][fname]} & {rng:.4f} \\\\")
        lines.append(r"\addlinespace")
    lines += [r"\bottomrule", r"\end{tabular}", r"\end{table}"]
    latex = "\n".join(lines)

    out = os.path.join(cfg["out_dir"], "taguchi_table.tex")
    open(out, "w").write(latex)
    print(f"\nLaTeX table written to {out}\n")
    print(latex)
    return df, retained, latex


print("Taguchi driver loaded.")
print("  run_taguchi()                 -- 27 runs, checkpointed")
print("  analyse_taguchi(done_taguchi) -- main effects + LaTeX table")
print()
print("Before running, check that the globals in _apply_factors() match the")
print("names your algorithms actually read. If a name is wrong the factor")
print("will be silently ignored and its range will come out near zero.")

