# =============================================================================
# FIGURES FOR THE MANUSCRIPT
# =============================================================================
# Paste as a new cell after the Phase 2 driver. Requires:
#   done      -- the campaign dictionary (raw_fronts.json)
#   per_inst  -- the second return value of analyse_campaign()
#
# Produces three PDF figures at publication quality:
#   fig_scaling.pdf   hypervolume against instance size, per method
#   fig_fronts.pdf    representative approximation fronts on one instance
#   fig_cd.pdf        critical difference diagram (Friedman + Nemenyi)
#
# Style choices are deliberate. Vector PDF rather than raster, so the figures
# survive typesetting at any column width. Serif fonts to match the body text.
# No colour dependence: every series is distinguishable by marker and line
# style alone, since journals still print in greyscale and roughly one reader
# in twelve has some form of colour vision deficiency.
# =============================================================================

import json
import os

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd

plt.rcParams.update({
    "font.family": "serif",
    "font.size": 9,
    "axes.labelsize": 9,
    "axes.titlesize": 9,
    "legend.fontsize": 8,
    "xtick.labelsize": 8,
    "ytick.labelsize": 8,
    "axes.grid": True,
    "grid.alpha": 0.3,
    "grid.linewidth": 0.5,
    "axes.axisbelow": True,
    "figure.dpi": 150,
    "savefig.bbox": "tight",
    "savefig.pad_inches": 0.02,
})

# Distinguishable without colour: marker + linestyle carry the information
STYLE = {
    "FFD+SA-EDDTS": dict(marker="o", ls="-",  color="#1b1b1b", ms=5, lw=1.6),
    "ALNS":         dict(marker="s", ls="--", color="#5a5a5a", ms=4.5, lw=1.2),
    "NSGA-II":      dict(marker="^", ls="-.", color="#8a8a8a", ms=4.5, lw=1.2),
    "LPT+EDD":      dict(marker="v", ls=":",  color="#b0b0b0", ms=4.5, lw=1.2),
}
ORDER = ["FFD+SA-EDDTS", "ALNS", "NSGA-II", "LPT+EDD"]


# -----------------------------------------------------------------------------
# Figure 1 -- scaling
# -----------------------------------------------------------------------------

def fig_scaling(per_inst, out_dir, fname="fig_scaling.pdf"):
    """Hypervolume against instance size, mean over instances with the
    standard deviation as a shaded band.

    This is the figure that carries the paper's main finding: the proposed
    method holds its performance as instances grow while the benchmarks fall
    away, so the gap widens with size rather than narrowing.
    """
    fig, ax = plt.subplots(figsize=(4.4, 3.1))
    sizes = sorted(per_inst["size"].unique())

    for method in ORDER:
        sub = per_inst[per_inst["method"] == method]
        if sub.empty:
            continue
        m = [sub[sub["size"] == s]["HV"].mean() for s in sizes]
        sd = [sub[sub["size"] == s]["HV"].std() for s in sizes]
        st = STYLE[method]
        ax.plot(sizes, m, label=method, **st)
        ax.fill_between(sizes, np.array(m) - np.array(sd),
                        np.array(m) + np.array(sd),
                        color=st["color"], alpha=0.10, linewidth=0)

    ax.set_xlabel("Number of jobs $n$")
    ax.set_ylabel("Hypervolume")
    ax.set_xticks(sizes)
    ax.legend(frameon=False, loc="center left", bbox_to_anchor=(0.02, 0.42))
    fig.savefig(os.path.join(out_dir, fname))
    plt.close(fig)
    print(f"  {fname}")


# -----------------------------------------------------------------------------
# Figure 2 -- representative fronts
# -----------------------------------------------------------------------------

def fig_fronts(done, out_dir, instance_key=None, rep=0,
               fname="fig_fronts.pdf", show_title=False):
    """Approximation fronts of every method on one instance.

    A single instance is shown rather than an average, because averaging
    Pareto fronts is not meaningful: the mean of two fronts is generally not
    a front. The instance is chosen as the largest available, since that is
    where the methods differ most.
    """
    if instance_key is None:
        # largest n, then first key alphabetically for reproducibility
        instance_key = sorted(
            done.keys(),
            key=lambda k: (-int(k.split("_")[1]), k))[0]

    fronts = done[instance_key]["replications"][rep]
    fig, ax = plt.subplots(figsize=(4.4, 3.3))

    for method in ORDER:
        pts = fronts.get(method, [])
        if not pts:
            continue
        nd = non_dominated(np.array(pts))
        nd = nd[np.argsort(nd[:, 0])]
        st = dict(STYLE[method])
        if len(nd) == 1:
            ax.plot(nd[:, 0], nd[:, 1], marker=st["marker"],
                    color=st["color"], ms=st["ms"] + 2, ls="none",
                    label=f"{method} (single point)")
        else:
            ax.plot(nd[:, 0], nd[:, 1], label=method, **st)

    ax.set_xlabel(r"Total tardiness $\sum_j T_j$ (hours)")
    ax.set_ylabel(r"Total setup time $\sum S$ (hours)")
    if show_title:
        ax.set_title(instance_key.replace("_", " / "), fontsize=8, pad=6)
    ax.legend(frameon=False, loc="upper right")

    # Direction-of-improvement arrow, placed away from the lower-left corner:
    # the proposed method's front sits there and the arrow was overplotting it.
    ax.annotate("better", xy=(0.14, 0.14), xytext=(0.38, 0.32),
                xycoords="axes fraction", textcoords="axes fraction",
                fontsize=7.5, ha="center", va="center",
                arrowprops=dict(arrowstyle="->", lw=0.8, color="#555555"))

    fig.savefig(os.path.join(out_dir, fname))
    plt.close(fig)
    print(f"  {fname}  (instance {instance_key})")


def pick_front_instance(done, method="FFD+SA-EDDTS", min_points=3):
    """Choose the instance and replication that best illustrates the fronts.

    LPT+EDD is excluded from the criterion because it returns a single point
    by construction; including it fixes the minimum at one, which is what an
    earlier version of this selection did and why it produced a figure in
    which the proposed method appeared as a lone dot.
    """
    cand = []
    for key, entry in done.items():
        for ri, rep in enumerate(entry["replications"]):
            nd = {m: len(non_dominated(np.array(v)))
                  for m, v in rep.items() if v}
            if len(nd) < 4 or nd.get(method, 0) < min_points:
                continue
            search = {m: n for m, n in nd.items() if m != "LPT+EDD"}
            cand.append((min(search.values()), sum(search.values()),
                         key, ri, nd))
    if not cand:
        return None, 0, {}
    cand.sort(reverse=True)
    _, _, key, ri, nd = cand[0]
    return key, ri, nd


# -----------------------------------------------------------------------------
# Figure 3 -- critical difference diagram
# -----------------------------------------------------------------------------

def fig_critical_difference(per_inst, out_dir, alpha_q=2.569,
                            fname="fig_cd.pdf"):
    """Demsar-style critical difference diagram.

    Methods are placed on an axis of mean Friedman rank; those whose ranks
    differ by less than the Nemenyi critical difference are joined by a bar,
    indicating that the test does not separate them.
    """
    pivot = per_inst.pivot_table(index=["preset", "size", "seed"],
                                 columns="method", values="HV")
    methods = [m for m in ORDER if m in pivot.columns]
    X = pivot[methods].dropna().values
    n, k = X.shape

    from scipy import stats as sstats
    ranks = np.array([sstats.rankdata(-row) for row in X]).mean(axis=0)
    cd = alpha_q * np.sqrt(k * (k + 1) / (6.0 * n))

    order = np.argsort(ranks)
    names = [methods[i] for i in order]
    rk = ranks[order]

    n_left = int(np.ceil(k / 2))
    depth_max = 0.45 + 0.42 * (max(n_left, k - n_left) - 1)
    fig, ax = plt.subplots(figsize=(5.2, 0.95 + 0.30 * k))
    lo, hi = 0.7, k + 0.3
    ax.set_xlim(lo, hi)                       # rank 1 (best) on the left
    ax.set_ylim(-(depth_max + 0.25), 1.15)
    ax.axis("off")

    ax.plot([lo, hi], [0, 0], color="black", lw=1.0)
    for t in range(1, k + 1):
        ax.plot([t, t], [0, 0.09], color="black", lw=0.9)
        ax.text(t, 0.16, str(t), ha="center", va="bottom", fontsize=8)

    for i, (nm, r) in enumerate(zip(names, rk)):
        left = i < n_left
        depth = -(0.45 + 0.42 * (i if left else k - 1 - i))
        xend = lo + 0.10 if left else hi - 0.10
        ax.plot([r, r], [0, depth], color="black", lw=0.8)
        ax.plot([r, xend], [depth, depth], color="black", lw=0.8)
        ax.text(xend, depth,
                f"{nm} ({r:.2f}) " if left else f" {nm} ({r:.2f})",
                ha="right" if left else "left", va="center", fontsize=8)

    # bars joining groups the test does not separate
    level = 0.30
    for i in range(k):
        j = i
        while j + 1 < k and rk[j + 1] - rk[i] < cd:
            j += 1
        if j > i:
            ax.plot([rk[i] - 0.02, rk[j] + 0.02], [level, level],
                    color="black", lw=3.0, solid_capstyle="butt")
            level += 0.17

    x0 = lo + 0.15
    ax.plot([x0, x0 + cd], [0.85, 0.85], color="black", lw=1.2)
    ax.plot([x0, x0], [0.81, 0.89], color="black", lw=1.0)
    ax.plot([x0 + cd, x0 + cd], [0.81, 0.89], color="black", lw=1.0)
    ax.text(x0 + cd / 2, 0.93, f"CD = {cd:.3f}",
            ha="center", va="bottom", fontsize=8)

    fig.savefig(os.path.join(out_dir, fname))
    plt.close(fig)
    print(f"  {fname}  (CD = {cd:.4f}, n = {n}, k = {k})")
    return dict(zip(names, rk.round(3))), cd


# -----------------------------------------------------------------------------
# Driver
# -----------------------------------------------------------------------------

def make_all_figures(done, per_inst, out_dir=None):
    out_dir = out_dir or (CAMPAIGN["out_dir"] + "/figures")
    os.makedirs(out_dir, exist_ok=True)
    print(f"Writing figures to {out_dir}")
    fig_scaling(per_inst, out_dir)
    key, ri, nd = pick_front_instance(done)
    if key is None:
        print("  no instance where the proposed method produced a "
              "multi-point front; using the largest instance instead")
        fig_fronts(done, out_dir)
    else:
        print(f"  front figure uses {key}, replication {ri}: {nd}")
        fig_fronts(done, out_dir, instance_key=key, rep=ri)
    ranks, cd = fig_critical_difference(per_inst, out_dir)
    print("\nMean ranks:", ranks)
    print(f"Critical difference: {cd:.4f}")
    return out_dir


