# =============================================================================
# SENSITIVITY ANALYSIS -- setup matrix parameters lambda and rho_h
# =============================================================================
# Paste as a new cell AFTER the Phase 2 driver cell.
#
# Purpose. The asymmetric setup matrix of Eq. (setup_matrix) carries two
# parameters that are modelling choices rather than measured quantities:
#   lambda : how strongly a transition towards a LIGHTER shade is penalised
#   rho_h  : the staining multiplier for chromatic families
# Reviewer 1's comment 10 asks for the limitations of the study, and any
# reviewer will ask how much of the result rests on those two numbers. This
# campaign answers that.
#
# Two claims are being tested.
#   C1  lambda = 0, rho_h = 1 reproduces the previous row-constant matrix
#       exactly, so the earlier specification is a special case. The
#       run at that setting is therefore also the "old model" reference.
#   C2  the ranking of the methods is stable across the parameter grid, i.e.
#       the conclusion of Section 5 does not depend on the chosen values.
#
# Note on comparability. Changing lambda or rho_h changes the instances
# themselves, so hypervolumes are NOT comparable ACROSS configurations in
# absolute terms -- each configuration has its own objective scale. What is
# comparable within a configuration is the RANKING of the methods and the
# shape of the trade-off. The table below therefore reports, per
# configuration, the mean HV of each method and the resulting rank order.
# =============================================================================

import itertools
import json
import os
import time

import numpy as np
import pandas as pd


SENS = {
    # one-factor-at-a-time around the baseline (lambda = 1.0, rho_h = 1.8)
    "lambda_levels": [0.0, 0.5, 1.0, 2.0],
    "rho_levels": [1.0, 1.4, 1.8],
    "baseline_lambda": 1.0,
    "baseline_rho": 1.8,

    "presets": ["MEDIUM"],
    "sizes": [30, 50],
    "seeds": [11, 22, 33],
    "replications": 2,
    "grid_points": 8,
    "machines": {30: 3, 50: 4},
    "budget_seconds": {30: 8.0, 50: 12.0},
    "colors": 8,
    "customers": 3,
    "capacity": 600,
    "methods": ["FFD+SA-EDDTS", "ALNS", "NSGA-II"],
    "out_dir": "/content/drive/MyDrive/phase2_sensitivity",
}


def set_setup_parameters(lam, rho_h):
    """Rebuild every module-level object that depends on the setup matrix.

    setup_time() reads LAMBDA_ASYM and RHO_H at call time, so the generator
    picks the new values up automatically; SETUP_MATRIX and
    SETUP_TIMES_BY_COLOR are cached constants and must be rebuilt explicitly.
    """
    globals()["LAMBDA_ASYM"] = float(lam)
    globals()["RHO_H"] = float(rho_h)
    globals()["SETUP_MATRIX"] = generate_setup_matrix(lam=lam, rho_h=rho_h)
    globals()["SETUP_TIMES_BY_COLOR"] = {
        c: base_setup_time(c) for c in COLOR_ORDER}
    globals()["SETUP_TIMES_BY_COLOR_GEN"] = globals()["SETUP_TIMES_BY_COLOR"]
    globals()["MAX_SIGMA"] = max(globals()["SETUP_MATRIX"].values())
    return globals()["SETUP_MATRIX"]


def matrix_descriptors(matrix):
    """Statistics used to characterise a configuration in the paper."""
    off = [(a, b, v) for (a, b), v in matrix.items() if a != b]
    vals = [v for _, _, v in off]
    cols = sorted({a for a, _, _ in off})
    asym = [abs(matrix[(a, b)] - matrix[(b, a)])
            for i, a in enumerate(cols) for b in cols[i + 1:]]
    return {
        "sigma_min": min(vals), "sigma_max": max(vals),
        "sigma_mean": float(np.mean(vals)),
        "ratio_max_min": max(vals) / min(vals) if min(vals) > 0 else float("inf"),
        "mean_asymmetry": float(np.mean(asym)),
        "symmetric": bool(all(a < 1e-9 for a in asym)),
    }


def run_sensitivity(cfg=SENS, resume=True, verbose=True):
    """One campaign per (lambda, rho_h) configuration, checkpointed."""
    os.makedirs(cfg["out_dir"], exist_ok=True)
    ckpt = os.path.join(cfg["out_dir"], "sensitivity.json")
    done = json.load(open(ckpt)) if (resume and os.path.exists(ckpt)) else {}

    configs = ([(l, cfg["baseline_rho"]) for l in cfg["lambda_levels"]]
               + [(cfg["baseline_lambda"], r) for r in cfg["rho_levels"]])
    configs = list(dict.fromkeys(configs))          # drop the duplicate
    # ensure the "old model" corner is present
    if (0.0, 1.0) not in configs:
        configs.insert(0, (0.0, 1.0))

    print(f"{len(configs)} configuration(s):")
    for l, r in configs:
        tag = "  (old symmetric model)" if (l == 0.0 and r == 1.0) else ""
        print(f"  lambda={l:.1f}  rho_h={r:.1f}{tag}")

    cells = list(itertools.product(cfg["presets"], cfg["sizes"], cfg["seeds"]))
    t_start = time.time()

    for ci, (lam, rho) in enumerate(configs, 1):
        ckey = f"L{lam}_R{rho}"
        if ckey in done:
            continue

        matrix = set_setup_parameters(lam, rho)
        desc = matrix_descriptors(matrix)
        if verbose:
            print(f"\n[{ci}/{len(configs)}] lambda={lam}, rho_h={rho}  "
                  f"sigma in [{desc['sigma_min']:.2f}, {desc['sigma_max']:.2f}], "
                  f"asymmetry {desc['mean_asymmetry']:.3f}", flush=True)

        per_instance = {}
        for preset, size, seed in cells:
            reps = []
            for rep in range(cfg["replications"]):
                fronts, _ = run_one(preset, size, seed, rep, cfg)
                reps.append({m: [list(p) for p in f] for m, f in fronts.items()})
            per_instance[f"{preset}_{size}_{seed}"] = {"replications": reps}

        done[ckey] = {"lambda": lam, "rho_h": rho,
                      "descriptors": desc, "instances": per_instance}
        json.dump(done, open(ckpt, "w"))

        el = time.time() - t_start
        if verbose:
            print(f"    done, {el/60:.1f} min elapsed, "
                  f"~{el/ci*(len(configs)-ci)/60:.0f} min left", flush=True)

    # restore the baseline so later cells are unaffected
    set_setup_parameters(cfg["baseline_lambda"], cfg["baseline_rho"])
    print(f"\nSensitivity campaign finished in {(time.time()-t_start)/60:.1f} min")
    print("Setup parameters restored to baseline "
          f"(lambda={cfg['baseline_lambda']}, rho_h={cfg['baseline_rho']})")
    return done


def analyse_sensitivity(done, cfg=SENS):
    """Per-configuration indicator means and a ready-to-paste LaTeX table."""
    rows = []
    for ckey, entry in done.items():
        for ikey, inst in entry["instances"].items():
            reps = inst["replications"]
            all_fronts = [np.array(f) for r in reps for f in r.values() if f]
            if not all_fronts:
                continue
            ideal, nadir = bounds_from_fronts(all_fronts)
            ref = non_dominated(normalize_front(np.vstack(all_fronts),
                                                ideal, nadir))
            for r in reps:
                for method, front in r.items():
                    if not front:
                        continue
                    f = normalize_front(non_dominated(front), ideal, nadir)
                    rows.append({
                        "lambda": entry["lambda"], "rho_h": entry["rho_h"],
                        "instance": ikey, "method": method,
                        "HV": hypervolume_2d(f),
                        "IGDp": igd_plus(f, ref),
                        "ND": len(f),
                        "setup_span": (max(p[1] for p in front)
                                       - min(p[1] for p in front)),
                    })

    df = pd.DataFrame(rows)
    if df.empty:
        print("No results.")
        return df, ""

    agg = (df.groupby(["lambda", "rho_h", "method"])[["HV", "ND", "setup_span"]]
             .mean().round(4).reset_index())

    print("\n" + "=" * 74)
    print("SENSITIVITY: mean hypervolume by configuration")
    print("=" * 74)
    pivot = agg.pivot_table(index=["lambda", "rho_h"], columns="method",
                            values="HV").round(4)
    print(pivot)

    print("\nRank order within each configuration (1 = best):")
    ranks = pivot.rank(axis=1, ascending=False).astype(int)
    print(ranks)
    stable = ranks.nunique().eq(1).all() if len(ranks) > 1 else True
    print(f"\nRanking stable across all configurations: {stable}")

    print("\nSetup-objective span of the fronts (mean, raw hours):")
    print(agg.pivot_table(index=["lambda", "rho_h"], columns="method",
                          values="setup_span").round(3))

    # --- LaTeX table
    methods = [m for m in cfg["methods"] if m in pivot.columns]
    lines = [
        r"\begin{table}[htbp]", r"\centering",
        r"\caption{Sensitivity of the results to the setup-matrix parameters. "
        r"Mean hypervolume over six instances (MEDIUM tightness, "
        r"$n \in \{30,50\}$, three seeds) with two replications each. "
        r"Hypervolumes are comparable within a row but not across rows, since "
        r"each configuration defines a different instance. The rank order is "
        r"the quantity of interest.}",
        r"\label{tab:sensitivity}", r"\small",
        r"\begin{tabular}{ll" + "c" * len(methods) + "c}",
        r"\toprule",
        r"$\lambda$ & $\rho_h$ & " + " & ".join(methods)
        + r" & $\sigma$ range \\", r"\midrule",
    ]
    for (lam, rho), r in pivot.iterrows():
        d = next(e["descriptors"] for e in done.values()
                 if e["lambda"] == lam and e["rho_h"] == rho)
        note = r" \textsuperscript{a}" if (lam == 0.0 and rho == 1.0) else ""
        lines.append(
            f"{lam:.1f}{note} & {rho:.1f} & "
            + " & ".join(f"{r[m]:.3f}" for m in methods)
            + f" & [{d['sigma_min']:.2f}, {d['sigma_max']:.2f}] \\\\")
    lines += [
        r"\bottomrule", r"\end{tabular}",
        r"\par\smallskip\footnotesize\textsuperscript{a} $\lambda = 0$, "
        r"$\rho_h = 1$ reproduces the row-constant matrix of the "
        r"original specification.",
        r"\end{table}",
    ]
    latex = "\n".join(lines)

    out = os.path.join(cfg["out_dir"], "sensitivity_table.tex")
    open(out, "w").write(latex)
    print(f"\nLaTeX table written to {out}\n")
    print(latex)

    df.to_csv(os.path.join(cfg["out_dir"], "sensitivity_raw.csv"), index=False)
    return df, latex


print("Sensitivity driver loaded.")
print("  run_sensitivity()          -- 6 configurations, checkpointed")
print("  analyse_sensitivity(done)  -- tables + LaTeX")
print()
print("Estimated runtime: 6 configurations x 6 instances x 2 replications")
print("x 3 methods, roughly 1.5-2 hours.")

