# =============================================================================
# GANTT CHARTS OF THE TWO ENDS OF A PARETO FRONT
# =============================================================================
# Paste as a new cell after the figure driver. Produces fig_gantt.pdf.
#
# Purpose. Every result in the paper is an aggregate: hypervolumes, ranks,
# indicator means. A reader who has followed all of it still has no picture of
# what the trade-off looks like on the shop floor. Two Gantt charts of the
# same instance, one from each end of the front, supply that picture in a way
# no indicator can.
#
# The two panels share an instance, a job set and a time axis, so the only
# thing that differs between them is the schedule. Reading down the panels,
# the low-setup schedule groups colours into long same-colour runs and pays
# for it in delivery; the low-tardiness schedule interleaves colours to meet
# due dates and pays for it in cleaning cycles.
# =============================================================================

import os

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import matplotlib.patches as mpatches
import numpy as np

plt.rcParams.update({
    "font.family": "serif", "font.size": 9,
    "axes.labelsize": 9, "axes.titlesize": 9,
    "xtick.labelsize": 8, "ytick.labelsize": 8,
    "figure.dpi": 150, "savefig.bbox": "tight", "savefig.pad_inches": 0.02,
})

# Greyscale ramp ordered by colour depth, so the visual darkness of a bar
# matches the shade it represents. Setup blocks are hatched rather than
# shaded, so they read as "not production" even in black and white.
DEPTH_GREY = {
    "ecru": 0.93, "pink": 0.84, "light": 0.76, "medium": 0.64,
    "pastel": 0.54, "brown": 0.42, "beige": 0.30, "dark": 0.18,
}


def _walk(schedule, setup_matrix):
    """Recompute the timeline of a schedule, returning drawable blocks."""
    rows = []
    for mi, machine in enumerate(schedule):
        prev, clock = None, 0.0
        for b in machine.get("batches", []):
            fam = b.get("family", b.get("color"))
            s = 0.0 if prev is None else setup_matrix.get((prev, fam), 0.0)
            if s > 0:
                rows.append(dict(machine=mi, start=clock, dur=s,
                                 kind="setup", family=fam))
            clock += s
            rows.append(dict(machine=mi, start=clock, dur=b["proc_time"],
                             kind="batch", family=fam,
                             njobs=len(b.get("jobs", []))))
            clock += b["proc_time"]
            prev = fam
    return rows


def _panel(ax, rows, n_machines, title, xmax):
    for r in rows:
        y = n_machines - 1 - r["machine"]
        if r["kind"] == "setup":
            ax.broken_barh([(r["start"], r["dur"])], (y - 0.30, 0.60),
                           facecolor="white", edgecolor="0.35",
                           hatch="////", linewidth=0.6, zorder=2)
        else:
            g = DEPTH_GREY.get(r["family"], 0.6)
            ax.broken_barh([(r["start"], r["dur"])], (y - 0.34, 0.68),
                           facecolor=str(g), edgecolor="0.25",
                           linewidth=0.6, zorder=3)
            if r["dur"] > xmax * 0.045:
                ax.text(r["start"] + r["dur"] / 2, y,
                        f"{r['family'][:4]}\n{r['njobs']}",
                        ha="center", va="center", fontsize=6,
                        color="black" if g > 0.5 else "white", zorder=4)

    ax.set_yticks(range(n_machines))
    ax.set_yticklabels([f"V{n_machines - i}" for i in range(n_machines)])
    ax.set_ylim(-0.6, n_machines - 0.4)
    ax.set_xlim(0, xmax)
    ax.set_title(title, fontsize=8.5, pad=4, loc="left")
    ax.grid(axis="x", alpha=0.25, linewidth=0.5)
    ax.set_axisbelow(True)


def fig_gantt(schedule_low_tard, schedule_low_setup, setup_matrix,
              n_machines, labels, out_dir, fname="fig_gantt.pdf"):
    """Two panels, same instance, opposite ends of the front.

    `labels` is a pair of (tardiness, setup) tuples used in the panel titles.
    """
    rows_a = _walk(schedule_low_tard, setup_matrix)
    rows_b = _walk(schedule_low_setup, setup_matrix)
    xmax = max(r["start"] + r["dur"] for r in rows_a + rows_b) * 1.02

    fig, axes = plt.subplots(2, 1, figsize=(6.4, 4.6), sharex=True)
    (t1, s1), (t2, s2) = labels
    _panel(axes[0], rows_a, n_machines,
           f"(a) low-tardiness end:  $\\sum T_j$ = {t1:.1f} h,  "
           f"$\\sum S$ = {s1:.2f} h", xmax)
    _panel(axes[1], rows_b, n_machines,
           f"(b) low-setup end:  $\\sum T_j$ = {t2:.1f} h,  "
           f"$\\sum S$ = {s2:.2f} h", xmax)
    axes[1].set_xlabel("Time (hours)")
    fig.text(0.02, 0.5, "Dye vessel", va="center", rotation="vertical",
             fontsize=9)

    handles = [mpatches.Patch(facecolor="0.55", edgecolor="0.25",
                              label="batch: shade and number of lots"),
               mpatches.Patch(facecolor="white", edgecolor="0.35",
                              hatch="////", label="cleaning changeover")]
    # Below the axes rather than inside them: an in-axes legend covers the
    # bars it is meant to explain.
    fig.legend(handles=handles, frameon=False, fontsize=7.5, ncol=2,
               loc="lower center", bbox_to_anchor=(0.55, -0.03))

    os.makedirs(out_dir, exist_ok=True)
    fig.savefig(os.path.join(out_dir, fname))
    plt.close(fig)
    print(f"  {fname}")


# -----------------------------------------------------------------------------
# Driver: regenerate the two end schedules and draw them
# -----------------------------------------------------------------------------

def make_gantt_figure(preset="MEDIUM", size=50, seed=22, out_dir=None):
    """Solve one instance at both ends of the front and draw both schedules.

    A moderate instance is used rather than the largest: at 100 jobs the bars
    are too thin to read, and the point of the figure is legibility rather
    than scale.
    """
    out_dir = out_dir or (CAMPAIGN["out_dir"] + "/figures")
    n_mach = CAMPAIGN["machines"][size]

    gen = RandomInstanceGenerator.from_preset(
        preset, num_jobs=size, num_machines=n_mach,
        num_colors=CAMPAIGN["colors"], num_customers=CAMPAIGN["customers"],
        machine_capacity=CAMPAIGN["capacity"], seed=seed)
    jobs, machines, meta, sm = gen.generate()
    batches = simplified_ffd(jobs, machines, sm)

    budget = CAMPAIGN["budget_seconds"][size]

    # Both ends are produced the way the front itself is produced: by
    # minimising tardiness under an epsilon bound on setup. The unconstrained
    # run gives the low-tardiness end; tightening the bound to a fraction of
    # the setup it achieved walks the search to the other end. Minimising
    # setup directly is avoided here because that branch of the heuristic does
    # not reliably improve on the setup found by the tardiness run.
    res_t = eddts_scheduling_epsilon(
        batches, machines, sm, primary_objective="tardiness",
        epsilon_value=1e9, range_primary=200.0, range_secondary=3.0,
        time_limit=budget)
    t1, s1 = calculate_objectives(res_t[0], res_t[1])

    res_s, t2, s2 = None, None, None
    for frac in (0.55, 0.65, 0.75, 0.85):
        cand = eddts_scheduling_epsilon(
            batches, machines, sm, primary_objective="tardiness",
            epsilon_value=s1 * frac, range_primary=200.0,
            range_secondary=max(s1 * (1 - frac), 0.5), time_limit=budget)
        ct, cs = calculate_objectives(cand[0], cand[1])
        if cs <= s1 * frac + 1e-6:          # the bound must actually hold
            res_s, t2, s2 = cand, ct, cs
            break
    if res_s is None:
        raise RuntimeError("no feasible low-setup schedule found; "
                           "loosen the fractions above")
    print(f"  instance {preset}/{size}/{seed}")
    print(f"  low tardiness: T={t1:.1f}  S={s1:.2f}")
    print(f"  low setup    : T={t2:.1f}  S={s2:.2f}")

    fig_gantt(res_t[0], res_s[0], sm, n_mach, [(t1, s1), (t2, s2)], out_dir)
    return (t1, s1), (t2, s2)


print("Gantt driver loaded.  Run:  make_gantt_figure()")
